insert into public.catalog_classes (id,name_pt,name_en,description_pt,hp_per_level,key_attributes,traits,ruleset,source_book,source_page,system_id,data) values
('dnd35.defensores.prestige.defensores-cacador-dos-mortos','Caçador dos Mortos','Caçador dos Mortos','Bônus Base de Ataque: +5. Tendência: Qualquer uma, exceto Mau. Conhecimento (mortos-vivos): 5 graduações. Especial: Capacidade de Expulsar Mortos-vivos. Cicatriz da não-vida: O personagem deve ter perdido um nível ou um ponto permanente de habilidade drenado por um morto-vivo. Essa é a cicatriz da não-vida, que todos os caçadores dos mortos carregam.',8,ARRAY[]::text[],ARRAY['prestige']::text[],'v35-defensores','D&D 3.5 — Defensores da Fé',51,'dnd35','{"id":"defensores-cacador-dos-mortos","name":"Caçador dos Mortos","hitDie":8,"requirements":["Bônus Base de Ataque: +5.","Tendência: Qualquer uma, exceto Mau.","Conhecimento (mortos-vivos): 5 graduações.","Especial: Capacidade de Expulsar Mortos-vivos.","Cicatriz da não-vida: O personagem deve ter perdido um nível ou um ponto permanente de habilidade drenado por um morto-vivo. Essa é a cicatriz da não-vida, que todos os caçadores dos mortos carregam."],"classSkills":["Concentração (Con)","Conhecimento (religião) (Int)","Conhecimento (mortos-vivos) (Int)","Cura (Sab)","Profissão (Sab)","Cavalgar (Des)","Procurar (Int)"],"skillPointsPerLevel":"2 + modificador de Inteligência","weaponArmor":"Os caçadores dos mortos sabem usar todas as armas simples e comuns, todos os tipos de armadura e escudos.","levels":[{"level":1,"bab":"+1","fort":"+2","ref":"+0","will":"+0","special":"Detectar mortos-vivos","spellsPerDay":[0,null,null,null]},{"level":2,"bab":"+2","fort":"+3","ref":"+0","will":"+0","special":"Destruir mortos-vivos","spellsPerDay":[1,null,null,null]},{"level":3,"bab":"+3","fort":"+3","ref":"+1","will":"+1","special":"Ignorar o toque da morte","spellsPerDay":[1,0,null,null]},{"level":4,"bab":"+4","fort":"+4","ref":"+1","will":"+1","special":"","spellsPerDay":[1,1,null,null]},{"level":5,"bab":"+5","fort":"+4","ref":"+1","will":"+1","special":"Morte definitiva","spellsPerDay":[1,1,0,null]},{"level":6,"bab":"+6","fort":"+5","ref":"+2","will":"+2","special":"Expulsão adicional","spellsPerDay":[1,1,1,null]},{"level":7,"bab":"+7","fort":"+5","ref":"+2","will":"+2","special":"","spellsPerDay":[2,1,1,0]},{"level":8,"bab":"+8","fort":"+6","ref":"+2","will":"+2","special":"Explosão de energia positiva","spellsPerDay":[2,1,1,1]},{"level":9,"bab":"+9","fort":"+6","ref":"+3","will":"+3","special":"","spellsPerDay":[2,2,1,1]},{"level":10,"bab":"+10","fort":"+7","ref":"+3","will":"+3","special":"Corpo fechado","spellsPerDay":[2,2,2,1]}],"features":[{"name":"Magias","text":"A partir do 1º nível, um caçador dos mortos adquire a habilidade de conjurar uma pequena quantidade de magias divinas. Para conjurar magias, um personagem deve ter uma pontuação em Sabedoria igual ou superior a 10 + o nível da magia; portanto, um personagem de Sabedoria 10 ou inferior não conseguirá fazê-lo. As magias adicionais do caçador dos mortos são baseadas em Sabedoria; a Classe de Dificuldade de um teste de resistência contra essas magias equivale a 10 + nível da magia + modificador de Sabedoria. Quando um caçador recebe 0 magias de um determinado nível (como 0 magias de 1º nível logo no 1º nível de experiência), recebe apenas magias adicionais. Um personagem que não receba magias adicionais em qualquer nível ainda não é capaz de conjurá-las. Ele tem acesso a qualquer magia da lista, desde que seja capaz de lançá-la, e pode escolher livremente qual preparar. Um caçador prepara e conjura magias como um clérigo (mas não pode usar a Conversão Espontânea para lançar magias de cura no lugar de uma magia preparada)."},{"name":"Detectar mortos-vivos (SM)","text":"O caçador dos mortos pode usar detectar mortos-vivos livremente, como uma habilidade similar a magia. Essa habilidade duplica o efeito da magia detectar mortos-vivos."},{"name":"Destruir Mortos-Vivos (Sob)","text":"Uma vez por dia, um caçador dos mortos de 2º nível ou superior pode tentar destruir mortos-vivos usando um ataque regular. Ao fazê-lo, ele soma seu modificador de Sabedoria (caso seja positivo) na sua jogada de ataque, causando 1 ponto de dano adicional por nível de experiência. Por exemplo, um caçador dos mortos de 8º nível empunhando uma espada longa causaria 1d8+8 pontos de dano, além do dano devido a sua Força ou outros efeitos mágicos. Se o caçador dos mortos, acidentalmente, tentar destruir uma criatura que não seja um morto-vivo, esta característica não gera efeitos, mas não poderá ser utilizada outra vez naquele dia. Observação: Um paladino/caçador dos mortos é capaz de destruir o mal e destruir mortos-vivos no mesmo dia, potencialmente contra o mesmo alvo — caso seja um morto-vivo maligno."},{"name":"Ignorar o Toque da Morte (Ext)","text":"A partir do 3º nível, o caçador aplica seu modificador de Sabedoria (caso seja positivo) como um bônus adicional aos testes de resistência contra magias ou efeitos dos mortos-vivos. Portanto, os testes de Vontade consideram o dobro do modificador normal de Sabedoria contra essas criaturas."},{"name":"Morte Definitiva (Sob)","text":"Qualquer morto-vivo eliminado por um caçador dos mortos, seja em combate corporal ou através de magias, nunca mais se erguerá como uma dessas criaturas. Ele estará destruído para sempre."},{"name":"Expulsão Adicional","text":"No 6º nível, o caçador dos mortos recebe Expulsão Adicional como um talento extra. Esse talento lhe concede mais quatro utilizações de Expulsar mortos-vivos por dia."},{"name":"Explosão de Energia Positiva (Sob)","text":"Um caçador dos mortos de 8º nível ou superior é capaz de gerar uma explosão de energia positiva, que causa 1d6 pontos de dano por nível na classe de prestígio a qualquer morto-vivo num raio de 30 metros do personagem. As criaturas podem realizar um teste de resistência de Reflexos (CD 10 + nível de experiência do caçador) para reduzir o dano à metade. A ativação usa uma ação padrão e duas tentativas de Expulsão."},{"name":"Corpo Fechado (Sob)","text":"Ao atingir o 10º nível, o caçador dos mortos não perderá mais níveis devido a efeitos de drenar energia (embora a morte e a ressurreição ainda reduzam o nível do personagem, assim como outros efeitos de absorção ou redução de níveis e experiência — como a criação de itens mágicos)."}],"spellList":{"1":["arma mágica","curar ferimentos leves","invisibilidade contra mortos-vivos","remover medo"],"2":["chama contínua","curar ferimentos moderados","força do touro","visão no escuro"],"3":["curar ferimentos graves","imobilizar mortos-vivos","luz cegante","proteção contra elementos"],"4":["curar ferimentos críticos","movimentação livre","proteção contra a morte"]}}'::jsonb),
('dnd35.defensores.prestige.defensores-cavaleiro-do-calice','Cavaleiro do Cálice','Cavaleiro do Cálice','Bônus Base de Ataque: +8. Tendência: Leal e Bom. Conhecimento (religião): 10 graduações. Conhecimento (planos): 5 graduações. Equipamento: Armadura de batalha mágica (+1 ou superior). Magias: Capacidade de conjurar magias divinas, inclusive proteção contra o mal. Especial: Inimigo predileto — demônios (habitantes do Abismo); derrotar um demônio ou enviá-lo de volta ao seu plano.',12,ARRAY[]::text[],ARRAY['prestige']::text[],'v35-defensores','D&D 3.5 — Defensores da Fé',51,'dnd35','{"id":"defensores-cavaleiro-do-calice","name":"Cavaleiro do Cálice","hitDie":12,"requirements":["Bônus Base de Ataque: +8.","Tendência: Leal e Bom.","Conhecimento (religião): 10 graduações.","Conhecimento (planos): 5 graduações.","Equipamento: Armadura de batalha mágica (+1 ou superior).","Magias: Capacidade de conjurar magias divinas, inclusive proteção contra o mal.","Especial: Inimigo predileto — demônios (habitantes do Abismo); derrotar um demônio ou enviá-lo de volta ao seu plano."],"classSkills":["Concentração (Con)","Conhecimento (planos) (Int)","Conhecimento (religião) (Int)","Diplomacia (Car)","Intimidação (Car)","Ofícios (Int)","Profissão (Sab)","Sentir Motivação (Sab)"],"skillPointsPerLevel":"2 + modificador de Inteligência","weaponArmor":"Os cavaleiros do cálice sabem usar todas as armas simples e comuns, todos os tipos de armadura e escudos.","levels":[{"level":1,"bab":"+1","fort":"+2","ref":"+0","will":"+2","special":"Eliminar demônios +1/+1d6, censurar demônios","spellsPerDay":[0,null,null,null]},{"level":2,"bab":"+2","fort":"+3","ref":"+0","will":"+3","special":"Coragem Celestial","spellsPerDay":[1,null,null,null]},{"level":3,"bab":"+3","fort":"+3","ref":"+1","will":"+3","special":"Eliminar demônios +2/+2d6","spellsPerDay":[1,0,null,null]},{"level":4,"bab":"+4","fort":"+4","ref":"+1","will":"+4","special":"","spellsPerDay":[1,1,null,null]},{"level":5,"bab":"+5","fort":"+4","ref":"+1","will":"+4","special":"Devoção celestial","spellsPerDay":[1,1,0,null]},{"level":6,"bab":"+6","fort":"+5","ref":"+2","will":"+5","special":"Eliminar demônios +3/+3d6","spellsPerDay":[1,1,1,null]},{"level":7,"bab":"+7","fort":"+5","ref":"+2","will":"+5","special":"","spellsPerDay":[2,1,1,0]},{"level":8,"bab":"+8","fort":"+6","ref":"+2","will":"+6","special":"Aura consagrada","spellsPerDay":[2,1,1,1]},{"level":9,"bab":"+9","fort":"+6","ref":"+3","will":"+6","special":"Eliminar demônios +4/+4d6","spellsPerDay":[2,2,1,1]},{"level":10,"bab":"+10","fort":"+7","ref":"+3","will":"+7","special":"Aura sagrada","spellsPerDay":[2,2,2,1]}],"features":[{"name":"Eliminar Demônios","text":"Um cavaleiro do cálice adquire vários benefícios especiais para combater seus inimigos jurados. No 1º nível, ele recebe +1 de bônus de competência nas jogadas de ataque contra qualquer demônio (mas não contra diabos). Seus ataques causarão +1d6 pontos de dano adicional, em função da especialização do cavaleiro contra esses monstros. Os benefícios aumentam à medida que o personagem adquire níveis nessa classe, conforme demonstrado na Tabela 3-2. Contra esse tipo de criatura, o bônus de competência também se aplica nos testes das perícias Intimidação, Ouvir, Sentir Motivação e Observar, nos testes de resistência de Vontade para anular poderes demoníacos e, finalmente, nos testes resistidos contra demônios. Esses bônus se acumulam com os bônus de inimigo predileto do personagem."},{"name":"Censurar Demônios (Sob)","text":"Os cavaleiros do cálice podem censurar demônios, de forma semelhante à capacidade de expulsar mortos-vivos dos clérigos. Em vez de canalizar energia positiva, o personagem conduz as energias dos planos celestiais Leais e Bons. Para fazê-lo, o cavaleiro precisa realizar um teste de Carisma e consultar a Tabela 8-16: Expulsão, na pág. 140 do Livro do Jogador, determinando qual o demônio mais poderoso que ele é capaz de afetar; o personagem deve somar seu nível de experiência total — e não somente seu nível na classe de prestígio — ao resultado do teste. Depois, será necessário calcular o dano de censura: jogue 2d6 + o nível de cavaleiro do cálice + o modificador de Carisma. Ao considerar todos os seus níveis de classe no teste de Carisma, o cavaleiro será capaz de afetar uma única criatura poderosa, mas dificilmente afetará vários demônios simultaneamente. Um demônio censurado ficará atordoado com a energia sagrada proveniente do cavaleiro. As criaturas atordoadas perdem seus bônus de Destreza na CA (se houver) e são incapazes de realizar qualquer ação. Os oponentes recebem +2 de bônus de circunstância para atacá-las. Se o cavaleiro do cálice atacar um demônio censurado, o efeito será dissipado imediatamente e a criatura agirá no seu próximo turno. Se o nível do cavaleiro for equivalente ao dobro dos Dados de Vida do demônio, a criatura será banida para seu plano de origem. Similar ao clérigo, o cavaleiro pode censurar demônios uma quantidade de vezes por dia equivalente a 3 + seu modificador de Carisma. As tentativas de expulsar mortos-vivos devem ser registradas separadamente."},{"name":"Magias","text":"A partir do 1º nível, um cavaleiro do cálice adquire a habilidade de conjurar uma pequena quantidade de magias divinas. Para conjurar magias, um personagem deve ter uma pontuação em Sabedoria igual ou superior a 10 + o nível da magia; portanto, um personagem de Sabedoria 10 ou inferior não conseguirá fazê-lo. As magias adicionais do cavaleiro do cálice são baseadas em Sabedoria; a Classe de Dificuldade de um teste de resistência contra essas magias equivale a 10 + nível da magia + modificador de Sabedoria. Quando o cavaleiro ganha 0 magias de um determinado nível (como 0 magias de 1º nível logo no 1º nível de experiência), recebe apenas magias adicionais. Um personagem que não receba magias adicionais em qualquer nível ainda não é capaz de conjurá-las. Ele tem acesso a qualquer magia da lista, desde que seja capaz de lançá-la, e pode escolher livremente qual preparar. Um cavaleiro prepara e conjura magias como um clérigo (mas não pode usar a Conversão Espontânea para lançar magias de cura no lugar de uma magia preparada)."},{"name":"Foco em Magia e Magia Penetrante","text":"Os cavaleiros do cálice recebem automaticamente os benefícios dos talentos Foco em Magia e Magia Penetrante quando conjuram uma magia visando um demônio. A CD do teste de resistência para esses efeitos recebe +2 de bônus e o cavaleiro recebe +2 de bônus no teste de conjurador para superar a RM do demônio."},{"name":"Coragem Celestial (Sob)","text":"Um cavaleiro do cálice de 2º nível ou superior é imune a efeitos de medo gerados ou conjurados por demônios. Qualquer aliado num raio de 3 m do personagem recebe +4 de bônus de moral nos testes de resistência contra esses efeitos."},{"name":"Devoção Celestial (Sob)","text":"A partir do 5º nível, o cavaleiro do cálice torna-se imune a magias e efeitos de encantamento gerados ou conjurados por demônios, inclusive feitiços e sugestões. Qualquer aliado num raio de 3 m do personagem recebe +4 de bônus de moral nos testes de resistência contra esses efeitos."},{"name":"Aura Consagrada (Sob)","text":"A partir do 8º nível, o cavaleiro do cálice emana um efeito permanente de consagrar que afeta um raio de 6 m à sua volta. Caso entre numa área afetada pela magia profanar, os dois efeitos são dissipados até que o cavaleiro abandone a área ou a duração de profanar termine. Se a magia profanar estiver sustentada por um altar ou outro santuário dedicado a uma divindade maligna, o efeito da aura consagrada anulará esse aprimoramento enquanto o cavaleiro permanecer na área: as penalidades de Expulsão são reduzidas a -3 e os mortos-vivos recebem apenas +1 de bônus profano em seus testes."},{"name":"Aura Sagrada (Sob)","text":"No 10º nível, o cavaleiro do cálice adquire a habilidade de criar uma aura sagrada ao seu redor, que afeta somente o personagem, enquanto ele estiver em combate corporal contra um ou mais demônios. Esse efeito é idêntico à magia conjurada por um clérigo de 10º nível, mas protege o cavaleiro contra ataques, magias e influências mentais geradas unicamente por demônios; além disso, apenas os demônios que atingirem o cavaleiro poderão ficar cegos."}],"spellList":{"1":["abençoar água","abençoar arma","arma mágica","auxílio divino","desespero","detectar o caos","detectar o mal","invocar criaturas I","proteção contra o mal","remover medo","resistência a elementos"],"2":["ajuda","arma espiritual","consagrar","dissimular tendência","explosão sônica","força do touro","invocar criaturas II","suportar elementos","vigor","zelo†"],"3":["círculo mágico contra o mal","dissipar magia","grito","invocar criaturas III","luz cegante","oração","proteção contra elementos","purgar invisibilidade","roupa encantada"],"4":["aliado extra-planar menor","âncora dimensional","arma da divindade†","arma mágica aprimorada","aspecto da divindade menor†","destruição sagrada","discernir mentiras","dissipar o mal","expulsão"]}}'::jsonb),
('dnd35.defensores.prestige.defensores-cavaleiro-do-circulo-central','Cavaleiro do Círculo Central','Cavaleiro do Círculo Central','Bônus Base de Ataque: +6. Tendência: Leal e Bom ou Neutro e Bom. Adestrar Animais: 7 graduações. Obter Informação: 4 graduações. Mensagens Secretas: 4 graduações.',10,ARRAY[]::text[],ARRAY['prestige']::text[],'v35-defensores','D&D 3.5 — Defensores da Fé',51,'dnd35','{"id":"defensores-cavaleiro-do-circulo-central","name":"Cavaleiro do Círculo Central","hitDie":10,"requirements":["Bônus Base de Ataque: +6.","Tendência: Leal e Bom ou Neutro e Bom.","Adestrar Animais: 7 graduações.","Obter Informação: 4 graduações.","Mensagens Secretas: 4 graduações."],"classSkills":["Adestrar Animais (Car)","Cavalgar (Des)","Concentração (Con)","Conhecimento (arcano) (Int)","Cura (Sab)","Diplomacia (Car)","Mensagens Secretas (Sab)","Profissão (Sab)","Sentir Motivação (Sab)"],"skillPointsPerLevel":"4 + modificador de Inteligência","weaponArmor":"Os cavaleiros do círculo central sabem usar todas as armas simples e comuns, todos os tipos de armadura e escudos.","levels":[{"level":1,"bab":"+1","fort":"+0","ref":"+0","will":"+2","special":"Percepção de combate +2, Lutar às Cegas","spellsPerDay":[0,null,null]},{"level":2,"bab":"+2","fort":"+0","ref":"+0","will":"+3","special":"Idiomas","spellsPerDay":[0,null,null]},{"level":3,"bab":"+3","fort":"+1","ref":"+1","will":"+3","special":"Ataque certeiro 1/dia","spellsPerDay":[1,null,null]},{"level":4,"bab":"+4","fort":"+1","ref":"+1","will":"+4","special":"","spellsPerDay":[1,null,null]},{"level":5,"bab":"+5","fort":"+1","ref":"+1","will":"+4","special":"Percepção de combate +4","spellsPerDay":[1,0,null]},{"level":6,"bab":"+6","fort":"+2","ref":"+2","will":"+5","special":"Ataque certeiro 2/dia","spellsPerDay":[1,0,null]},{"level":7,"bab":"+7","fort":"+2","ref":"+2","will":"+5","special":"","spellsPerDay":[1,1,null]},{"level":8,"bab":"+8","fort":"+2","ref":"+2","will":"+6","special":"","spellsPerDay":[1,1,0]},{"level":9,"bab":"+9","fort":"+3","ref":"+3","will":"+6","special":"Ataque certeiro 3/dia","spellsPerDay":[1,1,1]},{"level":10,"bab":"+10","fort":"+3","ref":"+3","will":"+7","special":"Percepção de combate +6","spellsPerDay":[1,1,1]}],"features":[{"name":"Magias","text":"A partir do 1º nível, um cavaleiro do círculo central adquire a habilidade de conjurar uma pequena quantidade de magias divinas. Para conjurar magias, um personagem deve ter uma pontuação em Sabedoria igual ou superior a 10 + o nível da magia; portanto, um personagem de Sabedoria 10 ou inferior não conseguirá fazê-lo. As magias adicionais do cavaleiro são baseadas em Sabedoria; a Classe de Dificuldade de um teste de resistência contra essas magias equivale a 10 + nível da magia + modificador de Sabedoria. Quando um cavaleiro do círculo central recebe 0 magias de um determinado nível (como 0 magias de 1º nível logo no 1º nível de experiência), recebe apenas magias adicionais. Um personagem que não receba magias adicionais em qualquer nível ainda não é capaz de conjurá-las. Ele tem acesso a qualquer magia da lista, desde que seja capaz de lançá-la, e pode escolher livremente qual preparar. Um cavaleiro prepara e conjura magias como um clérigo (mas não pode usar a Conversão Espontânea para lançar magias de cura no lugar de uma magia preparada). O nível de conjurador do cavaleiro do círculo central equivale à metade de seu nível na classe de prestígio."},{"name":"Lutar às Cegas","text":"O cavaleiro do círculo central recebe esse talento gratuitamente no 1º nível."},{"name":"Percepção de Combate (Ext)","text":"Um cavaleiro do círculo central pode selecionar um único oponente em combate — contra ele, o cavaleiro recebe +2 de bônus intuitivo na CA e +2 de bônus intuitivo nas jogadas de ataque. No 5º nível, esses bônus aumentam para +4 e no 10º nível, para +6."},{"name":"Idiomas (SM)","text":"O cavaleiro do círculo central deve estar apto a se comunicar com todos que encontra, atuando como os olhos e ouvidos dos Contempladores dos Astros. A partir do 2º nível, ele pode conjurar idiomas (idêntico à magia) uma quantidade de vezes por dia equivalente ao seu nível de cavaleiro + seu bônus de Carisma."},{"name":"Ataque Certeiro (SM)","text":"No 3º nível, o cavaleiro do círculo central pode lançar ataque certeiro (idêntico à magia) uma vez por dia. Ele adquire utilizações adicionais a cada três níveis na classe de prestígio (duas vezes por dia no 6º nível e três vezes por dia no 9º nível)."},{"name":"Observação para Multiclasse","text":"Os personagens paladinos podem adquirir livremente níveis desta classe de prestígio, intercalando as duas classes sem penalidades."}],"spellList":{"1":["abençoar arma","arma mágica","auxílio divino","benção","curar ferimentos leves","detectar mortos-vivos","detectar venenos","ler magias","proteção contra o mal"],"2":["augúrio","dissimular tendência","proteger outro"],"3":["arma mágica aprimorada","curar ferimentos moderados","discernir mentiras","dissipar magia","oração"]}}'::jsonb),
('dnd35.defensores.prestige.defensores-contemplativo','Contemplativo','Contemplativo','Conhecimento (religião): 13 graduações. Especial: O personagem deve ter mantido um contato direto com sua divindade patrona ou um servo enviado por ela ou com seres superiores que incorporem os princípios mais elevados de uma tendência (um solar, por exemplo).',6,ARRAY[]::text[],ARRAY['prestige']::text[],'v35-defensores','D&D 3.5 — Defensores da Fé',51,'dnd35','{"id":"defensores-contemplativo","name":"Contemplativo","hitDie":6,"requirements":["Conhecimento (religião): 13 graduações.","Especial: O personagem deve ter mantido um contato direto com sua divindade patrona ou um servo enviado por ela ou com seres superiores que incorporem os princípios mais elevados de uma tendência (um solar, por exemplo)."],"classSkills":["Concentração (Con)","Conhecimento (religião) (Int)","Cura (Sab)","Diplomacia (Car)","Espionar (Int, perícia exclusiva)","Identificar Magia (Int)","Intimidar (Car)","Ofícios (Int)","Profissão (Sab)","Senso de Direção (Sab)","Sentir Motivação (Sab)"],"skillPointsPerLevel":"2 + modificador de Inteligência","weaponArmor":"Os contemplativos sabem usar todas as armas simples. Eles não sabem usar nenhum tipo de armadura ou escudos, mas quase sempre conservam essa habilidade de sua(s) antiga(s) classe(s).","levels":[{"level":1,"bab":"+0","fort":"+0","ref":"+0","will":"+2","special":"1º domínio de prestígio, saúde divina","spellcastingAdvance":"+1 nível de classe existente"},{"level":2,"bab":"+1","fort":"+0","ref":"+0","will":"+3","special":"Mente escorregadia","spellcastingAdvance":"+1 nível de classe existente"},{"level":3,"bab":"+1","fort":"+1","ref":"+1","will":"+3","special":"Integridade divina","spellcastingAdvance":"+1 nível de classe existente"},{"level":4,"bab":"+2","fort":"+1","ref":"+1","will":"+4","special":"","spellcastingAdvance":"+1 nível de classe existente"},{"level":5,"bab":"+2","fort":"+1","ref":"+1","will":"+4","special":"Corpo divino","spellcastingAdvance":"+1 nível de classe existente"},{"level":6,"bab":"+3","fort":"+2","ref":"+2","will":"+5","special":"2º domínio de prestígio","spellcastingAdvance":"+1 nível de classe existente"},{"level":7,"bab":"+3","fort":"+2","ref":"+2","will":"+5","special":"Alma divina","spellcastingAdvance":"+1 nível de classe existente"},{"level":8,"bab":"+4","fort":"+2","ref":"+2","will":"+6","special":"","spellcastingAdvance":"+1 nível de classe existente"},{"level":9,"bab":"+4","fort":"+3","ref":"+3","will":"+6","special":"Corpo divino","spellcastingAdvance":"+1 nível de classe existente"},{"level":10,"bab":"+5","fort":"+3","ref":"+3","will":"+7","special":"União mística","spellcastingAdvance":"+1 nível de classe existente"}],"features":[{"name":"Domínio de Prestígio","text":"Quando seleciona a classe de contemplativo, e novamente no 6º nível, o personagem adquire acesso a um domínio de prestígio a sua escolha, conforme descrito no Capítulo 4: Magias Divinas. É possível selecionar qualquer domínio acessível à sua divindade ou tendência — seja um domínio de prestígio ou aqueles descritos no Livro do Jogador. O personagem recebe o poder concedido do domínio escolhido e será capaz de preparar as magias indicadas como suas magias de domínio diárias."},{"name":"Saúde Divina (Ext)","text":"Um contemplativo é imune a todas as doenças, inclusive as mágicas, como o apodrecimento das múmias e a licantropia."},{"name":"Conjuração","text":"Um contemplativo que já era capaz de conjurar magias divinas continuará desenvolvendo essa habilidade, adquirindo acesso a magias mais poderosas conforme segue sua devoção. Portanto, quando o personagem atinge um novo nível na classe de prestígio, adquire mais magias diárias — como se estivesse avançando um nível na sua classe de conjurador divino anterior. Entretanto, ele não recebe qualquer outro benefício daquela classe (chance aprimorada de Expulsar/Fascinar mortos-vivos, utilizações adicionais de remover doenças, etc.). Essencialmente, isso significa que o nível de contemplativo é somado ao nível de outra classe capaz de conjurar magias divinas do personagem e, depois disso, sua quantidade de magias diárias é determinada. Por exemplo, Teresa, uma clériga de 11º nível, adquire um nível de contemplativo, recebendo novas magias como se tivesse atingido o 12º nível de clérigo, mas usando os demais aspectos da progressão de nível — como o bônus base de ataque e o bônus base de resistência — da classe de prestígio. Se, em seguida, ela adquirir um nível de clérigo, tornando-se uma clériga de 12º nível/contemplativo de 1º, passará a conjurar e obter magias diárias como um clérigo de 13º nível. Caso o personagem tenha mais de uma classe capaz de conjurar magias divinas antes de se tornar um contemplativo, deverá escolher qual delas terá seu nível elevado para determinar a quantidade de magias diárias sempre que alcançar um nível na classe de prestígio. Se o personagem não era capaz de lançar magias divinas anteriormente, ele adquire a habilidade de fazê-lo exatamente como um clérigo de sua divindade patrona. A partir do 1º nível de contemplativo, sua progressão de magias será idêntica à do clérigo."},{"name":"Mente Escorregadia (Ext)","text":"No 2º nível, o contemplativo adquire a habilidade de ignorar efeitos mágicos que possam controlá-lo ou forçá-lo a fazer algo. Quando o personagem for afetado por um encantamento (falhando no seu teste de resistência), poderá tentar anular o efeito novamente uma rodada depois. O contemplativo dispõe somente de uma oportunidade adicional para realizar essa jogada."},{"name":"Integridade Divina (Sob)","text":"Ao atingir o 3º nível, o contemplativo poderá curar seus próprios ferimentos, além de usar qualquer outra habilidade similar que já tenha. Ele é capaz de recuperar uma quantidade de pontos de vida por dia equivalente ao dobro de seu nível de experiência atual, sendo possível dividir o efeito."},{"name":"Corpo Divino (Sob)","text":"A partir do 5º nível, o contemplativo se torna imune a qualquer tipo de veneno."},{"name":"Alma Divina (Sob)","text":"No 7º nível, o contemplativo adquire resistência à magia equivalente ao seu nível + 10. Para conseguir afetar o contemplativo com uma magia, um conjurador precisa igualar ou superar a resistência à magia do personagem num teste de conjurador — 1d20 + nível do conjurador."},{"name":"Corpo Eterno (Ext)","text":"Depois de atingir o 9º nível, o contemplativo não sofrerá mais penalidades devido a idade e não poderá ser envelhecido magicamente (qualquer penalidade existente permanece). O personagem continuará acumulando seus bônus em função do envelhecimento e morrerá de velhice quando chegar a hora."},{"name":"União Mística (Sob)","text":"Ao atingir o 10º nível, o contemplativo se tornará uma criatura mágica. A partir de então, ele será tratado como um extra-planar em vez de humanóide. Por exemplo, enfeitiçar pessoas não o afetará. Além disso, o contemplativo adquire redução de dano 20/+1. Isso significa que ele ignora (regenera instantaneamente) os 20 primeiros pontos de dano de qualquer ataque, exceto se o dano for causado por uma arma com +1 de bônus de melhoria (ou superior), por uma magia ou por uma forma de energia (fogo, gelo, eletricidade, etc.). Sendo um extra-planar, o contemplativo de 10º nível é afetado por magias que repelem criaturas encantadas, como proteção contra o bem."}]}'::jsonb),
('dnd35.defensores.prestige.defensores-devoto-da-guerra','Devoto da Guerra','Devoto da Guerra','Bônus Base de Ataque: +5. Talentos: Magias em Combate, Liderança. Diplomacia: 5 graduações. Sentir Motivação: 5 graduações. Magias: Capacidade de conjurar magias divinas e acesso a um dos seguintes domínios: Destruição, Força, Guerra ou Proteção. Para esse propósito, considera-se que os personagens capazes de lançar uma magia desses domínios têm acesso a eles. Especial: Capacidade de canalizar energia negativa ou positiva.',8,ARRAY[]::text[],ARRAY['prestige']::text[],'v35-defensores','D&D 3.5 — Defensores da Fé',51,'dnd35','{"id":"defensores-devoto-da-guerra","name":"Devoto da Guerra","hitDie":8,"requirements":["Bônus Base de Ataque: +5.","Talentos: Magias em Combate, Liderança.","Diplomacia: 5 graduações.","Sentir Motivação: 5 graduações.","Magias: Capacidade de conjurar magias divinas e acesso a um dos seguintes domínios: Destruição, Força, Guerra ou Proteção. Para esse propósito, considera-se que os personagens capazes de lançar uma magia desses domínios têm acesso a eles.","Especial: Capacidade de canalizar energia negativa ou positiva."],"classSkills":["Adestrar Animais (Car)","Cavalgar (Des)","Concentração (Cons)","Conhecimento (guerra) (Int)","Diplomacia (Car)","Identificar Magia (Int)","Natação (For)","Ofícios (Int)","Sentir Motivação (Sab)"],"skillPointsPerLevel":"2 + modificador de Inteligência","weaponArmor":"Os devotos da guerra sabem usar todas as armas simples e comuns, todos os tipos de armadura e escudos.","levels":[{"level":1,"bab":"+1","fort":"+2","ref":"+0","will":"+0","special":"Domínio de prestígio: Glória/Dominação, Bravura"},{"level":2,"bab":"+2","fort":"+3","ref":"+0","will":"+0","special":"Incentivar","spellcastingAdvance":"+1 nível de classe existente"},{"level":3,"bab":"+3","fort":"+3","ref":"+1","will":"+1","special":"Círculo de cura"},{"level":4,"bab":"+4","fort":"+4","ref":"+1","will":"+1","special":"Domínio de Prestígio: Adivinhação","spellcastingAdvance":"+1 nível na classe existente"},{"level":5,"bab":"+5","fort":"+4","ref":"+1","will":"+1","special":"Banquete de heróis"},{"level":6,"bab":"+6","fort":"+5","ref":"+2","will":"+2","special":"Aura de medo 1/dia","spellcastingAdvance":"+1 nível na classe existente"},{"level":7,"bab":"+7","fort":"+5","ref":"+2","will":"+2","special":"Velocidade em massa"},{"level":8,"bab":"+8","fort":"+6","ref":"+2","will":"+2","special":"Cura completa em massa","spellcastingAdvance":"+1 nível na classe existente"},{"level":9,"bab":"+9","fort":"+6","ref":"+3","will":"+3","special":"Aura de Medo 2/dia"},{"level":10,"bab":"+10","fort":"+7","ref":"+3","will":"+3","special":"Inimigo implacável","spellcastingAdvance":"+1 nível na classe existente"}],"features":[{"name":"Magias","text":"Um devoto da guerra conjura magias como um clérigo (consulte a Tabela 3-6: O Clérigo, na pág. 30 do Livro do Jogador) e tem acesso irrestrito à lista geral de magias dessa classe. Cada dois níveis de devoto da guerra são considerados como um nível adicional de clérigo para determinar a quantidade de magias diárias e seus efeitos (veja Conjuração, a seguir)."},{"name":"Conjuração","text":"Os devotos da guerra nunca abandonam seu treinamento mágico divino. Portanto, quando o personagem atinge um nível par na classe de prestígio (2º, 4º, 6º, 8º ou 10º), ele adquire mais magias diárias — como se estivesse avançando um nível na sua classe de conjurador divino anterior. Entretanto, ele não recebe qualquer outro benefício daquela classe (chance aprimorada de Expulsar/Fascinar mortos-vivos, utilizações adicionais de remover doenças, etc.). Por exemplo, Trafnar, um clérigo de 8º nível/devoto da guerra de 2º, adquire magias divinas por dia como se tivesse atingido o 9º nível de clérigo. Se, em seguida, ele adquirir um nível de devoto, tornando-se um clérigo 9/devoto 3, sua quantidade de magias diárias não será alterada; finalmente, quando alcançar o 4º nível de devoto da guerra, receberá magias diárias como um clérigo de 10º nível. Caso o personagem tenha mais de uma classe capaz de conjurar magias divinas antes de se tornar um devoto da guerra, deverá escolher qual delas terá seu nível elevado para determinar a quantidade de magias divinas por dia sempre que alcançar um nível par como devoto da guerra."},{"name":"Domínio de Prestígio","text":"Quando seleciona a classe devoto da guerra, o personagem adquire acesso ao domínio de prestígio Glória (caso canalize energia positiva) ou Dominação (caso utilize energia negativa), ambos descritos no Capítulo 4: Magias Divinas. No 4º nível, o devoto adquire acesso ao domínio de prestígio Adivinhação."},{"name":"Expulsar/Fascinar Mortos-Vivos (Sob)","text":"Os níveis de devoto da guerra são adicionados ao nível de clérigo ou paladino para Expulsar/Fascinar mortos-vivos."},{"name":"Bravura (Ext)","text":"Um devoto da guerra que resista a um efeito de medo é capaz de ativar essa habilidade usando uma ação padrão. Qualquer aliado num raio de 18 m, afetado pelo efeito de medo e que consiga ouvir o devoto, tem direito a realizar outro teste de resistência de Vontade contra a CD original, além de receber +1 de bônus de moral por nível do devoto da guerra."},{"name":"Incentivar (Ext)","text":"Caso o devoto gaste 5 minutos (no mínimo) proferindo um discurso de incentivo antes da batalha, concederá um bônus de moral nos testes de resistência contra feitiços e medo a todos os ouvintes. Este bônus será +2 no 2º nível da classe de prestígio e aumenta +2 a cada nível par subsequente (+4 no 4º nível, +6 no 6º nível, etc)."},{"name":"Círculo de Cura (SM)","text":"Uma vez por dia, o devoto da guerra pode conjurar um círculo de cura (idêntico à magia homônima)."},{"name":"Banquete de Heróis (SM)","text":"Uma vez por dia, o devoto da guerra pode conjurar um banquete de heróis (idêntico à magia homônima)."},{"name":"Aura de Medo (Sob)","text":"Uma vez por dia, o devoto da guerra é capaz de gerar uma aura de medo de 6 m de raio, que permanece 1 rodada por nível na classe de prestígio. Os oponentes devem realizar um teste de resistência de Vontade (CD 10 + nível do devoto + bônus de Carisma) ou serão afetados como na magia medo."},{"name":"Velocidade em Massa (SM)","text":"Uma vez por dia, o devoto da guerra pode conjurar velocidade em massa (idêntico à magia homônima)."},{"name":"Cura Completa em Massa (SM)","text":"Uma vez por dia, o devoto da guerra pode conjurar cura completa em massa (idêntico à magia homônima)."},{"name":"Inimigo Implacável (SM)","text":"No 10º nível, o devoto da guerra consegue canalizar energia positiva suficiente para induzir seus aliados num raio de 30 metros a continuar lutando, mesmo depois de sofrerem ferimentos letais. Essa habilidade exige uma ação equivalente a movimento e concentração; enquanto estiver ativa, todos os aliados na área afetada ignoram as conseqüências do dano sofrido e continuam a lutar, mesmo quando deveriam estar incapacitados ou morrendo. A morte ocorre imediatamente quando eles atingirem -20 pontos de vida. Caso a habilidade expire — seja porque o devoto parou de se concentrar, fracassou num teste de Concentração ou ficou incapacitado (ou morrendo) — os efeitos totais do dano ocorrem imediatamente."},{"name":"Observação para Multiclasse","text":"Caso o devoto da guerra selecione um nível em qualquer classe diferente desta classe de prestígio, não conseguirá adquirir mais níveis de devoto da guerra até que faça uma penitência (veja a descrição da magia penitência, pág. 245 do Livro do Jogador)."}]}'::jsonb),
('dnd35.defensores.prestige.defensores-exorcista-sagrado','Exorcista Sagrado','Exorcista Sagrado','Tendência: Leal e Bom, Neutro e Bom ou Caótico e Bom. Conhecimento (planos): 7 graduações. Conhecimento (religião): 10 graduações. Magias: Capacidade de conjurar expulsão ou dissipar o mal. Especial: Adotar esta classe de prestígio requer a sanção de uma igreja ou a ordenação para uma confraria de exorcistas sagrados. A igreja considera que somente os personagens detentores de uma fé e devoção exemplares, vontade inabalável e moralidade inquestionável merecem ser ordenados como exorcistas sagrados.',8,ARRAY[]::text[],ARRAY['prestige']::text[],'v35-defensores','D&D 3.5 — Defensores da Fé',51,'dnd35','{"id":"defensores-exorcista-sagrado","name":"Exorcista Sagrado","hitDie":8,"requirements":["Tendência: Leal e Bom, Neutro e Bom ou Caótico e Bom.","Conhecimento (planos): 7 graduações.","Conhecimento (religião): 10 graduações.","Magias: Capacidade de conjurar expulsão ou dissipar o mal.","Especial: Adotar esta classe de prestígio requer a sanção de uma igreja ou a ordenação para uma confraria de exorcistas sagrados. A igreja considera que somente os personagens detentores de uma fé e devoção exemplares, vontade inabalável e moralidade inquestionável merecem ser ordenados como exorcistas sagrados."],"classSkills":["Concentração (Con)","Conhecimento (arcano) (Int)","Conhecimento (planos) (Int)","Conhecimento (religião) (Int)","Cura (Sab)","Espionar (Int, perícia exclusiva)","Identificar Magia (Int)","Intimidar (Car)","Ofícios (Int)","Profissão (Sab)"],"skillPointsPerLevel":"2 + modificador de Inteligência","weaponArmor":"Os exorcistas sagrados sabem usar todas as armas simples. Eles não sabem usar nenhum tipo de armadura ou escudos, mas quase sempre conservam essa habilidade de sua(s) antiga(s) classe(s).","levels":[{"level":1,"bab":"+0","fort":"+0","ref":"+0","will":"+2","special":"Domínio de prestígio: Exorcismo, adversário predileto +1, expulsar mortos-vivos","spellcastingAdvance":"+1 nível de classe existente"},{"level":2,"bab":"+1","fort":"+0","ref":"+0","will":"+3","special":"Resistência à possessão, detectar o mal","spellcastingAdvance":"+1 nível de classe existente"},{"level":3,"bab":"+2","fort":"+1","ref":"+1","will":"+3","special":"Expulsão adicional","spellcastingAdvance":"+1 nível de classe existente"},{"level":4,"bab":"+3","fort":"+1","ref":"+1","will":"+4","special":"Dissipar o mal 1/semana, adversário predileto +2","spellcastingAdvance":"+1 nível de classe existente"},{"level":5,"bab":"+3","fort":"+1","ref":"+1","will":"+4","special":"Presença consagrada","spellcastingAdvance":"+1 nível de classe existente"},{"level":6,"bab":"+4","fort":"+2","ref":"+2","will":"+5","special":"Expulsão adicional","spellcastingAdvance":"+1 nível de classe existente"},{"level":7,"bab":"+5","fort":"+2","ref":"+2","will":"+5","special":"Dissipar o mal 2/semana","spellcastingAdvance":"+1 nível de classe existente"},{"level":8,"bab":"+6","fort":"+2","ref":"+2","will":"+6","special":"Adversário predileto +3","spellcastingAdvance":"+1 nível de classe existente"},{"level":9,"bab":"+6","fort":"+3","ref":"+3","will":"+6","special":"Expulsão adicional","spellcastingAdvance":"+1 nível de classe existente"},{"level":10,"bab":"+7","fort":"+3","ref":"+3","will":"+7","special":"Dissipar o mal 3/semana","spellcastingAdvance":"+1 nível de classe existente"}],"features":[{"name":"Conjuração","text":"Os exorcistas sagrados nunca abandonam seu treinamento mágico, desenvolvendo-o junto com suas habilidades de exorcismo. Portanto, quando o personagem atinge um novo nível na classe de prestígio, adquire mais magias diárias — como se estivesse avançando um nível na sua classe de conjurador anterior. Entretanto, ele não recebe qualquer outro benefício daquela classe (chance aprimorada de Expulsar/Fascinar mortos-vivos, utilizações adicionais de remover doenças, etc.). Essencialmente, isso significa que o nível de exorcista sagrado é somado ao nível de outra classe capaz de conjurar magias do personagem e, depois disso, sua quantidade de magias diárias é determinada. Por exemplo, Delliva, uma clériga de 8º nível, adquire um nível de exorcista sagrado, recebendo novas magias como se tivesse atingido o 9º nível de clérigo, mas usando os demais aspectos da progressão de nível — como o bônus base de ataque e o bônus base de resistência — da classe de prestígio. Se, em seguida, ela adquirir um nível de clérigo, tornando-se uma clériga de 9º nível/exorcista de 1º, passará a conjurar e obter magias diárias como um clérigo de 10º nível. Caso o personagem tenha mais de uma classe capaz de conjurar magias divinas antes de se tornar um exorcista sagrado, deverá escolher qual delas terá seu nível elevado para determinar a quantidade de magias diárias sempre que alcançar um novo nível na classe de prestígio."},{"name":"Domínio de Prestígio","text":"Quando seleciona a classe exorcista sagrado, o personagem adquire acesso ao domínio Exorcismo, descrito no Capítulo 4: Magias Divinas. O personagem recebe o poder concedido desse domínio (habilidade de expulsar entidades espirituais dos corpos que possuíram) e será capaz de preparar as magias indicadas como suas magias de domínio diárias."},{"name":"Adversário Predileto (Ext)","text":"Um exorcista sagrado precisa escolher seu adversário predileto entre mortos-vivos e seres extra-planares. O estudo intensivo e o treinamento especial nas técnicas adequadas para combater esse inimigo lhe concedem +1 de bônus de competência nos testes das perícias Blefar, Intimidar, Ouvir, Sentir Motivação e Observar, e nos testes de conjurador executados para superar a RM da criatura. No 4º nível, esse bônus aumenta para +2 e no 8º nível, para +3."},{"name":"Expulsar Mortos-Vivos (Sob)","text":"Um exorcista sagrado é capaz de expulsar mortos-vivos como um clérigo. Esta habilidade sobrenatural se acumula com a capacidade de Expulsar Mortos-vivos de outras classes; portanto, os níveis de exorcista são adicionados aos níveis de clérigo (ou de paladino -2) para determinar o nível efetivo do personagem quando utiliza a expulsão."},{"name":"Resistência à Possessão (Ext)","text":"A partir do 2º nível, o exorcista sagrado recebe +4 de bônus sagrado nos testes de resistência contra a magia recipiente arcano ou habilidades similares (incluindo a habilidade possessão do fantasma) e +2 de bônus sagrado nos testes de dissipar contra esses efeitos. Finalmente, ele recebe +2 de bônus sagrado nos testes de resistência contra magias e efeitos de encantamento e compulsão lançados por extra-planares malignos ou mortos-vivos."},{"name":"Detectar o Mal (SM)","text":"A partir do 2º nível, o exorcista pode usar detectar o mal livremente, como uma habilidade similar a magia. Essa habilidade duplica os efeitos da magia detectar o mal."},{"name":"Expulsão Adicional","text":"No 3º, 6º e 9º níveis, o exorcista sagrado recebe Expulsão Adicional como um talento extra. Em cada nível indicado, esse talento lhe concede mais quatro utilizações de Expulsar Mortos-vivos por dia."},{"name":"Dissipar o Mal (SM)","text":"No 4º nível, o exorcista sagrado adquire a habilidade de conjurar dissipar o mal, como uma habilidade similar a magia, uma vez por semana. A partir do 7º nível, ele poderá ativar essa habilidade duas vezes por semana; no 10º nível, essa quantidade aumenta para três por semana."},{"name":"Presença Consagrada (Sob)","text":"A partir do 5º nível, o exorcista sagrado emana uma aura de energia positiva com 6 m de raio. Essa aura duplica os efeitos da magia consagrar, mas desloca-se com o personagem. Caso entre numa área afetada pela magia profanar, os dois efeitos serão dissipados até que o exorcista abandone a área. Caso a magia profanar seja conjurada sobre o personagem, sua aura ficará desativada até que a duração da magia termine."}]}'::jsonb),
('dnd35.defensores.prestige.defensores-hospitalario','Hospitalário','Hospitalário','Bônus Base de Ataque: +4. Tendência: Qualquer uma, exceto Caótico. Talentos: Combate Montado, Investida Montada. Adestrar Animais: 5 graduações. Cavalgar: 5 graduações.',8,ARRAY[]::text[],ARRAY['prestige']::text[],'v35-defensores','D&D 3.5 — Defensores da Fé',51,'dnd35','{"id":"defensores-hospitalario","name":"Hospitalário","hitDie":8,"requirements":["Bônus Base de Ataque: +4.","Tendência: Qualquer uma, exceto Caótico.","Talentos: Combate Montado, Investida Montada.","Adestrar Animais: 5 graduações.","Cavalgar: 5 graduações."],"classSkills":["Adestrar Animais (Car)","Cavalgar (Des)","Concentração (Con)","Conhecimento (religião) (Int)","Cura (Sab)","Diplomacia (Car)","Ofícios (Int)","Profissão (Sab)"],"skillPointsPerLevel":"2 + modificador de Inteligência","weaponArmor":"Os hospitalários sabem usar todas as armas simples e comuns, todos os tipos de armadura e escudos.","levels":[{"level":1,"bab":"+1","fort":"+2","ref":"+0","will":"+0","special":"Cura pelas mãos","spellcastingAdvance":"+1 nível de classe existente"},{"level":2,"bab":"+2","fort":"+3","ref":"+0","will":"+0","special":"","spellcastingAdvance":"+1 nível de classe existente"},{"level":3,"bab":"+3","fort":"+3","ref":"+1","will":"+1","special":"Expulsar mortos-vivos, Remover doenças, talento adicional","spellcastingAdvance":"+1 nível de classe existente"},{"level":4,"bab":"+4","fort":"+4","ref":"+1","will":"+1","special":"","spellcastingAdvance":"+1 nível de classe existente"},{"level":5,"bab":"+5","fort":"+4","ref":"+1","will":"+1","special":"Talento adicional","spellcastingAdvance":"+1 nível de classe existente"},{"level":6,"bab":"+6","fort":"+5","ref":"+2","will":"+2","special":"","spellcastingAdvance":"+1 nível de classe existente"},{"level":7,"bab":"+7","fort":"+5","ref":"+2","will":"+2","special":"Talento adicional","spellcastingAdvance":"+1 nível de classe existente"},{"level":8,"bab":"+8","fort":"+6","ref":"+2","will":"+2","special":"","spellcastingAdvance":"+1 nível de classe existente"},{"level":9,"bab":"+9","fort":"+6","ref":"+3","will":"+3","special":"Talento adicional","spellcastingAdvance":"+1 nível de classe existente"},{"level":10,"bab":"+10","fort":"+7","ref":"+3","will":"+3","special":"","spellcastingAdvance":"+1 nível de classe existente"}],"features":[{"name":"Domínios","text":"Quando seleciona a classe hospitalário, o personagem adquire acesso aos seguintes domínios: Cura, Proteção e Guerra, além do domínio de prestígio Glória (caso canalize energia positiva) ou Dominação (caso utilize energia negativa), ambos descritos no Capítulo 4: Magias Divinas. O acesso aos domínios anteriores é permitido. O personagem recebe o poder concedido do domínio selecionado e será capaz de preparar as magias indicadas como suas magias de domínio diárias. Além disso, um hospitalário é capaz de converter espontaneamente suas magias preparadas em efeitos de curar ou infligir ferimentos."},{"name":"Conjuração","text":"Os hospitalários nunca abandonam seu treinamento mágico divino, desenvolvendo-o junto com suas perícias na classe de prestígio. Portanto, quando o personagem atinge um novo nível nessa classe, adquire mais magias diárias — como se estivesse avançando um nível na sua classe de conjurador divino anterior. Entretanto, ele não recebe qualquer outro benefício daquela classe (chance aprimorada de Expulsar/Fascinar mortos-vivos, dano adicional de destruir o mal, etc.). Essencialmente, isso significa que o nível de hospitalário é somado ao nível de outra classe capaz de conjurar magias divinas do personagem e, depois disso, sua quantidade de magias diárias é determinada. Por exemplo, Alhandra, uma paladina de 8º nível, adquire um nível de hospitalário, recebendo novas magias como se tivesse atingido o 9º nível de paladino, mas usando os demais aspectos da progressão de nível — como o bônus base de ataque e o bônus base de resistência — da classe de prestígio. Se, em seguida, ela adquirir um nível de paladino, tornando-se uma paladina de 9º nível/hospitalária de 1º, passará a conjurar e obter magias divinas como uma paladina de 10º nível. Caso o personagem tenha mais de uma classe capaz de conjurar magias divinas antes de se tornar um hospitalário, deverá escolher qual delas terá seu nível elevado para determinar a quantidade de magias divinas sempre que alcançar um novo nível como hospitalário."},{"name":"Cura pelas Mãos (SM)","text":"Um hospitalário pode curar ferimentos através do toque, como um paladino. Seus níveis de paladino são adicionados ao nível da classe de prestígio para determinar a quantidade de PV curados."},{"name":"Expulsar Mortos-Vivos (Sob)","text":"Quando um hospitalário atinge o 3º nível, adquire a habilidade sobrenatural de Expulsar Mortos-vivos como um clérigo com dois níveis inferiores ao seu. Esta habilidade sobrenatural se acumula com a capacidade de Expulsar Mortos-vivos de outras classes; logo, um clérigo 6º/hospitalário 4º afetaria mortos-vivos como um personagem de 8º nível. Um paladino de 6º nível (que também usa a Expulsão como um clérigo de dois níveis inferior)/hospitalário 4º nível afetaria mortos-vivos como um personagem de 6º nível."},{"name":"Remover Doenças (SM)","text":"Um hospitalário é capaz de remover doenças como os paladinos. Seus níveis de paladino são adicionados ao nível da classe de prestígio para determinar a quantidade de utilizações semanais."},{"name":"Talentos Adicionais","text":"Um hospitalário recebe um talento adicional nos níveis indicados na Tabela 3-7. Esses talentos devem ser escolhidos da seguinte lista: Ambidestria, Lutar às Cegas, Reflexos de Combate, Esquiva (Mobilidade, Deslocamento), Usar Arma Exótica, Especialização (Desarmar Aprimorado, Imobilização Aprimorada, Ataque Giratório), Sucesso Decisivo Aprimorado*, Iniciativa Aprimorada, Ataque Desarmado Aprimorado (Desviar Objetos, Ataque Atordoante), Arqueirismo Montado, Atropelar, Investida Implacável, Tiro Certeiro (Tiro Longo, Precisão, Tiro Rápido, Tiro em Movimento), Ataque Poderoso (Trespassar, Encontrão Aprimorado, Separar, Trespassar Aprimorado), Saque Rápido, Combater com Duas Armas (Combater com Duas Armas Aprimorado), Acuidade com Arma*, Foco em Arma*. Os talentos que têm pré-requisitos estão listados entre parênteses, depois do talento inicial exigido. O hospitalário pode escolher um talento marcado com um asterisco (*) mais de uma vez, selecionando uma arma diferente a cada vez. O hospitalário ainda precisa atender todos os pré-requisitos de um talento, inclusive valores de habilidade e o bônus base de ataque mínimo. Importante: Esses talentos são somados ao talento que um personagem de qualquer classe recebe a cada três níveis. O hospitalário não precisa se limitar a essa lista para selecionar aqueles talentos."},{"name":"Código de Conduta","text":"Os hospitalários fazem votos de pobreza, obediência e proteção aos inocentes sob seus cuidados. Isto não significa que eles vivem em miséria e mendicância, mas que repartem sua riqueza entre si e oferecem o excesso para sua ordem. A obediência não está relacionada ao nível social ou de experiência do personagem, mas à sua posição na ordem dos hospitalários, que muda conforme a situação. Não importa o seu cargo relativo, todos eles respondem ao líder local enquanto permanecerem em seu território. Os hospitalários devem estar dispostos a sacrificar suas vidas para salvar os peregrinos ou qualquer refúgio sob seus cuidados, mas não devem fazê-lo impetuosamente."},{"name":"Observação para Multiclasse","text":"Os personagens paladinos podem adquirir livremente níveis desta classe de prestígio, intercalando as duas classes sem penalidades."},{"name":"Ex-Hospitalários","text":"Um hospitalário que se torne Caótico, pratique voluntariamente um ato maligno ou viole de modo grave seu código de conduta perderá todas as suas magias e características da classe — e não conseguirá adquirir níveis na classe de prestígio — até que faça uma penitência (veja a descrição da magia penitência, pág. 245 do Livro do Jogador). Um hospitalário pode ser um personagem multiclasse, mas existe uma restrição especial. Caso adquira uma nova classe ou (caso seja multiclasse) eleve o nível de qualquer classe, exceto paladino, jamais poderá aumentar seu nível de hospitalário, embora conserve todas as habilidades da classe já adquiridas. O caminho desses indivíduos, assim como a trilha dos paladinos, requer devoção constante; uma vez que se afastem da vereda escolhida, nunca mais conseguirão trilhá-la novamente."}]}'::jsonb),
('dnd35.defensores.prestige.defensores-inquiridor-consagrado','Inquiridor Consagrado','Inquiridor Consagrado','Bônus Base de Ataque: +5. Tendência: Leal. Talentos: Rastrear. Disfarces: 5 graduações. Obter Informação: 5 graduações. Profissão (Advogado): 5 graduações. Especial: O candidato deve aceitar uma missão, imposta pela igreja, que envolva localizar e destruir um inimigo específico da organização. Caso fracasse, ele precisará aguardar durante um ano e um dia antes de fazer uma nova petição. Se obtiver sucesso, a igreja o aceitará como inquiridor consagrado e ele poderá adquirir níveis nessa classe de prestígio.',10,ARRAY[]::text[],ARRAY['prestige']::text[],'v35-defensores','D&D 3.5 — Defensores da Fé',51,'dnd35','{"id":"defensores-inquiridor-consagrado","name":"Inquiridor Consagrado","hitDie":10,"requirements":["Bônus Base de Ataque: +5.","Tendência: Leal.","Talentos: Rastrear.","Disfarces: 5 graduações.","Obter Informação: 5 graduações.","Profissão (Advogado): 5 graduações.","Especial: O candidato deve aceitar uma missão, imposta pela igreja, que envolva localizar e destruir um inimigo específico da organização. Caso fracasse, ele precisará aguardar durante um ano e um dia antes de fazer uma nova petição. Se obtiver sucesso, a igreja o aceitará como inquiridor consagrado e ele poderá adquirir níveis nessa classe de prestígio."],"classSkills":["Blefar (Car)","Diplomacia (Car)","Disfarces (Car)","Intimidar (Car)","Obter Informação (Car)","Procurar (Int)","Profissão (Sab)"],"skillPointsPerLevel":"4 + modificador de Inteligência","weaponArmor":"Os inquiridores consagrados sabem usar todas as armas simples e comuns, todos os tipos de armadura e escudos.","levels":[{"level":1,"bab":"+1","fort":"+0","ref":"+0","will":"+2","special":"Benção das escrituras +2, detectar o caos","spellsPerDay":[0,null,null,null,null]},{"level":2,"bab":"+2","fort":"+0","ref":"+0","will":"+3","special":"Visão santificada","spellsPerDay":[1,null,null,null,null]},{"level":3,"bab":"+3","fort":"+1","ref":"+1","will":"+3","special":"Benção das escrituras +4, dissipar magia","spellsPerDay":[1,0,null,null,null]},{"level":4,"bab":"+4","fort":"+1","ref":"+1","will":"+4","special":"Emoções","spellsPerDay":[1,1,null,null,null]},{"level":5,"bab":"+5","fort":"+1","ref":"+1","will":"+4","special":"Benção das escrituras +6","spellsPerDay":[1,1,0,null,null]},{"level":6,"bab":"+6","fort":"+2","ref":"+2","will":"+5","special":"Visão falsa","spellsPerDay":[1,1,1,null,null]},{"level":7,"bab":"+7","fort":"+2","ref":"+2","will":"+5","special":"Benção das escrituras +8","spellsPerDay":[2,1,1,0,null]},{"level":8,"bab":"+8","fort":"+2","ref":"+2","will":"+6","special":"Caçada implacável","spellsPerDay":[2,1,1,1,0]},{"level":9,"bab":"+9","fort":"+3","ref":"+3","will":"+6","special":"Benção das escrituras +10","spellsPerDay":[2,2,1,1,1]},{"level":10,"bab":"+10","fort":"+3","ref":"+3","will":"+7","special":"Caçada inequívoca","spellsPerDay":[2,2,2,1,1]}],"features":[{"name":"Magias","text":"A partir do 1º nível, um inquiridor adquire a habilidade de conjurar uma pequena quantidade de magias divinas. Para conjurar magias, um personagem deve ter uma pontuação em Sabedoria igual ou superior a 10 + o nível da magia; portanto, um personagem de Sabedoria 10 ou inferior não conseguirá fazê-lo. As magias adicionais do inquiridor consagrado são baseadas em Sabedoria; a Classe de Dificuldade de um teste de resistência contra essas magias equivale a 10 + nível da magia + modificador de Sabedoria. Quando um inquiridor ganha 0 magias de um determinado nível (como 0 magias de 1º nível logo no 1º nível de experiência), recebe apenas magias adicionais. Um personagem que não receba magias adicionais em qualquer nível ainda não é capaz de conjurá-las. Ele tem acesso a qualquer magia da lista, desde que seja capaz de lançá-la, e pode escolher livremente qual preparar. Um inquiridor prepara e conjura magias como um clérigo (mas não pode usar a Conversão Espontânea para lançar magias de cura no lugar de uma magia preparada)."},{"name":"Benção das Escrituras (Sob)","text":"Todos os inquiridores consagrados recebem +2 de bônus sagrado em testes de Blefar, Ouvir, Sentir Motivação, Observar e Sobrevivência quando estiverem rastreando o alvo indicado pela sua igreja. Quando esse alvo for um grupo, o bônus será aplicado ao líder. Eles recebem o mesmo bônus nas jogadas de ataque corporal e dano com armas brancas contra esses alvos — esse modificador não se aplica a jogadas de ataque à distância ou dano com armas de disparo. O bônus aumenta para +4 no 3º nível, +6 no 5º nível, +8 no 7º nível, e +10 no 9º nível."},{"name":"Detectar o Caos (SM)","text":"O inquiridor pode usar detectar o caos livremente, como um clérigo de nível equivalente ao seu."},{"name":"Visão Santificada (Sob)","text":"A partir do 2º nível, o inquiridor consagrado recebe +4 de bônus em todos os testes de resistência contra ilusões."},{"name":"Dissipar Magia (SM)","text":"O inquiridor consagrado é capaz de conjurar dissipar magia como um clérigo de nível equivalente ao seu. A partir do 3º nível, é possível utilizar essa habilidade similar a magia uma vez por dia, mais uma a cada ponto de bônus de Sabedoria."},{"name":"Emoções (SM)","text":"A partir do 4º nível, o inquiridor consagrado é capaz de induzir sentimentos em todas as criaturas vivas num raio de 4,5 m, com efeitos idênticos à magia emoções, conjurada por um mago de um nível inferior ao seu. Logo, um inquiridor de 4º nível usará essa habilidade como um mago de 3º nível. É possível ativá-la uma quantidade de vezes por dia equivalente ao seu bônus de Sabedoria (mínimo 1). Emoções é uma habilidade similar a magia."},{"name":"Visão Falsa (Sob)","text":"A partir do 6º nível, o inquiridor consagrado é capaz de evitar as tentativas de Espionar perpetradas por seu alvo, seus aliados ou qualquer pessoa a serviço dele, com efeitos idênticos à magia visão falsa, conjurada por um mago de um nível inferior ao seu. Logo, um inquiridor de 6º nível usará essa habilidade como um mago de 5º nível. É possível ativá-la uma quantidade de vezes por dia equivalente ao seu bônus de Sabedoria (mínimo 1). Visão Falsa é uma habilidade sobrenatural."},{"name":"Caçada Implacável (Sob)","text":"A partir do 8º nível, se o inquiridor ferir um alvo e este conseguir escapar, ele sempre saberá a direção da vítima e a distância aproximada entre ambos. É possível utilizar a caçada implacável simultaneamente contra vários adversários distintos, contanto que todos façam parte do mesmo grupo e, em conjunto, formem o alvo principal da missão atual do inquiridor. Essa habilidade somente funcionará se todos estiverem no mesmo plano de existência."},{"name":"Caçada Inequívoca (Sob)","text":"No 10º nível, caso o inquiridor estabeleça uma caçada implacável, será capaz de intensificá-la e transformá-la numa caçada inequívoca, ignorando as fronteiras planares durante a localização de seu alvo. Diferente da caçada implacável, que consegue afetar vários indivíduos ao mesmo tempo, a caçada inequívoca persegue um único alvo de cada vez. Para que o inquiridor consiga ativar essa habilidade, ele deverá abandonar qualquer alvo adicional já localizado."},{"name":"Código de Conduta","text":"O inquiridor consagrado tem que revelar a sua identidade e o motivo de sua presença ao seu alvo antes de enfrentá-lo. Ele não pode desferir ataques furtivos contra o alvo. Ele está proibido de eliminar seu alvo num campo de batalha antes de revelar sua identidade e sua motivação. Intencionalmente, cada inquiridor se apresenta ou declara seu código de conduta de maneira vaga, para manter alguma vantagem durante a caçada. Qualquer inquiridor incapaz de seguir esse código de honra deve se submeter a um ato de penitência (veja a descrição da magia penitência, pág. 245 do Livro do Jogador); caso contrário, será impossível adquirir níveis nessa classe de prestígio."},{"name":"Observação para Multiclasse","text":"Os personagens paladinos podem adquirir livremente níveis desta classe de prestígio, intercalando as duas classes sem penalidades."}],"spellList":{"1":["acalmar emoções","alterar-se","animar cordas","comando","desespero"],"2":["detectar pensamentos","enfeitiçar pessoas","imobilizar pessoas","luz do dia"],"3":["discernir mentiras","expulsão","lendas e histórias","proteção contra a morte"],"4":["dominar pessoas","marca da justiça"],"5":["banimento","campo antimagia"]}}'::jsonb),
('dnd35.defensores.prestige.defensores-inquisidor-da-igreja','Inquisidor da Igreja','Inquisidor da Igreja','Bônus Base de Resistência de Vontade: +3. Tendência: Leal e Bom ou Leal e Neutro. Conhecimento (arcano): 8 graduações. Identificar Magia: 8 graduações. Magias: Capacidade de conjurar dissipar magia como magia divina. Especial: Deve pertencer a uma igreja ou ordem religiosa Leal e Boa e deve ter sido responsável pela descoberta de corrupção dentro da mesma organização.',8,ARRAY[]::text[],ARRAY['prestige']::text[],'v35-defensores','D&D 3.5 — Defensores da Fé',51,'dnd35','{"id":"defensores-inquisidor-da-igreja","name":"Inquisidor da Igreja","hitDie":8,"requirements":["Bônus Base de Resistência de Vontade: +3.","Tendência: Leal e Bom ou Leal e Neutro.","Conhecimento (arcano): 8 graduações.","Identificar Magia: 8 graduações.","Magias: Capacidade de conjurar dissipar magia como magia divina.","Especial: Deve pertencer a uma igreja ou ordem religiosa Leal e Boa e deve ter sido responsável pela descoberta de corrupção dentro da mesma organização."],"classSkills":["Concentração (Con)","Conhecimento (arcano) (Int)","Conhecimento (planos) (Int)","Conhecimento (religião) (Int)","Diplomacia (Car)","Espionar (Int)","Identificar Magia (Int)","Intimidar (Car)","Obter Informação (Car)","Procurar (Int)","Sentir Motivação (Sab)"],"skillPointsPerLevel":"2 + modificador de Inteligência","weaponArmor":"Os inquisidores da igreja sabem usar todas as armas simples e comuns, todos os tipos de armadura e escudos.","levels":[{"level":1,"bab":"+0","fort":"+2","ref":"+0","will":"+2","special":"Detectar o mal, Domínio de Prestígio: Inquisição","spellcastingAdvance":"+1 nível de classe existente"},{"level":2,"bab":"+1","fort":"+3","ref":"+0","will":"+3","special":"Imunidade à escola feitiço","spellcastingAdvance":"+1 nível de classe existente"},{"level":3,"bab":"+2","fort":"+3","ref":"+1","will":"+3","special":"Transpor ilusões","spellcastingAdvance":"+1 nível de classe existente"},{"level":4,"bab":"+3","fort":"+4","ref":"+1","will":"+4","special":"","spellcastingAdvance":"+1 nível de classe existente"},{"level":5,"bab":"+3","fort":"+4","ref":"+1","will":"+4","special":"Imunidade à escola compulsão","spellcastingAdvance":"+1 nível de classe existente"},{"level":6,"bab":"+4","fort":"+5","ref":"+2","will":"+5","special":"Induzir metamorfose","spellcastingAdvance":"+1 nível de classe existente"},{"level":7,"bab":"+5","fort":"+5","ref":"+2","will":"+5","special":"","spellcastingAdvance":"+1 nível de classe existente"},{"level":8,"bab":"+5","fort":"+6","ref":"+2","will":"+6","special":"Imunidade à Possessão","spellcastingAdvance":"+1 nível de classe existente"},{"level":9,"bab":"+6","fort":"+6","ref":"+3","will":"+6","special":"Discernir mentiras, revelar a verdade","spellcastingAdvance":"+1 nível de classe existente"},{"level":10,"bab":"+7","fort":"+7","ref":"+3","will":"+7","special":"","spellcastingAdvance":"+1 nível de classe existente"}],"features":[{"name":"Detectar o Mal (SM)","text":"O inquisidor pode usar detectar o mal livremente, como uma habilidade similar a magia. Essa habilidade duplica os efeitos da magia detectar o mal."},{"name":"Domínio de Prestígio","text":"Quando seleciona a classe inquisidor da igreja, o personagem adquire acesso ao domínio Inquisição, descrito no Capítulo 4: Magias Divinas. O personagem recebe o poder concedido desse domínio (+4 de bônus em testes para dissipar magia) e será capaz de preparar as magias indicadas como suas magias de domínio diárias."},{"name":"Conjuração","text":"Os inquisidores nunca abandonam seu treinamento mágico divino, desenvolvendo-o junto com suas perícias na inquisição. Portanto, quando o personagem atinge um novo nível na classe de prestígio, adquire mais magias diárias — como se estivesse avançando um nível na sua classe de conjurador divino anterior. Entretanto, ele não recebe qualquer outro benefício daquela classe (chance aprimorada de Expulsar/Fascinar mortos-vivos, utilizações adicionais de remover doenças, etc.). Essencialmente, isso significa que o nível de inquisidor da igreja é somado ao nível de outra classe capaz de conjurar magias divinas do personagem e, depois disso, sua quantidade de magias diárias é determinada. Por exemplo, Garjin, um clérigo de 8º nível, adquire um nível de inquisidor da igreja, recebendo novas magias como se tivesse atingido o 9º nível de clérigo, mas usando os demais aspectos da progressão de nível — como o bônus base de ataque e o bônus base de resistência — da classe de prestígio. Se, em seguida, ele adquirir um nível de clérigo, tornando-se um clérigo de 9º nível/inquisidor de 1º, passará a conjurar e obter magias diárias como um clérigo de 10º nível. Caso o personagem tenha mais de uma classe capaz de conjurar magias divinas antes de se tornar um inquisidor da igreja, deverá escolher qual delas terá seu nível elevado para determinar a quantidade de magias diárias sempre que alcançar um novo nível como inquisidor da igreja."},{"name":"Imunidade à Escola Feitiço (Ext)","text":"Um inquisidor da igreja de 2º nível ou superior é imune a todas as magias e efeitos de feitiço."},{"name":"Transpor Ilusões (Sob)","text":"A partir do 3º nível, o inquisidor adquire a habilidade sobrenatural de transpor ilusões e disfarces, sem limite de uso diário. O personagem deve tocar a ilusão ou a criatura envolvida pelo efeito (como na magia alterar-se, por exemplo). Então, ele realiza um teste de conjurador como se tivesse lançado dissipar magia sobre o efeito ilusório. Caso obtenha sucesso, a ilusão será imediatamente dissipada. O bônus de +4 nos testes de dissipar do inquisidor (o poder concedido pelo domínio Inquisição) também é aplicado a esse teste. Além disso, o inquisidor recebe +4 de bônus de competência em testes de Observar contra a perícia Disfarces."},{"name":"Imunidade à Escola Compulsão (Ext)","text":"Um inquisidor da igreja de 5º nível ou superior é imune a todas as magias e efeitos de compulsão."},{"name":"Induzir Metamorfose (Sob)","text":"Um inquisidor da igreja de 6º nível ou superior é capaz de induzir uma criatura a assumir sua forma natural. O personagem deve obter sucesso num ataque de toque contra a criatura; depois disso, ele deve realizar um teste de conjurador como se tivesse lançado dissipar magia contra o efeito de metamorfose. O bônus de +4 nos testes de dissipar do inquisidor (o poder concedido pelo domínio Inquisição) também é aplicado a esse teste. Essa habilidade dissipa os efeitos de alterar-se, metamorfosear-se, alterar forma, e as habilidades de mudança de forma, sejam excepcionais, similares a magia ou sobrenaturais. A criatura afetada não conseguirá alterar sua forma durante 1d6 rodadas. Essa habilidade não tem limite diário de utilização."},{"name":"Imunidade à Possessão (Ext)","text":"Um inquisidor da igreja de 8º nível ou superior é imune às magias recipiente arcano, prender a alma, aprisionar a alma, à habilidade possessão dos fantasmas e qualquer magia ou efeito que possa retirar ou substituir a força vital do personagem. Ele ainda será capaz de viajar através dos planos usando projeção astral, caso queira."},{"name":"Discernir Mentiras (SM)","text":"Três vezes por dia, um inquisidor da igreja de 9º nível ou superior é capaz de conjurar discernir mentiras como uma habilidade similar a magia."},{"name":"Revelar a Verdade (Sob)","text":"Ao tocar uma criatura que tenha mentido para ele, um inquisidor de 9º nível ou superior poderá tentar forçá-la a dizer a verdade. A criatura deve realizar um teste de resistência de Vontade (CD 10 + nível do inquisidor + seu bônus de Carisma) para anular esse efeito de ação mental [compulsão]. Caso fracasse no teste de resistência, ela deve contar toda a verdade omitida. Não existe limite diário de uso para essa habilidade, mas o inquisidor apenas conseguirá ativá-la imediatamente depois de conjurar discernir mentiras sobre o alvo."}]}'::jsonb),
('dnd35.defensores.prestige.defensores-libertador-sagrado','Libertador Sagrado','Libertador Sagrado','Bônus Base de Ataque: +5. Tendência: Caótico e Bom. Talento: Vontade de Ferro. Diplomacia: 5 graduações.',10,ARRAY[]::text[],ARRAY['prestige']::text[],'v35-defensores','D&D 3.5 — Defensores da Fé',51,'dnd35','{"id":"defensores-libertador-sagrado","name":"Libertador Sagrado","hitDie":10,"requirements":["Bônus Base de Ataque: +5.","Tendência: Caótico e Bom.","Talento: Vontade de Ferro.","Diplomacia: 5 graduações."],"classSkills":["Adestrar Animais (Car)","Cavalgar (Des)","Concentração (Con)","Conhecimento (religião) (Int)","Cura (Sab)","Diplomacia (Car)","Intimidar (Car)","Ofícios (Int)","Profissão (Sab)","Sentir Motivação (Sab)"],"skillPointsPerLevel":"2 + modificador de Inteligência","weaponArmor":"Os libertadores sagrados sabem usar todas as armas simples e comuns, todos os tipos de armadura e escudos.","levels":[{"level":1,"bab":"+1","fort":"+2","ref":"+0","will":"+2","special":"Detectar o mal, resistência a encantamentos","spellsPerDay":[0,null,null,null]},{"level":2,"bab":"+2","fort":"+3","ref":"+0","will":"+3","special":"Graça divina, destruir o mal","spellsPerDay":[1,null,null,null]},{"level":3,"bab":"+3","fort":"+3","ref":"+1","will":"+3","special":"Expulsar mortos-vivos, imunidade a feitiços e compulsões","spellsPerDay":[1,0,null,null]},{"level":4,"bab":"+4","fort":"+4","ref":"+1","will":"+4","special":"","spellsPerDay":[1,1,null,null]},{"level":5,"bab":"+5","fort":"+4","ref":"+1","will":"+4","special":"Companheiro Celestial","spellsPerDay":[1,1,0,null]},{"level":6,"bab":"+6","fort":"+5","ref":"+2","will":"+5","special":"","spellsPerDay":[1,1,1,null]},{"level":7,"bab":"+7","fort":"+5","ref":"+2","will":"+5","special":"Subversão","spellsPerDay":[2,1,1,0]},{"level":8,"bab":"+8","fort":"+6","ref":"+2","will":"+6","special":"","spellsPerDay":[2,1,1,1]},{"level":9,"bab":"+9","fort":"+6","ref":"+3","will":"+6","special":"","spellsPerDay":[2,2,1,1]},{"level":10,"bab":"+10","fort":"+7","ref":"+3","will":"+7","special":"","spellsPerDay":[2,2,2,1]}],"features":[{"name":"Magias","text":"A partir do 1º nível, um libertador sagrado adquire a habilidade de conjurar uma pequena quantidade de magias divinas. Para conjurar magias, um personagem deve ter uma pontuação em Sabedoria igual ou superior a 10 + o nível da magia; portanto, um personagem de Sabedoria 10 ou inferior não conseguirá fazê-lo. As magias adicionais do libertador sagrado são baseadas em Sabedoria; a Classe de Dificuldade de um teste de resistência contra essas magias equivale a 10 + nível da magia + modificador de Sabedoria. Quando um libertador recebe 0 magias de um determinado nível (como 0 magias de 1º nível logo no 1º nível de experiência), recebe apenas magias adicionais. Um personagem que não receba magias adicionais em qualquer nível ainda não é capaz de conjurá-las. Ele tem acesso a qualquer magia da lista, desde que seja capaz de lançá-la, e pode escolher livremente qual preparar. Um libertador prepara e conjura magias como um clérigo (mas não pode usar a Conversão Espontânea para lançar magias de cura no lugar de uma magia preparada)."},{"name":"Detectar o Mal (SM)","text":"O libertador sagrado pode usar detectar o mal livremente, como uma habilidade similar a magia. Essa habilidade duplica os efeitos da magia detectar o mal."},{"name":"Resistência a Encantamentos (Sob)","text":"Os libertadores sagrados recebem +2 de bônus de moral em todos os testes de resistência contra magias ou efeitos de encantamento."},{"name":"Graça Divina (Sob)","text":"O libertador sagrado de 2º nível ou superior aplica seu modificador de Carisma (caso seja positivo) como um bônus em todos os seus testes de resistência."},{"name":"Destruir o Mal (Sob)","text":"Uma vez por dia, um libertador sagrado de 2º nível ou superior pode tentar destruir o mal usando um ataque regular. Ao fazê-lo, ele soma seu modificador de Carisma (caso seja positivo) na sua jogada de ataque, causando 1 ponto de dano adicional por nível de experiência. Por exemplo, um libertador de 9º nível empunhando uma espada longa causaria 1d8+9 pontos de dano, além do dano devido a sua Força ou outros efeitos mágicos. Se o libertador, acidentalmente, tentar destruir uma criatura que não seja maligna, esta característica não gera efeitos, mas não poderá ser utilizada outra vez naquele dia. Destruir o mal é uma habilidade sobrenatural."},{"name":"Expulsar Mortos-Vivos (Sob)","text":"Quando um libertador sagrado atinge o 3º nível, adquire a habilidade sobrenatural de Expulsar Mortos-vivos. Ele expulsa mortos-vivos como um clérigo com dois níveis inferiores."},{"name":"Imunidade a Feitiços e Compulsões (Ext)","text":"A partir do 3º nível, o libertador sagrado torna-se imune a todos os efeitos das escolas feitiço e compulsão. Sua consciência lhe pertence totalmente e nenhuma criatura é capaz de controlar seus pensamentos ou ações."},{"name":"Companheiro Celestial","text":"Ao atingir o 5º nível ou posteriormente, o libertador sagrado é capaz de invocar um dos seguintes animais como seu companheiro celestial: gato, cachorro, águia, falcão, cavalo, coruja, pônei ou lobo (consulte o Apêndice 1 do Livro dos Monstros para obter as estatísticas básicas destes animais e o Apêndice 3 para obter o modelo de criaturas celestiais). Voluntariamente, essa criatura agirá como guardião (como um falcão), um auxiliar (como um gato) ou montaria (como um cavalo). O animal adquire DV e habilidades especiais conforme o nível do personagem. É impossível ter mais de um companheiro celestial simultaneamente. Se a criatura morrer, o libertador sagrado poderá invocar outra no dia seguinte. O novo companheiro possuirá todas as habilidades inerentes a uma criatura de um libertador do mesmo nível de experiência."},{"name":"Subversão (Sob)","text":"A partir do 7º nível, caso ele gaste 5 minutos dialogando com um personagem sob a influência de um efeito de compulsão ou feitiço, o libertador conseguirá ajudá-lo a superar o encantamento. Usando uma ação de rodada completa, o libertador toca o personagem enfeitiçado (realizando uma jogada de ataque de toque, se necessário) e invoca seu poder divino interior. Imediatamente depois, o personagem afetado deve realizar outro teste de resistência, usando seus próprios modificadores mais o bônus de Carisma do libertador sagrado. Se o resultado igualar ou superar a CD original, o personagem estará livre do efeito de feitiço ou compulsão."},{"name":"Código de Conduta","text":"O libertador sagrado deve conservar sua tendência (Caótico e Bom) e perderá todas as habilidades especiais da classe se cometer voluntariamente qualquer ato maligno. Conforme esperado dessa tendência, o código de conduta dos libertadores está limitado a essa diretriz — não há regras formais e rígidas."},{"name":"Libertadores Ex-paladinos","text":"Não é completamente incomum um paladino se afastar do inabalável caminho da ordem durante sua exaustiva luta pelo bem, tornando-se um libertador sagrado. Na maioria das vezes, o ex-paladino que seleciona essa classe de prestígio nunca mais recupera suas habilidades da classe anterior. Entretanto, os níveis de paladino contribuem nas habilidades destruir o mal e expulsar mortos-vivos do atual libertador. Ambas consideram o nível de experiência total do personagem; logo, a habilidade ''destruir o mal'' e a capacidade de expulsar mortos-vivos do ex-paladino consideram os níveis de libertador sagrado e de paladino somados."}],"spellList":{"1":["abençoar arma","arma mágica","auxílio divino","benção","curar ferimentos leves","detectar mortos-vivos","detectar venenos","remover medo","resistência a elementos","resistência","virtude"],"2":["acalmar emoções","ajuda","curar ferimentos moderados","força do touro","proteger outro","remover paralisia","retardar envenenamento","suportar elementos"],"3":["arma mágica aprimorada","círculo mágico contra o mal","curar ferimentos graves","discernir mentiras","dissipar magia","oração","remover maldição"],"4":["curar ferimentos críticos","dissipar o mal","espada sagrada","movimentação livre","neutralizar venenos","proteção contra a morte"]},"companion":{"animals":["gato","cachorro","águia","falcão","cavalo","coruja","pônei","lobo"],"rows":[{"characterLevel":"12 ou menos","bonusHd":"+2","naturalArmor":"+1","strengthAdjust":"+1","int":6,"special":"Evasão aprimorada, partilhar magias, vínculo empático, partilhar testes de resistência"},{"characterLevel":"13-15","bonusHd":"+4","naturalArmor":"+3","strengthAdjust":"+2","int":7,"special":"Falar com o mestre"},{"characterLevel":"16-18","bonusHd":"+6","naturalArmor":"+5","strengthAdjust":"+3","int":8,"special":"Laço de sangue"},{"characterLevel":"19-20","bonusHd":"+8","naturalArmor":"+7","strengthAdjust":"+4","int":9,"special":"Resistência à magia"}],"notes":"DV de bônus: dados de vida extras (d8). Armadura natural e ajuste de Força somam-se aos do animal. Resistência à magia = nível do libertador sagrado + 5. Vínculo empático: alcance máximo 1,5 km. Laço de sangue: +2 de bônus em ataques, testes de resistência e testes ao ver o libertador ameaçado ou ferido."}}'::jsonb),
('dnd35.defensores.prestige.defensores-mestre-das-mortalhas','Mestre das Mortalhas','Mestre das Mortalhas','Bônus Base de Resistência: Vontade +5. Tendência: Qualquer uma, exceto Bom. Concentração: 10 graduações. Identificar Magia: 10 graduações. Magias: Capacidade de conjurar magias divinas e acesso a um dos seguintes domínios: Morte, Mal ou Proteção. Para esse propósito, considera-se que os personagens capazes de lançar uma magia desses domínios têm acesso a eles. Especial: Capacidade de canalizar energia negativa.',8,ARRAY[]::text[],ARRAY['prestige']::text[],'v35-defensores','D&D 3.5 — Defensores da Fé',51,'dnd35','{"id":"defensores-mestre-das-mortalhas","name":"Mestre das Mortalhas","hitDie":8,"requirements":["Bônus Base de Resistência: Vontade +5.","Tendência: Qualquer uma, exceto Bom.","Concentração: 10 graduações.","Identificar Magia: 10 graduações.","Magias: Capacidade de conjurar magias divinas e acesso a um dos seguintes domínios: Morte, Mal ou Proteção. Para esse propósito, considera-se que os personagens capazes de lançar uma magia desses domínios têm acesso a eles.","Especial: Capacidade de canalizar energia negativa."],"classSkills":["Concentração (Con)","Conhecimento (arcano) (Int)","Conhecimento (religião) (Int)","Diplomacia (Car)","Espionar (Int, perícia exclusiva)","Identificar Magia (Int)","Ofícios (Int)","Profissão (Sab)"],"skillPointsPerLevel":"2 + modificador de Inteligência","weaponArmor":"Os mestres das mortalhas sabem usar todas as armas simples, todos os tipos de armadura e escudos.","levels":[{"level":1,"bab":"+1","fort":"+0","ref":"+0","will":"+2","special":"Expulsão Adicional"},{"level":2,"bab":"+2","fort":"+0","ref":"+0","will":"+3","special":""},{"level":3,"bab":"+3","fort":"+1","ref":"+1","will":"+3","special":"Invocar Mortos-vivos I"},{"level":4,"bab":"+4","fort":"+1","ref":"+1","will":"+4","special":""},{"level":5,"bab":"+5","fort":"+1","ref":"+1","will":"+4","special":"Invocar Mortos-vivos II"},{"level":6,"bab":"+6","fort":"+2","ref":"+2","will":"+5","special":""},{"level":7,"bab":"+7","fort":"+2","ref":"+2","will":"+5","special":"Invocar Mortos-vivos III"},{"level":8,"bab":"+8","fort":"+2","ref":"+2","will":"+6","special":""},{"level":9,"bab":"+9","fort":"+3","ref":"+3","will":"+6","special":"Invocar Mortos-vivos IV"},{"level":10,"bab":"+10","fort":"+3","ref":"+3","will":"+7","special":""}],"features":[{"name":"Magias","text":"Um mestre das mortalhas conjura magias como um clérigo (consulte a Tabela 3-6: O Clérigo, na pág. 30 do Livro do Jogador) e tem acesso irrestrito à lista geral de magias dessa classe. O nível de mestre das mortalhas é adicionado ao nível de clérigo para determinar a quantidade de magias diárias e seus efeitos (veja Magias Diárias, a seguir). Além disso, o personagem adquire acesso aos domínios Morte, Mal e Proteção."},{"name":"Magias Diárias","text":"Um mestre das mortalhas nunca abandona seu treinamento mágico divino, desenvolvendo-o junto com suas perícias na classe. Portanto, quando o personagem atinge um novo nível na classe de prestígio, adquire mais magias divinas por dia — como se estivesse avançando um nível como clérigo. Entretanto, ele não recebe qualquer outro benefício daquela classe (chance aprimorada de Expulsar/Fascinar mortos-vivos, conversão espontânea, etc.). Essencialmente, isso significa que o nível de mestre das mortalhas é somado ao nível de clérigo do personagem e, depois disso, sua quantidade de magias diárias é determinada."},{"name":"Expulsão Adicional","text":"No 1º nível, o mestre das mortalhas recebe Expulsão Adicional como um talento extra. Esse talento lhe concede mais quatro utilizações de Expulsar/Fascinar Mortos-vivos por dia."},{"name":"Invocar Mortos-Vivos I (SM)","text":"Essa habilidade similar a magia é idêntica a invocar criaturas I, com as seguintes exceções: o mestre das mortalhas é capaz de invocar uma ou duas sombras, um ou dois allips ou uma criatura de cada tipo. Quando é ativada, o mestre das mortalhas precisa determinar a duração da invocação; normalmente, as criaturas permanecem sob seu controle durante 1 rodada a cada nível de mestre das mortalhas, mas é possível reduzir essa duração. Caso o personagem seja capaz de falar com os mortos-vivos invocados, poderá conduzi-los como na magia invocar criaturas. Se as criaturas permanecerem no local até eliminar o último adversário, elas atacarão o mestre das mortalhas, exceto se ele obtiver sucesso num teste de Expulsão que afete todas as criaturas até elas decidirem partir. Essa habilidade pode ser utilizada uma quantidade de vezes por dia equivalente a 3 + o bônus de Carisma do mestre das mortalhas (mínimo 1)."},{"name":"Invocar Mortos-Vivos II (SM)","text":"Como invocar mortos-vivos I, mas o mestre das mortalhas é capaz de invocar uma ou duas aparições, ou qualquer combinação de sombras e allips que não exceda quatro criaturas."},{"name":"Invocar Mortos-Vivos III (SM)","text":"Como invocar mortos-vivos I, mas o mestre das mortalhas é capaz de invocar um ou dois espectros, ou qualquer combinação de aparições, sombras e allips que não exceda quatro criaturas."},{"name":"Invocar Mortos-Vivos IV (SM)","text":"Como invocar mortos-vivos I, mas o mestre das mortalhas é capaz de invocar qualquer combinação de espectros, aparições, sombras e allips que não exceda oito criaturas."},{"name":"Invocando Mortos-vivos","text":"Depois que o mestre das mortalhas invocar seus mortos-vivos, existem apenas três desfechos possíveis. 1) O morto-vivo será destruído ou eliminado em combate. 2) O morto-vivo partirá quando a duração do efeito terminar. 3) O morto-vivo atacará o mestre das mortalhas quando todos os demais oponentes forem eliminados. Nessa última hipótese, o personagem deverá utilizar outros poderes ou seus aliados para evitar a ira dos mortos-vivos invocados."}],"spellList":{"1":["romper mortos-vivos","raio do enfraquecimento","toque macabro"],"2":["aterrorizar","mão espectral","toque do carniçal"],"3":["descanso tranqüilo","imobilizar mortos-vivos","praga","toque vampírico"],"4":["drenar temporário","medo"],"5":["recipiente arcano"]}}'::jsonb),
('dnd35.defensores.prestige.defensores-oraculo-divino','Oráculo Divino','Oráculo Divino','Talento: Foco em Perícia (Espionar). Espionar: 10 graduações.',6,ARRAY[]::text[],ARRAY['prestige']::text[],'v35-defensores','D&D 3.5 — Defensores da Fé',51,'dnd35','{"id":"defensores-oraculo-divino","name":"Oráculo Divino","hitDie":6,"requirements":["Talento: Foco em Perícia (Espionar).","Espionar: 10 graduações."],"classSkills":["Concentração (Con)","Conhecimento (religião) (Int)","Cura (Sab)","Espionar (Int, perícia exclusiva)","Identificar Magia (Int)","Intimidar (Car)","Ofícios (Int)","Profissão (Sab)"],"skillPointsPerLevel":"2 + modificador de Inteligência","weaponArmor":"Os oráculos divinos sabem usar todas as armas simples. Eles não sabem usar nenhum tipo de armadura ou escudos, mas quase sempre conservam essa habilidade de sua(s) antiga(s) classe(s).","levels":[{"level":1,"bab":"+0","fort":"+0","ref":"+0","will":"+2","special":"Domínio de Prestígio: Adivinhação, bônus em Espionar","spellcastingAdvance":"+1 nível de classe existente"},{"level":2,"bab":"+1","fort":"+0","ref":"+0","will":"+3","special":"Premonição","spellcastingAdvance":"+1 nível de classe existente"},{"level":3,"bab":"+1","fort":"+1","ref":"+1","will":"+3","special":"Adivinhação aprimorada","spellcastingAdvance":"+1 nível de classe existente"},{"level":4,"bab":"+2","fort":"+1","ref":"+1","will":"+4","special":"Esquiva sobrenatural (bônus de Des na CA)","spellcastingAdvance":"+1 nível de classe existente"},{"level":5,"bab":"+2","fort":"+1","ref":"+1","will":"+4","special":"","spellcastingAdvance":"+1 nível de classe existente"},{"level":6,"bab":"+3","fort":"+2","ref":"+2","will":"+5","special":"Esquiva sobrenatural (não pode ser flanqueado)","spellcastingAdvance":"+1 nível de classe existente"},{"level":7,"bab":"+3","fort":"+2","ref":"+2","will":"+5","special":"","spellcastingAdvance":"+1 nível de classe existente"},{"level":8,"bab":"+4","fort":"+2","ref":"+2","will":"+6","special":"Esquiva sobrenatural (+1 contra armadilhas)","spellcastingAdvance":"+1 nível de classe existente"},{"level":9,"bab":"+4","fort":"+3","ref":"+3","will":"+6","special":"","spellcastingAdvance":"+1 nível de classe existente"},{"level":10,"bab":"+5","fort":"+3","ref":"+3","will":"+7","special":"Imunidade à surpresa","spellcastingAdvance":"+1 nível de classe existente"}],"features":[{"name":"Conjuração","text":"Os oráculos divinos nunca abandonam seu treinamento mágico, desenvolvendo-o junto com suas perícias na classe. Portanto, quando o personagem atinge um novo nível na classe de prestígio, adquire mais magias diárias — como se estivesse avançando um nível na sua classe de conjurador anterior. Entretanto, ele não recebe qualquer outro benefício daquela classe (chance aprimorada de Expulsar/Fascinar mortos-vivos, forma selvagem, etc.). Essencialmente, isso significa que o nível de oráculo divino é somado ao nível de outra classe capaz de conjurar magias do personagem e, depois disso, sua quantidade de magias diárias é determinada. Por exemplo, Cassandra, uma clériga de 10º nível, adquire um nível de oráculo divino, recebendo novas magias como se tivesse atingido o 11º nível de clérigo, mas usando os demais aspectos da progressão de nível — como o bônus base de ataque e o bônus base de resistência — da classe de prestígio. Se, em seguida, ela adquirir um nível de clérigo, tornando-se uma clériga de 11º nível/oráculo de 1º, passará a conjurar e obter magias diárias como um clérigo de 12º nível. Caso o personagem tenha mais de uma classe capaz de conjurar magias antes de se tornar um oráculo divino, deverá escolher qual delas terá seu nível elevado para determinar a quantidade de magias diárias sempre que alcançar um novo nível na classe de prestígio."},{"name":"Domínio de Prestígio","text":"Quando seleciona a classe oráculo divino, o personagem adquire acesso ao domínio Adivinhação, descrito no Capítulo 4: Magias Divinas. O personagem recebe o poder concedido desse domínio (+2 níveis de conjurador para lançar magias de adivinhação) e será capaz de preparar as magias indicadas como suas magias de domínio diárias."},{"name":"Bônus em Espionar (Sob)","text":"Um oráculo divino recebe +2 de bônus sagrado em todos os testes de Espionar."},{"name":"Premonição (Ext)","text":"A partir do 2º nível, quando obtiver sucesso num teste de resistência de Reflexos contra qualquer ataque adequado (como um sopro de dragão ou uma bola de fogo) para reduzir o dano à metade, o oráculo divino não sofrerá nenhum dano, uma vez que sua premonição lhe permite evitar o perigo com mais velocidade. Esta forma de evasão funciona a despeito do tipo de armadura que o oráculo estiver usando, diferente da habilidade Evasão dos monges e ladinos."},{"name":"Adivinhação Aprimorada (Ext)","text":"A partir do 3º nível, o personagem adiciona seu nível de oráculo divino à porcentagem de chance de sucesso para magias como augúrio ou adivinhação. Por exemplo, se um clérigo 11/oráculo 4 conjurar adivinhação, sua chance de sucesso seria 70% (base) + 15% (1% por nível de conjurador) + 4% (seu nível de oráculo), totalizando 89%."},{"name":"Esquiva Sobrenatural (Ext)","text":"A partir do 4º nível, o oráculo divino adquire a habilidade extraordinária de reagir ao perigo antes que seus sentidos lhe advirtam da forma normal. O personagem conserva seu bônus de Destreza na CA (se houver) mesmo se for surpreendido ou atacado por um inimigo invisível (ele ainda perde seu bônus de Destreza na CA se estiver imobilizado). A partir do 6º nível, ele não poderá mais ser flanqueado, pois reagirá a seus oponentes de ambos os lados tão facilmente como se estivesse reagindo a um atacante solitário. Essa defesa impedirá que os ladinos realizem ataques furtivos quando estiverem flanqueando o personagem. A única exceção a essa esquiva se aplica aos ladinos de quatro ou mais níveis superiores ao oráculo, que poderão flanqueá-lo e realizar seu ataque furtivo. A partir do 8º nível, ele adquire um senso intuitivo que o adverte do perigo de armadilhas, concedendo-lhe +1 de bônus para os testes de resistência de Reflexos realizados afim de evitá-las e +1 de esquiva na CA contra ataques procedentes delas."},{"name":"Imunidade a Surpresa (Ext)","text":"No 10º nível, a sensibilidade do oráculo divino ao perigo fica tão aguçada que é impossível surpreendê-lo. Ele sempre poderá realizar uma ação parcial durante a rodada surpresa, a menos que esteja imobilizado."}]}'::jsonb),
('dnd35.defensores.prestige.defensores-punho-sagrado','Punho Sagrado','Punho Sagrado','Base de Ataque: +4. Talentos: Prontidão, Reflexos de Combate e Ataque Desarmado Aprimorado. Magia: Capacidade de conjurar magias divinas.',8,ARRAY[]::text[],ARRAY['prestige']::text[],'v35-defensores','D&D 3.5 — Defensores da Fé',51,'dnd35','{"id":"defensores-punho-sagrado","name":"Punho Sagrado","hitDie":8,"requirements":["Base de Ataque: +4.","Talentos: Prontidão, Reflexos de Combate e Ataque Desarmado Aprimorado.","Magia: Capacidade de conjurar magias divinas."],"classSkills":["Acrobacia (Des)","Arte da Fuga (Des)","Concentração (Con)","Cura (Sab)","Equilíbrio (Des)","Profissão (Sab)","Saltar (For)"],"skillPointsPerLevel":"4 + modificador de Inteligência","weaponArmor":"Os punhos sagrados se recusam a utilizar armas e escudos. Eles podem usar apenas armaduras leves sem quebrar seus votos religiosos.","levels":[{"level":1,"bab":"+1","fort":"+2","ref":"+2","will":"+0","special":"Rajada de ataques, domínio adicional, punhos poderosos","spellsPerDay":[0,null,null,null]},{"level":2,"bab":"+2","fort":"+3","ref":"+3","will":"+0","special":"Evasão, magias em combate","spellsPerDay":[1,null,null,null]},{"level":3,"bab":"+3","fort":"+3","ref":"+3","will":"+1","special":"Esquiva sobrenatural (bônus de Des na CA)","spellsPerDay":[1,0,null,null]},{"level":4,"bab":"+4","fort":"+4","ref":"+4","will":"+1","special":"","spellsPerDay":[1,1,null,null]},{"level":5,"bab":"+5","fort":"+4","ref":"+4","will":"+1","special":"Esquiva Sobrenatural (não pode ser flanqueado)","spellsPerDay":[1,1,0,null]},{"level":6,"bab":"+6","fort":"+5","ref":"+5","will":"+2","special":"Percepção às cegas","spellsPerDay":[1,1,1,null]},{"level":7,"bab":"+7","fort":"+5","ref":"+5","will":"+2","special":"Chamas sagradas","spellsPerDay":[2,1,1,0]},{"level":8,"bab":"+8","fort":"+6","ref":"+6","will":"+2","special":"Golpe sem sombra","spellsPerDay":[2,1,1,1]},{"level":9,"bab":"+9","fort":"+6","ref":"+6","will":"+3","special":"","spellsPerDay":[2,2,1,1]},{"level":10,"bab":"+10","fort":"+7","ref":"+7","will":"+3","special":"Armadura Interior","spellsPerDay":[2,2,2,1]}],"features":[{"name":"Código de Conduta","text":"Um membro de uma ordem de punhos sagrados deve se recusar a empunhar qualquer tipo de arma. Caso transporte ou utilize intencionalmente qualquer arma, ele perderá todas as suas magias e características da classe — e não conseguirá adquirir níveis na classe de prestígio — até que faça uma penitência (veja a descrição da magia penitência, pág. 245 do Livro do Jogador)."},{"name":"Magias","text":"A partir do 1º nível, um punho sagrado adquire a habilidade de conjurar uma pequena quantidade de magias divinas. Para conjurar magias, um personagem deve ter uma pontuação em Sabedoria igual ou superior a 10 + o nível da magia; portanto, um personagem de Sabedoria 10 ou inferior não conseguirá fazê-lo. As magias adicionais do punho são baseadas em Sabedoria; a Classe de Dificuldade de um teste de resistência contra essas magias equivale a 10 + nível da magia + modificador de Sabedoria. Quando um punho sagrado ganha 0 magias de um determinado nível (como 0 magias de 1º nível logo no 1º nível de experiência), recebe apenas magias adicionais. Um personagem que não receba magias adicionais em qualquer nível ainda não é capaz de conjurá-las. A relação das magias do punho sagrado é descrita a seguir; ele tem acesso a qualquer magia da lista, desde que seja capaz de lançá-la, e pode escolher livremente qual preparar. Um punho sagrado prepara e conjura magias como um clérigo (mas não pode usar a Conversão Espontânea para lançar magias de cura no lugar de uma magia preparada)."},{"name":"Domínio Adicional","text":"Quando seleciona a classe punho sagrado, o personagem adquire acesso a um domínio de sua divindade."},{"name":"Combate Desarmado (Ext)","text":"Um punho sagrado é altamente treinado em combate desarmado, obtendo vantagens consideráveis nesse estilo. Durante uma luta, ele é capaz de usar seus punhos, cotovelos, joelhos ou pés para golpear. Para um punho sagrado em combate desarmado, realizar um ataque com a mão inábil não representa dificuldade. Ele pode escolher causar dano por contusão ou dano normal; o personagem causa mais dano que o normal, conforme indicado na tabela abaixo. Essa habilidade não se acumula com o ataque desarmado dos monges (utilize o maior valor entre ambos). Tamanho do Punho Sagrado — nível 1º: Pequeno 1d4, Médio ou Grande 1d6; 5º: 1d6 / 1d8; 8º: 1d8 / 1d10; 10º: 1d10 / 1d12."},{"name":"Rajada de Ataques (Ext)","text":"Um punho sagrado consegue atacar com uma rajada de golpes, sacrificando sua precisão. Ao fazê-lo, ele adquire um ataque adicional na mesma rodada, usando seu maior bônus de ataque, mas todos os golpes realizados nessa rodada sofrem -2 de penalidade. Esta penalidade permanece durante uma rodada completa, então afeta qualquer ataque de oportunidade que o punho sagrado faça. Para utilizar essa habilidade, o punho sagrado deve escolher a ação de ataque total (veja a pág. 124 do Livro do Jogador)."},{"name":"Punhos Poderosos (Sob)","text":"Os punhos sagrados conseguem ignorar alguns tipos de redução de dano. No 1º nível, seus golpes são considerados armas +1 para superar a redução de dano dos adversários. A partir do 3º nível, eles serão considerados armas +2 para essa finalidade; no 6º nível, serão considerados armas +3; a partir do 9º nível, serão considerados armas +4. Esses bônus não afetam as jogadas de ataque, nem são adicionados ao dano causado pelo golpe. Essa habilidade não se acumula com o ataque chi dos monges (utilize o maior bônus entre ambas)."},{"name":"Evasão (Ext)","text":"Um punho sagrado é capaz de evitar ataques mágicos ou incomuns através de sua agilidade extraordinária. Quando obtiver sucesso num teste de resistência de Reflexos contra qualquer ataque adequado (como um sopro de dragão ou uma bola de fogo) para reduzir o dano à metade, o punho sagrado não sofrerá nenhum dano. Essa habilidade somente pode ser utilizada quando o personagem estiver sem armadura ou usando armaduras leves. Essa habilidade se acumula com a Evasão de outras classes (some os níveis para determinar a aquisição de Evasão Aprimorada)."},{"name":"Magias em Combate (Ext)","text":"No 2º nível, o punho sagrado recebe este talento gratuitamente."},{"name":"Esquiva Sobrenatural (Ext)","text":"A partir do 3º nível, o punho sagrado adquire a habilidade de reagir ao perigo antes que seus sentidos lhe advirtam da forma normal. O personagem conserva seu bônus de Destreza na CA (se houver) mesmo se for surpreendido ou atacado por um inimigo invisível (ele ainda perde seu bônus de Destreza na CA se estiver imobilizado). A partir do 5º nível, ele não poderá mais ser flanqueado, pois reagirá a seus oponentes de ambos os lados tão facilmente como se estivesse reagindo a um atacante solitário. Essa defesa impedirá que os ladinos realizem ataques furtivos quando estiverem flanqueando o personagem. A única exceção a essa esquiva se aplica aos ladinos de quatro ou mais níveis superiores ao punho, que poderão flanqueá-lo e realizar seu ataque furtivo. Essa habilidade somente pode ser utilizada quando o personagem estiver sem armadura ou usando armaduras leves. Essa habilidade se acumula com a Esquiva Sobrenatural de outras classes (some os níveis para determinar a aquisição de bônus adicionais)."},{"name":"Percepção às Cegas (Ext)","text":"Essa habilidade, adquirida no 6º nível, concede sensibilidade a vibrações, faro e audição aguçada ao punho sagrado, permitindo-lhe manobrar e lutar como se estivesse enxergando. Essa percepção alcança um raio de 9 m. A invisibilidade e a escuridão são irrelevantes, embora ainda seja impossível distinguir criaturas etéreas. Não é necessário realizar testes de Observar ou Ouvir para perceber uma criatura dentro da área afetada."},{"name":"Chamas Sagradas (SM)","text":"No 7º nível, o punho sagrado é capaz de usar uma ação padrão e invocar chamas sagradas em torno de suas mãos e pés. Em vez de causar o dano normal, os golpes dessa chama sagrada causam o seguinte dano: 1d6 + bônus de Sabedoria + nível da classe de prestígio. O dano máximo do ataque será 1d6+15; metade dele será dano por fogo e o restante será causado por energia sagrada (logo, impossível de reduzir com efeitos que ignorem o dano por fogo). Um ataque com as chamas sagradas pode ser combinado com a rajada de ataques."},{"name":"Golpe Sem Sombra (Ext)","text":"A partir do 8º nível, o punho sagrado é capaz de somar seu bônus de Sabedoria nas suas jogadas de ataque e dano. Além disso, seus golpes desarmados são considerados armas mágicas com um bônus de melhoria equivalente ao seu modificador de Sabedoria, mas somente para superar a redução de dano dos adversários; esse modificador se acumula com o bônus de punhos poderosos ou ataque chi. A mente, o corpo e a vontade do punho sagrado estão ajustados como um único instrumento."},{"name":"Armadura Interior (Ext)","text":"No 10º nível, a tranqüilidade interna de um punho sagrado o protege das ameaças externas. Ele pode adquirir +4 de bônus intuitivo na CA, +4 de bônus de resistência nos testes de resistência e RM equivalente ao seu nível de experiência; esses efeitos permanecem ativos durante uma quantidade de rodadas igual ao modificador de Sabedoria do personagem. Caso o modificador de Sabedoria seja +0 ou negativo, será impossível ativar a armadura interior. Essa habilidade pode ser utilizada um número de vezes por dia equivalente ao nível de classe do personagem."}],"spellList":{"1":["abençoar água*","abençoar funeral†","amaldiçoar água*","arma mágica**","auxílio divino","compreensão de linguagens","curar ferimentos leves*","escudo da fé","escudo entrópico","infligir ferimentos leves*","invisibilidade contra mortos-vivos","pedra encantada**","proteção contra o caos/mal/bem/ordem*","resistência a elementos","santuário"],"2":["ajuda","arbustos**†","augúrio","curar ferimentos moderados*","descanso tranqüilo","dissimular tendência","drenar força vital","falar com animais","força do touro","infligir ferimentos moderados*","restauração menor","retardar envenenamento","suportar elementos","vigor"],"3":["caminhar na água","chama contínua","chamas da fé†","círculo mágico contra o caos/mal/bem/ordem*","curar ferimentos graves*","escuridão profunda","espinhos**†","falar com plantas","infligir ferimentos graves*","luz do dia","maldição dos brutos†","mesclar-se às rochas","moldar rochas","obscurecer objeto","praga*","proteção contra elementos","proteção contra energia negativa","purgar invisibilidade","remover doenças*","remover maldição*","respirar na água","rogar maldição*","roupa encantada","símbolo de proteção","visão seqüencial†"],"4":["adivinhação","caminhar no ar","condição","curar ferimentos críticos*","envenenamento*","garras da besta†","idiomas","infligir ferimentos críticos*","movimentação livre","neutralizar venenos*","poder divino","proteção contra a morte","restauração","potência infinita†","transferência de poder divino"]}}'::jsonb),
('dnd35.defensores.prestige.defensores-templario','Templário','Templário','Bônus Base de Ataque: +5. Talentos: Tolerância, Foco em Arma (arma favorita de sua divindade). Conhecimento (religião): 8 graduações.',10,ARRAY[]::text[],ARRAY['prestige']::text[],'v35-defensores','D&D 3.5 — Defensores da Fé',51,'dnd35','{"id":"defensores-templario","name":"Templário","hitDie":10,"requirements":["Bônus Base de Ataque: +5.","Talentos: Tolerância, Foco em Arma (arma favorita de sua divindade).","Conhecimento (religião): 8 graduações."],"classSkills":["Concentração (Con)","Conhecimento (religião) (Int)","Cura (Sab)","Natação (For)","Ofícios (Int)","Profissão (Sab)","Saltar (For)"],"skillPointsPerLevel":"2 + modificador de Inteligência","weaponArmor":"Os templários sabem usar todas as armas simples e comuns, todos os tipos de armadura e escudos.","levels":[{"level":1,"bab":"+1","fort":"+2","ref":"+0","will":"+2","special":"Têmpera, especialização em arma","spellsPerDay":[0,null,null,null]},{"level":2,"bab":"+2","fort":"+3","ref":"+0","will":"+3","special":"Destruição 1/dia","spellsPerDay":[1,null,null,null]},{"level":3,"bab":"+3","fort":"+3","ref":"+1","will":"+3","special":"Redução de dano 1/—","spellsPerDay":[1,0,null,null]},{"level":4,"bab":"+4","fort":"+4","ref":"+1","will":"+4","special":"Talento adicional","spellsPerDay":[1,1,null,null]},{"level":5,"bab":"+5","fort":"+4","ref":"+1","will":"+4","special":"","spellsPerDay":[1,1,0,null]},{"level":6,"bab":"+6","fort":"+5","ref":"+2","will":"+5","special":"Redução de dano 2/—","spellsPerDay":[1,1,1,null]},{"level":7,"bab":"+7","fort":"+5","ref":"+2","will":"+5","special":"Destruição 2/dia","spellsPerDay":[2,1,1,0]},{"level":8,"bab":"+8","fort":"+6","ref":"+2","will":"+6","special":"Talento adicional","spellsPerDay":[2,1,1,1]},{"level":9,"bab":"+9","fort":"+6","ref":"+3","will":"+6","special":"Redução de dano 3/—","spellsPerDay":[2,2,1,1]},{"level":10,"bab":"+10","fort":"+7","ref":"+3","will":"+7","special":"","spellsPerDay":[2,2,2,1]}],"features":[{"name":"Têmpera (Sob)","text":"A benção especial dos templários lhes permite ignorar os efeitos mágicos capazes de prejudicá-los. Caso um templário obtenha sucesso num teste de resistência de Fortitude ou Vontade que normalmente reduziria o efeito de uma magia ou habilidade similar, ele anulará por completo os efeitos dessa magia. Somente as magias que possuem a indicação \"Vontade parcial\", \"Fortitude para metade\" ou semelhantes na descrição de seus Testes de Resistência são afetadas por esta habilidade."},{"name":"Especialização em Arma","text":"O templário recebe gratuitamente o talento Especialização em Arma com a arma predileta da sua divindade."},{"name":"Magias","text":"A partir do 1º nível, um templário adquire a habilidade de conjurar uma pequena quantidade de magias divinas. Para conjurar magias, um personagem deve ter uma pontuação em Sabedoria igual ou superior a 10 + o nível da magia; portanto, um personagem de Sabedoria 10 ou inferior não conseguirá fazê-lo. As magias adicionais do templário são baseadas em Sabedoria; a Classe de Dificuldade de um teste de resistência contra essas magias equivale a 10 + nível da magia + modificador de Sabedoria. Quando um templário recebe 0 magias de um determinado nível (como 0 magias de 1º nível logo no 1º nível de experiência), recebe apenas magias adicionais. Um personagem que não receba magias adicionais em qualquer nível ainda não é capaz de conjurá-las. A relação das magias do templário é descrita a seguir; ele tem acesso a qualquer magia da lista, desde que seja capaz de lançá-la, e pode escolher livremente qual preparar. Um templário prepara e conjura magias como um clérigo (mas não pode usar a Conversão Espontânea para lançar magias de cura no lugar de uma magia preparada)."},{"name":"Destruição (Sob)","text":"Uma vez por dia, um templário de 2º nível ou superior pode tentar destruir seu oponente usando um ataque regular. Ao fazê-lo, ele recebe +4 de bônus na sua jogada de ataque e causa 1 ponto de dano adicional por nível na classe de prestígio. O templário precisa declarar que vai utilizar a destruição antes de realizar a jogada de ataque (logo, um ataque fracassado gasta a tentativa). No 7º nível, ele adquire uma destruição adicional por dia. Se o templário possuir as habilidades \"destruir o mal\" ou \"destruir\" (proveniente da classe paladino ou do domínio Destruição, respectivamente), será capaz de utilizá-la mais uma vez por dia (ou mais duas no 7º nível). O bônus de ataque não é afetado, mas o dano adicional considera todos os níveis de classe pertinentes (o nível de templário, mais o nível de clérigo ou paladino, conforme a situação)."},{"name":"Redução de Dano (Ext)","text":"A partir do 3º nível, o templário adquire a habilidade de ignorar parte do dano de cada golpe ou ataque que sofra. Cada vez que o personagem sofrer dano, subtraia 1 da quantidade de pontos de vida perdida. No 6º nível, a redução de dano aumenta para 2 pontos por golpe e no 9º nível, para 3."},{"name":"Talentos Adicionais","text":"Um templário recebe um talento adicional no 4º nível e outro no 8º nível. Esses talentos devem ser escolhidos da seguinte lista: Ambidestria, Lutar às Cegas, Reflexos de Combate, Esquiva (Mobilidade, Deslocamento), Usar Arma Exótica*, Especialização (Desarmar Aprimorado, Imobilização Aprimorada, Ataque Giratório), Sucesso Decisivo Aprimorado*, Iniciativa Aprimorada, Ataque Desarmado Aprimorado (Desviar Objetos, Ataque Atordoante), Combate Montado (Arqueirismo Montado, Atropelar, Investida Montada, Investida Implacável), Tiro Certeiro (Tiro Longo, Precisão, Tiro Rápido, Tiro em Movimento), Ataque Poderoso (Trespassar, Encontrão Aprimorado, Separar, Trespassar Aprimorado), Saque Rápido, Combater com Duas Armas (Combater com Duas Armas Aprimorado), Acuidade com Arma*, Foco em Arma*. Os talentos que têm pré-requisitos estão listados entre parênteses, depois do talento inicial exigido. O templário pode escolher um talento marcado com um asterisco (*) mais de uma vez, selecionando uma arma diferente a cada vez. O templário ainda precisa atender todos os pré-requisitos de um talento, inclusive valores de habilidade e o bônus base de ataque mínimo."}],"spellList":{"1":["arma mágica","auxílio divino","benção","causar medo","comando","escudo da fé","escudo entrópico","montaria arcana"],"2":["acalmar emoções","ajuda","arma espiritual","cativar","força do touro","imobilizar pessoas","proteger outro","vigor"],"3":["cegueira/surdez","dissipar magia","luz cegante","luz do dia","oração","proteção contra energia negativa","purgar invisibilidade","roupa encantada"],"4":["arma mágica aprimorada","condição","movimentação livre","poder divino"]}}'::jsonb)
insert into public.catalog_items (id,name_pt,name_en,description_pt,item_category,level,price_gp,traits,ruleset,source_book,source_page,system_id,data) values
('dnd35.defensores.domain.defensores-dominio-adivinhacao','Adivinhação','Adivinhação','Suas magias de Adivinhação recebem +2 no nível de conjurador.','domain',1,null,ARRAY['Boccob','Obad-Hai','Pelor','Vecna']::text[],'v35-defensores','D&D 3.5 — Defensores da Fé',77,'dnd35','{"id":"defensores-dominio-adivinhacao","name":"Adivinhação","deities":["Boccob","Obad-Hai","Pelor","Vecna"],"grantedPower":"Suas magias de Adivinhação recebem +2 no nível de conjurador.","spells":[{"level":1,"name":"Identificação","description":"Determina uma habilidade de um item mágico."},{"level":2,"name":"Augúrio","description":"Descobre se uma ação será boa ou ruim."},{"level":3,"name":"Adivinhação","description":"Oferece conselhos úteis sobre as ações propostas."},{"level":4,"name":"Observação","description":"Espiona um alvo à distância."},{"level":5,"name":"Comunhão","description":"Divindade responde uma pergunta por nível (sim ou não)."},{"level":6,"name":"Lendas e Histórias","description":"Descubra histórias sobre uma pessoa, local ou objeto."},{"level":7,"name":"Observação Aprimorada","description":"Como observação, só que mais rápido e com duração maior."},{"level":8,"name":"Discernir Localização","description":"Descobre o local exato de uma criatura ou objeto."},{"level":9,"name":"Sexto Sentido","description":"\"Sexto sentido\" lhe avisa sobre um perigo iminente."}]}'::jsonb),
('dnd35.defensores.domain.defensores-dominio-comunidade','Comunidade','Comunidade','Você pode conjurar acalmar emoções uma vez por dia, como uma habilidade similar a magia, e ainda recebe +2 de bônus em qualquer teste de Diplomacia.','domain',1,null,ARRAY['Corellon Larethian','Garl Glittergold','Pelor','St. Cuthbert','Yondalla']::text[],'v35-defensores','D&D 3.5 — Defensores da Fé',77,'dnd35','{"id":"defensores-dominio-comunidade","name":"Comunidade","deities":["Corellon Larethian","Garl Glittergold","Pelor","St. Cuthbert","Yondalla"],"grantedPower":"Você pode conjurar acalmar emoções uma vez por dia, como uma habilidade similar a magia, e ainda recebe +2 de bônus em qualquer teste de Diplomacia.","spells":[{"level":1,"name":"Benção","description":"Os aliados recebem +1 para ataques e testes de resistência contra medo."},{"level":2,"name":"Proteger Outro","description":"Você sofre metade do dano dirigido ao alvo."},{"level":3,"name":"Oração","description":"Os aliados recebem +1 em várias jogadas e os inimigos sofrem -1."},{"level":4,"name":"Condição","description":"Monitora a condição e a posição dos aliados."},{"level":5,"name":"Ligação Telepática de Rary","description":"Ligação que permite aos aliados se comunicarem."},{"level":6,"name":"Banquete de Heróis","description":"Produz comida para 1 criatura/nível, cura e abençoa."},{"level":7,"name":"Refúgio","description":"Altera um item para que transporte seu usuário até você."},{"level":8,"name":"Cura Completa em Massa","description":"Como cura completa, mas para vários alvos."},{"level":9,"name":"Milagre","description":"Pede a intervenção de uma divindade."}]}'::jsonb),
('dnd35.defensores.domain.defensores-dominio-criacao','Criação','Criação','Suas magias de Conjuração [criação] recebem +2 no nível de conjurador.','domain',1,null,ARRAY['Corellon Larethian','Garl Glittergold','Moradin','Obad-Hai','Pelor','Vecna','Yondalla']::text[],'v35-defensores','D&D 3.5 — Defensores da Fé',77,'dnd35','{"id":"defensores-dominio-criacao","name":"Criação","deities":["Corellon Larethian","Garl Glittergold","Moradin","Obad-Hai","Pelor","Vecna","Yondalla"],"grantedPower":"Suas magias de Conjuração [criação] recebem +2 no nível de conjurador.","spells":[{"level":1,"name":"Criar Água","description":"Cria 8 litros/nível de água pura."},{"level":2,"name":"Imagem Menor","description":"Cria ilusões visuais e sonoras."},{"level":3,"name":"Criar Alimentos","description":"Alimenta três humanos (ou um cavalo)/nível."},{"level":4,"name":"Criar Itens Efêmeros","description":"Cria um objeto de tecido ou madeira."},{"level":5,"name":"Criar Itens Temporários","description":"Como criar itens efêmeros, mas também pedra e metal."},{"level":6,"name":"Banquete de Heróis","description":"Produz comida para 1 criatura/nível, cura e abençoa."},{"level":7,"name":"Imagem Permanente","description":"Inclui visão, som e cheiro."},{"level":8,"name":"Criar Itens Permanentes","description":"Como criar itens temporários, mas permanente.","novo":true},{"level":9,"name":"Gênese","description":"Cria um semi-plano limitado.","novo":true}]}'::jsonb),
('dnd35.defensores.domain.defensores-dominio-dominacao','Dominação','Dominação','Você recebe o talento Foco em Magia (Encantamento).','domain',1,null,ARRAY['Gruumsh','Hextor','St. Cuthbert','Wee Jas']::text[],'v35-defensores','D&D 3.5 — Defensores da Fé',77,'dnd35','{"id":"defensores-dominio-dominacao","name":"Dominação","deities":["Gruumsh","Hextor","St. Cuthbert","Wee Jas"],"grantedPower":"Você recebe o talento Foco em Magia (Encantamento).","spells":[{"level":1,"name":"Comando","description":"Um alvo obedece a uma palavra de comando durante 1 rodada."},{"level":2,"name":"Cativar","description":"Cativa todos num raio de 30 m + 3 m/nível."},{"level":3,"name":"Sugestão","description":"Força o alvo a seguir um curso de ação."},{"level":4,"name":"Dominar Pessoas","description":"Controla um humanóide telepaticamente."},{"level":5,"name":"Comando Aprimorado","description":"Como comando, mas afeta um alvo/nível."},{"level":6,"name":"Tarefa/Missão","description":"Como missão menor, mas afeta qualquer criatura."},{"level":7,"name":"Sugestionar Multidões","description":"Como sugestão, mas um alvo/nível."},{"level":8,"name":"Dominação Verdadeira","description":"Como dominar pessoas, mas aplica -4 de penalidade no teste.","novo":true},{"level":9,"name":"Escravo Monstruoso","description":"Como dominar pessoas, mas com efeito permanente e afeta qualquer criatura.","novo":true}]}'::jsonb),
('dnd35.defensores.domain.defensores-dominio-exorcismo','Exorcismo','Exorcismo','Você adquire a habilidade sobrenatural de expulsar espíritos de corpos possuídos. O jogador realiza um teste de Carisma (1d20 + modificador de Carisma) e consulta a tabela 8-16, pág. 140 do Livro do Jogador, mas soma seu nível na classe de prestígio, seu nível de clérigo (se houver), mais seu nível de paladino -2 (se houver). Se o resultado obtido na tabela igualar ou superar os DVs da criatura invasora, ela será obrigada a abandonar o corpo. Caso o espírito pertença a um mago usando recipiente arcano, ele voltará ao recipiente. Caso seja um fantasma, a criatura se tornará etérea e flutuará. Em qualquer caso, a mesma vítima não poderá ser possuída pelo espírito durante um dia inteiro.','domain',1,null,ARRAY['Corellon Larethian','Heironeous','Kord','Moradin','Pelor']::text[],'v35-defensores','D&D 3.5 — Defensores da Fé',77,'dnd35','{"id":"defensores-dominio-exorcismo","name":"Exorcismo","deities":["Corellon Larethian","Heironeous","Kord","Moradin","Pelor"],"grantedPower":"Você adquire a habilidade sobrenatural de expulsar espíritos de corpos possuídos. O jogador realiza um teste de Carisma (1d20 + modificador de Carisma) e consulta a tabela 8-16, pág. 140 do Livro do Jogador, mas soma seu nível na classe de prestígio, seu nível de clérigo (se houver), mais seu nível de paladino -2 (se houver). Se o resultado obtido na tabela igualar ou superar os DVs da criatura invasora, ela será obrigada a abandonar o corpo. Caso o espírito pertença a um mago usando recipiente arcano, ele voltará ao recipiente. Caso seja um fantasma, a criatura se tornará etérea e flutuará. Em qualquer caso, a mesma vítima não poderá ser possuída pelo espírito durante um dia inteiro.","spells":[{"level":1,"name":"Proteção Contra o Mal","description":"+2 na CA e testes de resistência, impede controle mental, isola elementais e seres extra-planares."},{"level":2,"name":"Círculo Mágico Contra o Mal","description":"Como proteção contra o mal, mas com 3 m de raio e 10 min/nível."},{"level":3,"name":"Remover Maldição","description":"Liberta objeto ou pessoa de qualquer maldição."},{"level":4,"name":"Expulsão","description":"Força uma criatura a retornar para seu plano nativo."},{"level":5,"name":"Dissipar o Mal","description":"+4 de bônus contra ataques de criaturas malignas."},{"level":6,"name":"Banimento","description":"Expulsa 2 DV/nível de criaturas extra-planares."},{"level":7,"name":"Palavra Sagrada","description":"Mata, paralisa, cega ou ensurdece alvos neutros ou maus."},{"level":8,"name":"Aura Sagrada","description":"+4 na CA, +4 de testes de resistência e RM 25 contra magias malignas."},{"level":9,"name":"Desatar","description":"Destrói magias de aprisionamento num raio de 60 m.","novo":true}]}'::jsonb),
('dnd35.defensores.domain.defensores-dominio-gloria','Glória','Glória','+2 de bônus nos testes para Expulsar mortos-vivos e +1d6 no teste para calcular o dano de expulsão.','domain',1,null,ARRAY['Heironeous','Pelor']::text[],'v35-defensores','D&D 3.5 — Defensores da Fé',77,'dnd35','{"id":"defensores-dominio-gloria","name":"Glória","deities":["Heironeous","Pelor"],"grantedPower":"+2 de bônus nos testes para Expulsar mortos-vivos e +1d6 no teste para calcular o dano de expulsão.","spells":[{"level":1,"name":"Romper Mortos-vivos","description":"Causa 1d6 pontos de dano a um morto-vivo."},{"level":2,"name":"Arma Mágica","description":"Uma arma recebe +1 de bônus."},{"level":3,"name":"Luz Cegante","description":"Um raio causa 1d8 de dano/2 níveis, ou mais contra mortos-vivos."},{"level":4,"name":"Destruição Sagrada","description":"Causa dano e cega criaturas malignas."},{"level":5,"name":"Espada Sagrada","description":"Arma se torna +5 e causa dano dobrado contra seres malignos."},{"level":6,"name":"Raio de Glória","description":"Um raio causa dano de energia positiva, em especial contra criaturas malignas e mortos-vivos.","novo":true},{"level":7,"name":"Raio de Sol","description":"Luz cega e causa 3d6 pontos de dano."},{"level":8,"name":"Coroa da Glória","description":"O alvo recebe +4 Car e cativa os alvos.","novo":true},{"level":9,"name":"Portal","description":"Conecta dois planos para viagens ou invocação."}]}'::jsonb),
('dnd35.defensores.domain.defensores-dominio-inquisicao','Inquisição','Inquisição','+4 de bônus em qualquer teste de dissipar.','domain',1,null,ARRAY['Heironeous','Moradin','St. Cuthbert']::text[],'v35-defensores','D&D 3.5 — Defensores da Fé',77,'dnd35','{"id":"defensores-dominio-inquisicao","name":"Inquisição","deities":["Heironeous","Moradin","St. Cuthbert"],"grantedPower":"+4 de bônus em qualquer teste de dissipar.","spells":[{"level":1,"name":"Detectar o Mal","description":"Revela criaturas, magias ou objetos malignos."},{"level":2,"name":"Zona da Verdade","description":"Os alvos na área não podem mentir."},{"level":3,"name":"Detectar Pensamentos","description":"Permite captar pensamentos superficiais."},{"level":4,"name":"Discernir Mentiras","description":"Revela mentiras deliberadas."},{"level":5,"name":"Visão da Verdade","description":"Mostra todas as coisas em sua forma verdadeira."},{"level":6,"name":"Proibição","description":"Impede que criaturas de outra tendência entrem na área."},{"level":7,"name":"Ditado","description":"Mata, paralisa, deixa lento ou ensurdece alvos neutros ou caóticos."},{"level":8,"name":"Aura Sagrada","description":"+4 na CA, +4 de testes de resistência e RM 25 contra magias malignas."},{"level":9,"name":"Aprisionar a Alma","description":"Aprisiona o alvo dentro de uma gema."}]}'::jsonb),
('dnd35.defensores.domain.defensores-dominio-insanidade','Insanidade','Insanidade','Você adquire um "valor de Insanidade" equivalente a metade do seu nível de classe (some os níveis de clérigo ao nível na classe de prestígio). Para conjurar magias, determinar suas magias adicionais e CD de resistência, adicione esse valor à sua Sabedoria e utilize o resultado como Sabedoria efetiva. Para todos os demais propósitos, como testes de perícias e testes de resistência, subtraia esse valor da sua Sabedoria e use o resultado como Sabedoria efetiva. Isso significa que é muito difícil resistir às suas magias, mas em geral você não prestará nenhuma atenção ao seu ambiente e agirá com imprudência — ou mesmo com imprevisibilidade. Uma vez por dia, você poderá enxergar e agir com a clareza da insanidade genuína. Utilize seu valor de insanidade como um bônus numa única jogada que envolva Sabedoria, como um teste de Ouvir ou um teste de resistência de Vontade. É necessário declarar o uso do poder antes da jogada.','domain',1,null,ARRAY['Boccob','Erythnul','Vecna']::text[],'v35-defensores','D&D 3.5 — Defensores da Fé',77,'dnd35','{"id":"defensores-dominio-insanidade","name":"Insanidade","deities":["Boccob","Erythnul","Vecna"],"grantedPower":"Você adquire um \"valor de Insanidade\" equivalente a metade do seu nível de classe (some os níveis de clérigo ao nível na classe de prestígio). Para conjurar magias, determinar suas magias adicionais e CD de resistência, adicione esse valor à sua Sabedoria e utilize o resultado como Sabedoria efetiva. Para todos os demais propósitos, como testes de perícias e testes de resistência, subtraia esse valor da sua Sabedoria e use o resultado como Sabedoria efetiva. Isso significa que é muito difícil resistir às suas magias, mas em geral você não prestará nenhuma atenção ao seu ambiente e agirá com imprudência — ou mesmo com imprevisibilidade. Uma vez por dia, você poderá enxergar e agir com a clareza da insanidade genuína. Utilize seu valor de insanidade como um bônus numa única jogada que envolva Sabedoria, como um teste de Ouvir ou um teste de resistência de Vontade. É necessário declarar o uso do poder antes da jogada.","spells":[{"level":1,"name":"Ação Aleatória","description":"Uma criatura age aleatoriamente durante uma rodada."},{"level":2,"name":"Toque da Loucura","description":"Uma criatura fica pasma durante uma rodada/nível.","novo":true},{"level":3,"name":"Fúria","description":"+4 For, +4 Cons, +2 de bônus de moral em testes de resistência de Vontade.","novo":true},{"level":4,"name":"Confusão","description":"Obriga o alvo a agir de modo estranho durante uma rodada/nível."},{"level":5,"name":"Raios de Malevolência","description":"Um raio/rodada pasma durante 1d3 rodadas.","novo":true},{"level":6,"name":"Assassino Fantasmagórico","description":"Ilusão temerária mata o alvo ou causa 3d6 pontos de dano."},{"level":7,"name":"Insanidade","description":"O alvo sofre confusão contínua."},{"level":8,"name":"Grito Enlouquecedor","description":"Alvo sofre -4 na CA, não pode usar escudos e seus testes de Reflexo exigem um resultado 20.","novo":true},{"level":9,"name":"Encarnação Fantasmagórica","description":"Como assassino fantasmagórico, mas afeta todos num raio de 9 m."}]}'::jsonb),
('dnd35.defensores.domain.defensores-dominio-invocacao','Invocação','Invocação','Suas magias invocar criaturas consideram o dobro do seu nível de conjurador para determinar o alcance e a duração (mas não a quantidade de criaturas).','domain',1,null,ARRAY['Todos']::text[],'v35-defensores','D&D 3.5 — Defensores da Fé',77,'dnd35','{"id":"defensores-dominio-invocacao","name":"Invocação","deities":["Todos"],"grantedPower":"Suas magias invocar criaturas consideram o dobro do seu nível de conjurador para determinar o alcance e a duração (mas não a quantidade de criaturas).","spells":[{"level":1,"name":"Invocar Criaturas I","description":"Invoca um extra-planar para auxiliar o conjurador."},{"level":2,"name":"Invocar Criaturas II","description":"Invoca um extra-planar para auxiliar o conjurador."},{"level":3,"name":"Invocar Criaturas III","description":"Invoca um extra-planar para auxiliar o conjurador."},{"level":4,"name":"Aliado Extra-planar Menor","description":"Negocia serviços com um ser extra-planar de 8 DV."},{"level":5,"name":"Invocar Criaturas V","description":"Invoca um extra-planar para auxiliar o conjurador."},{"level":6,"name":"Aliado Extra-planar","description":"Como aliado extra-planar menor, mas com até 16 DV."},{"level":7,"name":"Invocar Criaturas VII","description":"Invoca um extra-planar para auxiliar o conjurador."},{"level":8,"name":"Aliado Extra-planar Aprimorado","description":"Como aliado extra-planar menor, mas com até 24 DV."},{"level":9,"name":"Portal","description":"Conecta dois planos para viagens ou invocação."}]}'::jsonb),
('dnd35.defensores.domain.defensores-dominio-mente','Mente','Mente','+2 de bônus em testes de Blefar, Diplomacia, Mensagens Secretas, Leitura Labial e Sentir Motivação. +2 de bônus em testes de Vontade contra magias e efeitos de encantamento.','domain',1,null,ARRAY['Boccob','Vecna','Wee Jas']::text[],'v35-defensores','D&D 3.5 — Defensores da Fé',77,'dnd35','{"id":"defensores-dominio-mente","name":"Mente","deities":["Boccob","Vecna","Wee Jas"],"grantedPower":"+2 de bônus em testes de Blefar, Diplomacia, Mensagens Secretas, Leitura Labial e Sentir Motivação. +2 de bônus em testes de Vontade contra magias e efeitos de encantamento.","spells":[{"level":1,"name":"Compreensão de Linguagens","description":"Entenda todos os idiomas falados e escritos."},{"level":2,"name":"Detectar Pensamentos","description":"Permite captar pensamentos superficiais."},{"level":3,"name":"Laço Telepático Menor","description":"Ligação telepática com um alvo num raio de 9 m, durante 10 min/nível.","novo":true},{"level":4,"name":"Discernir Mentiras","description":"Revela mentiras deliberadas."},{"level":5,"name":"Ligação Telepática de Rary","description":"Ligação que permite aos aliados se comunicarem."},{"level":6,"name":"Examinar Pensamentos","description":"Revela as memórias do alvo, uma pergunta/rodada.","novo":true},{"level":7,"name":"Aracnídeo Mental","description":"Vasculha os pensamentos de até oito criaturas.","novo":true},{"level":8,"name":"Limpar a Mente","description":"O alvo se torna imune a magias mentais/emocionais e observação."},{"level":9,"name":"Encarnação Fantasmagórica","description":"Como assassino fantasmagórico, mas afeta todos num raio de 9 m."}]}'::jsonb),
('dnd35.defensores.domain.defensores-dominio-mestre-das-feras','Mestre das Feras','Mestre das Feras','Você pode lançar falar com animais uma vez por nível a cada dia, com efeitos idênticos à magia. Esta é uma habilidade sobrenatural.','domain',1,null,ARRAY['Ehlonna','Obad-Hai']::text[],'v35-defensores','D&D 3.5 — Defensores da Fé',77,'dnd35','{"id":"defensores-dominio-mestre-das-feras","name":"Mestre das Feras","deities":["Ehlonna","Obad-Hai"],"grantedPower":"Você pode lançar falar com animais uma vez por nível a cada dia, com efeitos idênticos à magia. Esta é uma habilidade sobrenatural.","spells":[{"level":1,"name":"Cativar Animais","description":"Adquire companheiros animais permanentes."},{"level":2,"name":"Máscara Bestial","description":"Os animais e as bestas consideram o conjurador um semelhante.","novo":true},{"level":3,"name":"Transe Animal","description":"Fascina 2d6 DV de animais."},{"level":4,"name":"Coração de Urso","description":"Um aliado/nível recebe +4 de Força e +1d4/nível pontos de vida.","novo":true},{"level":5,"name":"Ampliar Animais","description":"Um animal/dois níveis dobra de tamanho e DV."},{"level":6,"name":"Invocar Aliado da Natureza III","description":"Invoca animais para auxiliar o conjurador."},{"level":7,"name":"Forma Animal","description":"Um aliado/nível sofre metamorfose para o animal escolhido."},{"level":8,"name":"Invocar Aliado da Natureza IV","description":"Invoca animais para auxiliar o conjurador."},{"level":9,"name":"Alterar Forma","description":"Transforma você em qualquer criatura; pode mudar de forma uma vez por rodada."}]}'::jsonb),
('dnd35.defensores.domain.defensores-dominio-misticismo','Misticismo','Misticismo','Você aplica o seu modificador de Carisma (caso seja positivo) como bônus em todos os testes de resistência. Caso já tenha essa habilidade (paladinos, por exemplo), você adiciona +1 de bônus.','domain',1,null,ARRAY['Qualquer deus Bom ou Mau']::text[],'v35-defensores','D&D 3.5 — Defensores da Fé',77,'dnd35','{"id":"defensores-dominio-misticismo","name":"Misticismo","deities":["Qualquer deus Bom ou Mau"],"grantedPower":"Você aplica o seu modificador de Carisma (caso seja positivo) como bônus em todos os testes de resistência. Caso já tenha essa habilidade (paladinos, por exemplo), você adiciona +1 de bônus.","spells":[{"level":1,"name":"Auxílio Divino","description":"Você recebe +1 de bônus/três níveis para ataques e dano."},{"level":2,"name":"Arma Espiritual","description":"Arma mágica ataca sozinha."},{"level":3,"name":"Aspecto da Divindade Menor","description":"O personagem se torna mais parecido com a forma de seu deus.","novo":true},{"level":4,"name":"Arma da Divindade","description":"+1 no ataque e dano com a arma do deus, além de uma habilidade especial.","novo":true},{"level":5,"name":"Força dos Justos","description":"Seu tamanho aumenta e você recebe +4 de Força."},{"level":6,"name":"Aspecto da Divindade","description":"Como aspecto menor, mas você adquire qualidades celestiais ou abissais.","novo":true},{"level":7,"name":"Blasfêmia/Palavra Sagrada","description":"Mata, paralisa, enfraquece, ensurdece ou confunde criaturas boas/malignas."},{"level":8,"name":"Aura Sagrada/Aura Profana","description":"+4 na CA, +4 de testes de resistência e RM 25 contra magias malignas/bondosas."},{"level":9,"name":"Aspecto da Divindade Maior","description":"Como aspecto menor, mas adquire asas, valores de habilidade aprimorados, diversas resistências e imunidades.","novo":true}]}'::jsonb),
('dnd35.defensores.domain.defensores-dominio-pestilencia','Pestilência','Pestilência','Imunidade aos efeitos de quaisquer doenças, embora os clérigos que tenham esse poder ainda possam transmitir doenças contagiosas.','domain',1,null,ARRAY['Erythnul','Hextor','Nerull','Wee Jas']::text[],'v35-defensores','D&D 3.5 — Defensores da Fé',77,'dnd35','{"id":"defensores-dominio-pestilencia","name":"Pestilência","deities":["Erythnul","Hextor","Nerull","Wee Jas"],"grantedPower":"Imunidade aos efeitos de quaisquer doenças, embora os clérigos que tenham esse poder ainda possam transmitir doenças contagiosas.","spells":[{"level":1,"name":"Desespero","description":"Um alvo sofre -2 para ataques, dano, testes de resistência e testes."},{"level":2,"name":"Invocar Criaturas II","description":"Invoca 1d3 ratos atrozes abissais para auxiliar o conjurador."},{"level":3,"name":"Praga","description":"Infecta um alvo com a doença escolhida."},{"level":4,"name":"Envenenamento","description":"Toque causa 1d10 pontos de dano de Cons, que se repete após 1 min."},{"level":5,"name":"Praga dos Ratos","description":"Convoca uma horda de ratos pestilentos.","novo":true},{"level":6,"name":"Maldição da Licantropia","description":"Causa licantropia temporária ao alvo.","novo":true},{"level":7,"name":"Flagelo","description":"Inflige uma doença que só pode ser curada magicamente, um alvo/nível.","novo":true},{"level":8,"name":"Criar Mortos-vivos Aprimorados","description":"Transforma um cadáver em múmia."},{"level":9,"name":"Bando de Otyughs","description":"Cria 3d4 otyughs ou 1d3+1 otyughs Enormes.","novo":true}]}'::jsonb),
('dnd35.defensores.domain.defensores-dominio-velocidade','Velocidade','Velocidade','+2 de bônus de aprimoramento na Destreza, +2 de bônus de aprimoramento na Iniciativa, +3 m de deslocamento, mas apenas se utilizar armaduras leves. Essas são habilidades sobrenaturais.','domain',1,null,ARRAY['Fharlanghn','Olidammara']::text[],'v35-defensores','D&D 3.5 — Defensores da Fé',77,'dnd35','{"id":"defensores-dominio-velocidade","name":"Velocidade","deities":["Fharlanghn","Olidammara"],"grantedPower":"+2 de bônus de aprimoramento na Destreza, +2 de bônus de aprimoramento na Iniciativa, +3 m de deslocamento, mas apenas se utilizar armaduras leves. Essas são habilidades sobrenaturais.","spells":[{"level":1,"name":"Nublar","description":"Os ataques têm 20% de chance de falhar."},{"level":2,"name":"Agilidade Felina","description":"O alvo recebe 1d4+1 Des durante 1 hora/nível."},{"level":3,"name":"Andar no Ar","description":"O alvo caminha no ar como se fosse sólido (sobe num ângulo de 45°)."},{"level":4,"name":"Velocidade","description":"Ação parcial adicional e +4 na CA."},{"level":5,"name":"Caminhar em Árvores","description":"Passe através de uma árvore para outra."},{"level":6,"name":"Caminhar no Vento","description":"Você e seus aliados se transformam em vapores e viajam rápido."},{"level":7,"name":"Velocidade em Massa","description":"Como velocidade, mas afeta 1 alvo/nível."},{"level":8,"name":"Piscar","description":"Você desaparece e reaparece aleatoriamente durante 1 rodada/nível."},{"level":9,"name":"Parar o Tempo","description":"Você age livremente durante 1d4+1 rodadas."}]}'::jsonb)
insert into public.catalog_feats (id,feat_type,level,name_pt,name_en,description_pt,prerequisites,traits,ruleset,source_book,source_page,system_id,data) values
('dnd35.defensores.feat.defensores-acelerar-expulsao','Especial',1,'Acelerar Expulsão','Acelerar Expulsão','O personagem consegue Expulsar ou Fascinar Mortos-vivos como uma ação livre, mas sofrerá -4 de penalidade nas jogadas de Expulsão e dano de Expulsão. É possível realizar apenas uma tentativa de Expulsão por rodada. Esse talento somente pode ser ativado para efetivamente Expulsar ou Fascinar Mortos-vivos; ele não funciona para ativar talentos divinos.','Expulsar/Fascinar Mortos-vivos, Carisma 13+, Expulsão Adicional',ARRAY['especial']::text[],'v35-defensores','D&D 3.5 — Defensores da Fé',19,'dnd35','{"id":"defensores-acelerar-expulsao","name":"Acelerar Expulsão","type":"Especial","summary":"Você consegue Expulsar ou Fascinar Mortos-vivos muito rapidamente e de modo reflexo.","prerequisites":["Expulsar/Fascinar Mortos-vivos","Carisma 13+","Expulsão Adicional"],"tablePrerequisites":["Clérigo ou paladino","Carisma 13+","Expulsão Adicional"],"benefit":"O personagem consegue Expulsar ou Fascinar Mortos-vivos como uma ação livre, mas sofrerá -4 de penalidade nas jogadas de Expulsão e dano de Expulsão. É possível realizar apenas uma tentativa de Expulsão por rodada. Esse talento somente pode ser ativado para efetivamente Expulsar ou Fascinar Mortos-vivos; ele não funciona para ativar talentos divinos."}'::jsonb),
('dnd35.defensores.feat.defensores-ataque-com-escudo-aprimorado','Geral',1,'Ataque com Escudo Aprimorado','Ataque com Escudo Aprimorado','Sempre que o personagem atingir um oponente usando um escudo (pequeno ou grande), ele afetará o alvo como se tivesse realizado a manobra Encontrão. O personagem não invade realmente a área ocupada pelo adversário e não provoca ataques de oportunidade; além disso, não consegue deslocar a vítima mais de 1,5 m para trás, nem se mover com o defensor. É impossível usar esse talento com um broquel.','Ataque Poderoso',ARRAY['geral']::text[],'v35-defensores','D&D 3.5 — Defensores da Fé',19,'dnd35','{"id":"defensores-ataque-com-escudo-aprimorado","name":"Ataque com Escudo Aprimorado","type":"Geral","summary":"Você é capaz de empurrar seus oponentes com golpes de seu escudo.","prerequisites":["Ataque Poderoso"],"tablePrerequisites":["Força 13+","Ataque Poderoso"],"benefit":"Sempre que o personagem atingir um oponente usando um escudo (pequeno ou grande), ele afetará o alvo como se tivesse realizado a manobra Encontrão. O personagem não invade realmente a área ocupada pelo adversário e não provoca ataques de oportunidade; além disso, não consegue deslocar a vítima mais de 1,5 m para trás, nem se mover com o defensor. É impossível usar esse talento com um broquel."}'::jsonb),
('dnd35.defensores.feat.defensores-destruicao-adicional','Especial',1,'Destruição Adicional','Destruição Adicional','Quando o personagem seleciona esse talento, ele adquire uma utilização adicional de ''destruir o mal'' por dia. Essa tentativa extra aplica-se a qualquer habilidade de ''destruir o mal'' (de paladinos, libertadores sagrados ou clérigos com acesso ao domínio Destruição). É possível escolher esse talento diversas vezes.','4º nível ou superior, Destruir o Mal',ARRAY['especial']::text[],'v35-defensores','D&D 3.5 — Defensores da Fé',19,'dnd35','{"id":"defensores-destruicao-adicional","name":"Destruição Adicional","type":"Especial","summary":"Você consegue desferir mais ataques para destruir o mal.","prerequisites":["4º nível ou superior","Destruir o Mal"],"tablePrerequisites":["4º nível ou maior de uma classe de personagem"],"benefit":"Quando o personagem seleciona esse talento, ele adquire uma utilização adicional de ''destruir o mal'' por dia. Essa tentativa extra aplica-se a qualquer habilidade de ''destruir o mal'' (de paladinos, libertadores sagrados ou clérigos com acesso ao domínio Destruição). É possível escolher esse talento diversas vezes."}'::jsonb),
('dnd35.defensores.feat.defensores-elevar-expulsao','Especial',1,'Elevar Expulsão','Elevar Expulsão','O personagem poderá escolher um valor igual ou inferior ao seu nível de clérigo e adicionar esse valor como bônus no seu teste de Expulsão. O mesmo valor será aplicado como penalidade na jogada de dano de Expulsão. Caso não seja um clérigo, esse valor será limitado por seu nível efetivo nessa classe (por exemplo, um paladino tem um nível efetivo de clérigo igual ao seu nível -2). Quando uma classe de prestígio aumentar seu nível de expulsão efetivo, considere o novo valor.','Expulsar/Fascinar Mortos-vivos, Carisma 13+, Expulsão Adicional',ARRAY['especial']::text[],'v35-defensores','D&D 3.5 — Defensores da Fé',19,'dnd35','{"id":"defensores-elevar-expulsao","name":"Elevar Expulsão","type":"Especial","summary":"Você consegue Expulsar ou Fascinar Mortos-vivos mais poderosos que o normal.","prerequisites":["Expulsar/Fascinar Mortos-vivos","Carisma 13+","Expulsão Adicional"],"tablePrerequisites":["Clérigo ou paladino","Carisma 13+","Expulsão Adicional"],"benefit":"O personagem poderá escolher um valor igual ou inferior ao seu nível de clérigo e adicionar esse valor como bônus no seu teste de Expulsão. O mesmo valor será aplicado como penalidade na jogada de dano de Expulsão. Caso não seja um clérigo, esse valor será limitado por seu nível efetivo nessa classe (por exemplo, um paladino tem um nível efetivo de clérigo igual ao seu nível -2). Quando uma classe de prestígio aumentar seu nível de expulsão efetivo, considere o novo valor."}'::jsonb),
('dnd35.defensores.feat.defensores-escudo-divino','Divino',1,'Escudo Divino','Escudo Divino','O personagem imbui seu escudo de energia, concedendo-lhe um bônus de melhoria equivalente a seu modificador de Carisma. Esse bônus se aplica na CA do usuário e nas suas jogadas de ataque com o escudo; ele dura uma quantidade de rodadas equivalente ao modificador de Carisma do personagem. A ativação usa uma ação padrão e uma tentativa de Expulsão.','Expulsar/Fascinar Mortos-vivos, Carisma 13+, Força 13+, Ataque Poderoso, Ataque com Escudo Aprimorado',ARRAY['divino']::text[],'v35-defensores','D&D 3.5 — Defensores da Fé',19,'dnd35','{"id":"defensores-escudo-divino","name":"Escudo Divino","type":"Divino","summary":"Você é capaz de canalizar a energia sagrada para tornar seu escudo mais eficiente — na defesa e no ataque.","prerequisites":["Expulsar/Fascinar Mortos-vivos","Carisma 13+","Força 13+","Ataque Poderoso","Ataque com Escudo Aprimorado"],"benefit":"O personagem imbui seu escudo de energia, concedendo-lhe um bônus de melhoria equivalente a seu modificador de Carisma. Esse bônus se aplica na CA do usuário e nas suas jogadas de ataque com o escudo; ele dura uma quantidade de rodadas equivalente ao modificador de Carisma do personagem. A ativação usa uma ação padrão e uma tentativa de Expulsão."}'::jsonb),
('dnd35.defensores.feat.defensores-forca-divina','Divino',1,'Força Divina','Força Divina','O personagem adiciona seu bônus de Carisma a todas as suas jogadas de dano com armas, durante uma quantidade de rodadas equivalente ao seu modificador de Carisma. A ativação usa uma ação padrão e uma tentativa de Expulsão.','Expulsar/Fascinar Mortos-vivos, Carisma 13+, Força 13+, Ataque Poderoso',ARRAY['divino']::text[],'v35-defensores','D&D 3.5 — Defensores da Fé',19,'dnd35','{"id":"defensores-forca-divina","name":"Força Divina","type":"Divino","summary":"Você é capaz de canalizar a energia sagrada para aumentar o dano que causa em batalha.","prerequisites":["Expulsar/Fascinar Mortos-vivos","Carisma 13+","Força 13+","Ataque Poderoso"],"benefit":"O personagem adiciona seu bônus de Carisma a todas as suas jogadas de dano com armas, durante uma quantidade de rodadas equivalente ao seu modificador de Carisma. A ativação usa uma ação padrão e uma tentativa de Expulsão."}'::jsonb),
('dnd35.defensores.feat.defensores-investida-com-escudo','Geral',1,'Investida com Escudo','Investida com Escudo','Quando o personagem executar a manobra Investida e utilizar seu escudo como arma, ele causará o dobro do dano normal.','Ataque Poderoso, Ataque com Escudo Aprimorado',ARRAY['geral']::text[],'v35-defensores','D&D 3.5 — Defensores da Fé',19,'dnd35','{"id":"defensores-investida-com-escudo","name":"Investida com Escudo","type":"Geral","summary":"Você causará dano adicional se utilizar um escudo como arma durante uma Investida.","prerequisites":["Ataque Poderoso","Ataque com Escudo Aprimorado"],"tablePrerequisites":["Força 13+","Ataque Poderoso","Ataque com Escudo Aprimorado"],"benefit":"Quando o personagem executar a manobra Investida e utilizar seu escudo como arma, ele causará o dobro do dano normal."}'::jsonb),
('dnd35.defensores.feat.defensores-magia-de-alcance','Metamágico',1,'Magia de Alcance','Magia de Alcance','O personagem pode lançar uma magia que tenha alcance "Toque" a até 9 metros de distância. Efetivamente, a magia se torna um raio; o conjurador precisará realizar um teste de ataque de toque à distância para afetar o alvo desejado. Uma magia de alcance alterado ocupa o espaço de uma magia dois níveis superiores ao padrão.',null,ARRAY['metamágico']::text[],'v35-defensores','D&D 3.5 — Defensores da Fé',19,'dnd35','{"id":"defensores-magia-de-alcance","name":"Magia de Alcance","type":"Metamágico","summary":"Você é capaz de conjurar magias de toque sem encostar no alvo.","prerequisites":[],"benefit":"O personagem pode lançar uma magia que tenha alcance \"Toque\" a até 9 metros de distância. Efetivamente, a magia se torna um raio; o conjurador precisará realizar um teste de ataque de toque à distância para afetar o alvo desejado. Uma magia de alcance alterado ocupa o espaço de uma magia dois níveis superiores ao padrão."}'::jsonb),
('dnd35.defensores.feat.defensores-magia-sagrada','Metamágico',1,'Magia Sagrada','Magia Sagrada','Metade do dano causado por qualquer magia sagrada é alimentada diretamente pelas entidades divinas, portanto não será afetada por efeitos como suportar elementos ou magias similares. A outra metade do dano da magia deve ser tratada normalmente. Uma magia sagrada ocupa o espaço de uma magia dois níveis superiores ao padrão. Somente conjuradores divinos podem selecionar esse talento.',null,ARRAY['metamágico']::text[],'v35-defensores','D&D 3.5 — Defensores da Fé',19,'dnd35','{"id":"defensores-magia-sagrada","name":"Magia Sagrada","type":"Metamágico","summary":"Suas magias de dano são carregadas de poderes divinos.","prerequisites":[],"benefit":"Metade do dano causado por qualquer magia sagrada é alimentada diretamente pelas entidades divinas, portanto não será afetada por efeitos como suportar elementos ou magias similares. A outra metade do dano da magia deve ser tratada normalmente. Uma magia sagrada ocupa o espaço de uma magia dois níveis superiores ao padrão. Somente conjuradores divinos podem selecionar esse talento."}'::jsonb),
('dnd35.defensores.feat.defensores-potencializar-expulsao','Especial',1,'Potencializar Expulsão','Potencializar Expulsão','O personagem consegue afetar mais mortos-vivos que o normal, mas tem dificuldade para influenciar as criaturas que tenham muitos Dados de Vida. Ele pode aceitar -2 de penalidade em seu teste de Expulsão para adicionar 2d6 na jogada de dano de Expulsão.','Expulsar/Fascinar Mortos-vivos, Carisma 13+, Expulsão Adicional',ARRAY['especial']::text[],'v35-defensores','D&D 3.5 — Defensores da Fé',19,'dnd35','{"id":"defensores-potencializar-expulsao","name":"Potencializar Expulsão","type":"Especial","summary":"Você consegue expulsar ou fascinar mais mortos-vivos na mesma tentativa.","prerequisites":["Expulsar/Fascinar Mortos-vivos","Carisma 13+","Expulsão Adicional"],"tablePrerequisites":["Clérigo ou paladino","Carisma 13+","Expulsão Adicional"],"benefit":"O personagem consegue afetar mais mortos-vivos que o normal, mas tem dificuldade para influenciar as criaturas que tenham muitos Dados de Vida. Ele pode aceitar -2 de penalidade em seu teste de Expulsão para adicionar 2d6 na jogada de dano de Expulsão."}'::jsonb),
('dnd35.defensores.feat.defensores-purificacao-divina','Divino',1,'Purificação Divina','Purificação Divina','O personagem e todos os seus aliados, numa dispersão de 18 m, recebem +2 de bônus sagrado nos testes de resistência de Fortitude durante uma quantidade de rodadas equivalente ao modificador de Carisma do usuário do talento. A ativação usa uma ação padrão e uma tentativa de Expulsão.','Expulsar/Fascinar Mortos-vivos, Carisma 13+, Expulsão Adicional',ARRAY['divino']::text[],'v35-defensores','D&D 3.5 — Defensores da Fé',19,'dnd35','{"id":"defensores-purificacao-divina","name":"Purificação Divina","type":"Divino","summary":"Você é capaz de canalizar a energia sagrada para aumentar a sua resistência — e de seus aliados — contra venenos e maldições.","prerequisites":["Expulsar/Fascinar Mortos-vivos","Carisma 13+","Expulsão Adicional"],"benefit":"O personagem e todos os seus aliados, numa dispersão de 18 m, recebem +2 de bônus sagrado nos testes de resistência de Fortitude durante uma quantidade de rodadas equivalente ao modificador de Carisma do usuário do talento. A ativação usa uma ação padrão e uma tentativa de Expulsão."}'::jsonb),
('dnd35.defensores.feat.defensores-resistencia-divina','Divino',1,'Resistência Divina','Resistência Divina','O personagem e todos os seus aliados, numa dispersão de 18 m, adquirem resistência contra fogo, frio e eletricidade 5. Essa proteção não se acumula com poderes similares, como os fornecidos por magias ou habilidades especiais. A resistência permanece ativa até o final do próximo turno do usuário. A ativação usa uma ação padrão e uma tentativa de Expulsão.','Expulsar/Fascinar Mortos-vivos, Expulsão Adicional, Purificação Divina',ARRAY['divino']::text[],'v35-defensores','D&D 3.5 — Defensores da Fé',19,'dnd35','{"id":"defensores-resistencia-divina","name":"Resistência Divina","type":"Divino","summary":"Você é capaz de canalizar a energia sagrada para reduzir temporariamente o dano causado por algumas fontes contra você e seus aliados.","prerequisites":["Expulsar/Fascinar Mortos-vivos","Expulsão Adicional","Purificação Divina"],"benefit":"O personagem e todos os seus aliados, numa dispersão de 18 m, adquirem resistência contra fogo, frio e eletricidade 5. Essa proteção não se acumula com poderes similares, como os fornecidos por magias ou habilidades especiais. A resistência permanece ativa até o final do próximo turno do usuário. A ativação usa uma ação padrão e uma tentativa de Expulsão."}'::jsonb),
('dnd35.defensores.feat.defensores-tolerancia-divina','Divino',1,'Tolerância Divina','Tolerância Divina','O personagem aumenta seu deslocamento básico em 3 metros e recebe +2 de bônus de aprimoramento no valor de Constituição. Esses efeitos duram uma quantidade de minutos equivalente ao modificador de Carisma do personagem. A ativação usa uma ação padrão e uma tentativa de Expulsão.','Expulsar/Fascinar Mortos-vivos, Carisma 13+, Expulsão Adicional',ARRAY['divino']::text[],'v35-defensores','D&D 3.5 — Defensores da Fé',19,'dnd35','{"id":"defensores-tolerancia-divina","name":"Tolerância Divina","type":"Divino","summary":"Você é capaz de canalizar a energia sagrada para aumentar seu deslocamento e sua Constituição.","prerequisites":["Expulsar/Fascinar Mortos-vivos","Carisma 13+","Expulsão Adicional"],"benefit":"O personagem aumenta seu deslocamento básico em 3 metros e recebe +2 de bônus de aprimoramento no valor de Constituição. Esses efeitos duram uma quantidade de minutos equivalente ao modificador de Carisma do personagem. A ativação usa uma ação padrão e uma tentativa de Expulsão."}'::jsonb),
('dnd35.defensores.feat.defensores-vinganca-divina','Divino',1,'Vingança Divina','Vingança Divina','O personagem adiciona 2d6 pontos de dano sagrado a todos os ataques bem-sucedidos contra mortos-vivos, usando armas brancas, até o final de sua próxima ação. A ativação usa uma ação padrão e uma tentativa de Expulsão.','Expulsar/Fascinar Mortos-vivos, Expulsão Adicional',ARRAY['divino']::text[],'v35-defensores','D&D 3.5 — Defensores da Fé',19,'dnd35','{"id":"defensores-vinganca-divina","name":"Vingança Divina","type":"Divino","summary":"Você é capaz de canalizar a energia sagrada para causar dano de combate adicional aos mortos-vivos.","prerequisites":["Expulsar/Fascinar Mortos-vivos","Expulsão Adicional"],"benefit":"O personagem adiciona 2d6 pontos de dano sagrado a todos os ataques bem-sucedidos contra mortos-vivos, usando armas brancas, até o final de sua próxima ação. A ativação usa uma ação padrão e uma tentativa de Expulsão."}'::jsonb)
insert into public.catalog_spells (id,name_pt,name_en,description_pt,rank,is_cantrip,is_focus,traditions,cast_actions,range,targets,duration,defense,traits,ruleset,source_book,source_page,system_id,data) values
('dnd35.defensores.spell.defensores-abencoar-funeral','Abençoar Funeral','Abençoar Funeral','Usando essa magia, o clérigo protege um cadáver das influências e efeitos malignos. A menos que o corpo seja profanado ou a benção seja anulada, o indivíduo não poderá ser transformado num morto-vivo ou numa cria desses monstros (como um carniçal ou um vampiro, por exemplo). Além disso, qualquer criatura que deseje perturbar o corpo será afetada por uma onda de medo e deve obter sucesso num teste de Vontade ou fugirá do local durante um minuto por nível do conjurador. Se o corpo protegido for ressuscitado, a magia abençoar funeral será dissipada.',1,false,false,ARRAY['Clr 1']::text[],'10 minutos','Toque','Área: Cadáver tocado','Permanente','Vontade anula (veja texto)',ARRAY['Abjuração [Bem]']::text[],'v35-defensores','D&D 3.5 — Defensores da Fé',81,'dnd35','{"id":"defensores-abencoar-funeral","name":"Abençoar Funeral","school":"Abjuração [Bem]","level":"Clr 1","components":"V, S, M, XP","castingTime":"10 minutos","range":"Toque","target":"Área: Cadáver tocado","duration":"Permanente","savingThrow":"Vontade anula (veja texto)","spellResistance":"Sim","description":"Usando essa magia, o clérigo protege um cadáver das influências e efeitos malignos. A menos que o corpo seja profanado ou a benção seja anulada, o indivíduo não poderá ser transformado num morto-vivo ou numa cria desses monstros (como um carniçal ou um vampiro, por exemplo). Além disso, qualquer criatura que deseje perturbar o corpo será afetada por uma onda de medo e deve obter sucesso num teste de Vontade ou fugirá do local durante um minuto por nível do conjurador. Se o corpo protegido for ressuscitado, a magia abençoar funeral será dissipada.","materialComponent":"O símbolo sagrado do conjurador e um frasco de água benta ou profana, conforme a tendência, que é borrifada sobre o cadáver.","xpCost":"100 XP"}'::jsonb),
('dnd35.defensores.spell.defensores-agilidade-divina','Agilidade Divina','Agilidade Divina','Invocando o poder divino de seu patrono, você concede mais agilidade e capacidade de combate à criatura tocada. Você lhe fornece o bônus base de resistência de Reflexos de um ladino do seu nível de personagem, um bônus de aprimoramento na Destreza suficiente para elevá-la até 18 (caso não seja 18 ou superior) e o talento Deslocamento enquanto a magia permanecer ativa.',5,false,false,ARRAY['Clr 5']::text[],'1 ação','Toque','Alvo: Criatura viva tocada','1 rodada/nível','Vontade anula (benéfica)',ARRAY['Transmutação']::text[],'v35-defensores','D&D 3.5 — Defensores da Fé',81,'dnd35','{"id":"defensores-agilidade-divina","name":"Agilidade Divina","school":"Transmutação","level":"Clr 5","components":"V, S","castingTime":"1 ação","range":"Toque","target":"Alvo: Criatura viva tocada","duration":"1 rodada/nível","savingThrow":"Vontade anula (benéfica)","spellResistance":"Não","description":"Invocando o poder divino de seu patrono, você concede mais agilidade e capacidade de combate à criatura tocada. Você lhe fornece o bônus base de resistência de Reflexos de um ladino do seu nível de personagem, um bônus de aprimoramento na Destreza suficiente para elevá-la até 18 (caso não seja 18 ou superior) e o talento Deslocamento enquanto a magia permanecer ativa."}'::jsonb),
('dnd35.defensores.spell.defensores-agua-doce','Água Doce','Água Doce','Essa magia localiza um lençol de água fresca a até 30 m abaixo da superfície. Se a água encontrada estiver dentro do alcance, a magia escavará um poço até ela. Caso contrário, a magia fracassa.',3,false,false,ARRAY['Clr 3, Drd 2']::text[],'1 ação','Longo (120 m + 12 m/nível)','Efeito: Um poço com 3 m de diâmetro e até 30 m de profundidade','Instantânea','Nenhum',ARRAY['Adivinhação']::text[],'v35-defensores','D&D 3.5 — Defensores da Fé',81,'dnd35','{"id":"defensores-agua-doce","name":"Água Doce","school":"Adivinhação","level":"Clr 3, Drd 2","components":"V, S, M","castingTime":"1 ação","range":"Longo (120 m + 12 m/nível)","target":"Efeito: Um poço com 3 m de diâmetro e até 30 m de profundidade","duration":"Instantânea","savingThrow":"Nenhum","spellResistance":"Não","description":"Essa magia localiza um lençol de água fresca a até 30 m abaixo da superfície. Se a água encontrada estiver dentro do alcance, a magia escavará um poço até ela. Caso contrário, a magia fracassa.","materialComponent":"Uma pá ou espátula."}'::jsonb),
('dnd35.defensores.spell.defensores-aracnideo-mental','Aracnídeo Mental','Aracnídeo Mental','Essa magia lhe permite vasculhar os pensamentos de até oito criaturas diferentes, usando uma ação padrão, simultaneamente, e obter as seguintes informações: • O caos incessante dos pensamentos e imagens superficiais. • As linhas de raciocínio individuais, em qualquer ordem desejada. • Detalhes conhecidos por todos os indivíduos sobre um único assunto, objeto ou criatura — você obtém um fragmento de informação por nível de conjurador. • Um estudo dos pensamentos e memórias de uma criatura em especial no grupo. Uma vez por rodada, exceto quando você realiza um estudo detalhado da mente de uma criatura, poderá implantar uma sugestão na mente de qualquer um dos alvos usando uma ação padrão. A criatura deve realizar outro teste de resistência de Vontade para resistir à sugestão, usando a CD inicial do aracnídeo mental (as criaturas que tenham resistência especial a magias de encantamento podem utilizá-la para evitar a sugestão.) Um sucesso nesse teste de resistência não anula os demais efeitos de aracnídeo mental. A seu critério, é possível afetar todos os seres inteligentes dentro do alcance (até o limite de oito criaturas), começando com os alvos conhecidos ou que tenham nomes. O idioma não é um impedimento e você não precisa conhecer pessoalmente os alvos — pode-se escolher, por exemplo, "os oito guardas mais próximos que deveriam estar naquela câmara." A magia não afetará as criaturas que obtenham sucesso no teste de resistência de Vontade inicial.',8,false,false,ARRAY['Clr 8, Mente 7']::text[],'1 rodada completa','Longo (120 m + 12 m/nível)','Alvos: Até oito criaturas vivas na área','1 minuto por nível','Vontade anula',ARRAY['Adivinhação [ação mental]']::text[],'v35-defensores','D&D 3.5 — Defensores da Fé',81,'dnd35','{"id":"defensores-aracnideo-mental","name":"Aracnídeo Mental","school":"Adivinhação [ação mental]","level":"Clr 8, Mente 7","components":"V, S, M, FD","castingTime":"1 rodada completa","range":"Longo (120 m + 12 m/nível)","target":"Alvos: Até oito criaturas vivas na área","duration":"1 minuto por nível","savingThrow":"Vontade anula","spellResistance":"Sim","description":"Essa magia lhe permite vasculhar os pensamentos de até oito criaturas diferentes, usando uma ação padrão, simultaneamente, e obter as seguintes informações: • O caos incessante dos pensamentos e imagens superficiais. • As linhas de raciocínio individuais, em qualquer ordem desejada. • Detalhes conhecidos por todos os indivíduos sobre um único assunto, objeto ou criatura — você obtém um fragmento de informação por nível de conjurador. • Um estudo dos pensamentos e memórias de uma criatura em especial no grupo. Uma vez por rodada, exceto quando você realiza um estudo detalhado da mente de uma criatura, poderá implantar uma sugestão na mente de qualquer um dos alvos usando uma ação padrão. A criatura deve realizar outro teste de resistência de Vontade para resistir à sugestão, usando a CD inicial do aracnídeo mental (as criaturas que tenham resistência especial a magias de encantamento podem utilizá-la para evitar a sugestão.) Um sucesso nesse teste de resistência não anula os demais efeitos de aracnídeo mental. A seu critério, é possível afetar todos os seres inteligentes dentro do alcance (até o limite de oito criaturas), começando com os alvos conhecidos ou que tenham nomes. O idioma não é um impedimento e você não precisa conhecer pessoalmente os alvos — pode-se escolher, por exemplo, \"os oito guardas mais próximos que deveriam estar naquela câmara.\" A magia não afetará as criaturas que obtenham sucesso no teste de resistência de Vontade inicial.","materialComponent":"Uma aranha de qualquer tamanho ou espécie. Ela pode estar morta, mas ainda deve ter as oito patas."}'::jsonb),
('dnd35.defensores.spell.defensores-arbustos','Arbustos','Arbustos','Pequenos espinhos ou farpas mágicas projetam-se da superfície de uma arma de madeira — como uma clava, uma clava grande, um nunchaku ou um bordão. Enquanto a magia permanecer ativa, a arma causará dano perfurante e de concussão, além de receber +1 de bônus de aprimoramento no ataque e causar +1 ponto de dano por nível do conjurador (limite +10). Essa magia afeta somente armas brancas que sejam feitas de madeira. Por exemplo, ela não afetará um arco, uma flecha ou uma maça de metal.',2,false,false,ARRAY['Clr 2, Drd 2']::text[],'1 ação','Toque','Alvo: Arma de madeira tocada','1 rodada/nível','Nenhum',ARRAY['Transmutação']::text[],'v35-defensores','D&D 3.5 — Defensores da Fé',81,'dnd35','{"id":"defensores-arbustos","name":"Arbustos","school":"Transmutação","level":"Clr 2, Drd 2","components":"V, S, M","castingTime":"1 ação","range":"Toque","target":"Alvo: Arma de madeira tocada","duration":"1 rodada/nível","savingThrow":"Nenhum","spellResistance":"Não","description":"Pequenos espinhos ou farpas mágicas projetam-se da superfície de uma arma de madeira — como uma clava, uma clava grande, um nunchaku ou um bordão. Enquanto a magia permanecer ativa, a arma causará dano perfurante e de concussão, além de receber +1 de bônus de aprimoramento no ataque e causar +1 ponto de dano por nível do conjurador (limite +10). Essa magia afeta somente armas brancas que sejam feitas de madeira. Por exemplo, ela não afetará um arco, uma flecha ou uma maça de metal.","materialComponent":"Um pequeno espinho."}'::jsonb),
('dnd35.defensores.spell.defensores-arma-da-divindade','Arma da Divindade','Arma da Divindade','Você deve estar empunhando a arma favorita de sua divindade para conjurar essa magia. O conjurador poderá brandir a arma como se possuísse o Talento Usar Arma adequado, mesmo se normalmente não o tiver. A arma recebe +1 de bônus de melhoria nas jogadas de ataque e dano e uma habilidade especial (consulte a lista a seguir). Uma arma dupla recebe o bônus de melhoria e a habilidade especial para apenas uma de suas pontas, a critério do conjurador. O bônus de melhoria aumenta conforme o nível do conjurador: +2 a partir do 9º nível; +3 a partir do 12º; +4 a partir do 15º nível e +5 no 18º nível.',4,false,false,ARRAY['Clr 4, Misticismo 4, Pal 4']::text[],'1 ação','Pessoal','Alvo: Sua arma','1 rodada/nível',null,ARRAY['Transmutação']::text[],'v35-defensores','D&D 3.5 — Defensores da Fé',81,'dnd35','{"id":"defensores-arma-da-divindade","name":"Arma da Divindade","school":"Transmutação","level":"Clr 4, Misticismo 4, Pal 4","components":"V, FD","castingTime":"1 ação","range":"Pessoal","target":"Alvo: Sua arma","duration":"1 rodada/nível","description":"Você deve estar empunhando a arma favorita de sua divindade para conjurar essa magia. O conjurador poderá brandir a arma como se possuísse o Talento Usar Arma adequado, mesmo se normalmente não o tiver. A arma recebe +1 de bônus de melhoria nas jogadas de ataque e dano e uma habilidade especial (consulte a lista a seguir). Uma arma dupla recebe o bônus de melhoria e a habilidade especial para apenas uma de suas pontas, a critério do conjurador. O bônus de melhoria aumenta conforme o nível do conjurador: +2 a partir do 9º nível; +3 a partir do 12º; +4 a partir do 15º nível e +5 no 18º nível."}'::jsonb),
('dnd35.defensores.spell.defensores-aspecto-da-divindade','Aspecto da Divindade','Aspecto da Divindade','Como aspecto da divindade menor, mas o conjurador adquire todas as qualidades de uma criatura celestial ou abissal (consulte o Livro dos Monstros para obter detalhes): • Você adquire uma aparência metálica e brilhante (para os clérigos bons) ou aterrorizante (para os maus). • Você adquire a habilidade de destruir o mal (ou o bem) uma vez por dia. Adicione seu modificador de Carisma numa jogada de ataque e o seu nível de personagem ao dano contra um inimigo de tendência oposta à sua. • Você adquire Visão no Escuro de 18 m. • Você adquire resistência contra ácido, frio e eletricidade 20 (para clérigos bons) resistência contra fogo e frio 20 (para clérigos do mal). • Você adquire redução de dano 10/+3. • Você adquire RM 25. Seu tipo de criatura não se altera (você não se transforma numa criatura extra-planar).',6,false,false,ARRAY['Misticismo 6']::text[],null,null,null,null,null,ARRAY['Transmutação [Bem, Mal]']::text[],'v35-defensores','D&D 3.5 — Defensores da Fé',81,'dnd35','{"id":"defensores-aspecto-da-divindade","name":"Aspecto da Divindade","school":"Transmutação [Bem, Mal]","level":"Misticismo 6","description":"Como aspecto da divindade menor, mas o conjurador adquire todas as qualidades de uma criatura celestial ou abissal (consulte o Livro dos Monstros para obter detalhes): • Você adquire uma aparência metálica e brilhante (para os clérigos bons) ou aterrorizante (para os maus). • Você adquire a habilidade de destruir o mal (ou o bem) uma vez por dia. Adicione seu modificador de Carisma numa jogada de ataque e o seu nível de personagem ao dano contra um inimigo de tendência oposta à sua. • Você adquire Visão no Escuro de 18 m. • Você adquire resistência contra ácido, frio e eletricidade 20 (para clérigos bons) resistência contra fogo e frio 20 (para clérigos do mal). • Você adquire redução de dano 10/+3. • Você adquire RM 25. Seu tipo de criatura não se altera (você não se transforma numa criatura extra-planar)."}'::jsonb),
('dnd35.defensores.spell.defensores-aspecto-da-divindade-maior','Aspecto da Divindade Maior','Aspecto da Divindade Maior','Como aspecto da divindade menor, mas você adquire todas as qualidades de um meio-celestial ou meio-abissal (consulte o Apêndice 3 do Livro dos Monstros para obter detalhes). Você não recebe as habilidades similares a magia dessas criaturas. Seu tipo de criatura muda para extra-planar enquanto a magia permanecer ativa. Diferente dos outros extra-planares, você pode ser ressuscitado caso morra nesta forma. Os clérigos bons adquirem as seguintes características: • Asas cobertas de penas que lhe permitem voar com o dobro do seu deslocamento (capacidade de manobra boa). • +1 de armadura natural. • Visão na penumbra. • Imunidade a ácido, frio, doenças e eletricidade. • +4 de bônus racial em testes de resistência contra venenos. • Os seguintes bônus de aprimoramento nos valores de habilidade: +4 For, +2 Des, +4 Cons, +2 Int, +4 Sab, +4 Car. Os clérigos maus adquirem as seguintes características: • Asas de couro que lhe permitem voar com seu deslocamento normal (capacidade de manobra média). • +1 de armadura natural. • Ataques de mordida e garras. Caso seja uma criatura Média ou Grande, a mordida causará 1d6 pontos de dano e cada garra causará 1d4 pontos de dano. Caso seja uma criatura Pequena, a mordida causará 1d3 pontos de dano e cada garra causará 1d3 pontos de dano. • Visão no Escuro de 18 m. • Imunidade contra venenos. • Resistência contra ácido, frio, eletricidade e fogo 20. • Os seguintes bônus de aprimoramento nos valores de habilidade: +4 For, +4 Des, +2 Cons, +4 Int, +4 Sab, +2 Car.',9,false,false,ARRAY['Misticismo 9']::text[],null,null,null,null,null,ARRAY['Transmutação [Bem, Mal]']::text[],'v35-defensores','D&D 3.5 — Defensores da Fé',81,'dnd35','{"id":"defensores-aspecto-da-divindade-maior","name":"Aspecto da Divindade Maior","school":"Transmutação [Bem, Mal]","level":"Misticismo 9","description":"Como aspecto da divindade menor, mas você adquire todas as qualidades de um meio-celestial ou meio-abissal (consulte o Apêndice 3 do Livro dos Monstros para obter detalhes). Você não recebe as habilidades similares a magia dessas criaturas. Seu tipo de criatura muda para extra-planar enquanto a magia permanecer ativa. Diferente dos outros extra-planares, você pode ser ressuscitado caso morra nesta forma. Os clérigos bons adquirem as seguintes características: • Asas cobertas de penas que lhe permitem voar com o dobro do seu deslocamento (capacidade de manobra boa). • +1 de armadura natural. • Visão na penumbra. • Imunidade a ácido, frio, doenças e eletricidade. • +4 de bônus racial em testes de resistência contra venenos. • Os seguintes bônus de aprimoramento nos valores de habilidade: +4 For, +2 Des, +4 Cons, +2 Int, +4 Sab, +4 Car. Os clérigos maus adquirem as seguintes características: • Asas de couro que lhe permitem voar com seu deslocamento normal (capacidade de manobra média). • +1 de armadura natural. • Ataques de mordida e garras. Caso seja uma criatura Média ou Grande, a mordida causará 1d6 pontos de dano e cada garra causará 1d4 pontos de dano. Caso seja uma criatura Pequena, a mordida causará 1d3 pontos de dano e cada garra causará 1d3 pontos de dano. • Visão no Escuro de 18 m. • Imunidade contra venenos. • Resistência contra ácido, frio, eletricidade e fogo 20. • Os seguintes bônus de aprimoramento nos valores de habilidade: +4 For, +4 Des, +2 Cons, +4 Int, +4 Sab, +2 Car."}'::jsonb),
('dnd35.defensores.spell.defensores-aspecto-da-divindade-menor','Aspecto da Divindade Menor','Aspecto da Divindade Menor','Quando você conjura essa magia, seu corpo se altera para ficar mais parecido com a forma da sua divindade (de modo bastante limitado, obviamente). Você adquire 1d4+1 de bônus de aprimoramento no Carisma. Você também recebe resistência 10 contra dois ou três tipos de energia: ácido, frio e eletricidade se você for Bom ou frio e fogo se você for Mau.',3,false,false,ARRAY['Misticismo 3, Pal 4']::text[],'1 ação','Pessoal','Alvo: Você','1 rodada/nível',null,ARRAY['Transmutação [Bem, Mal]']::text[],'v35-defensores','D&D 3.5 — Defensores da Fé',81,'dnd35','{"id":"defensores-aspecto-da-divindade-menor","name":"Aspecto da Divindade Menor","school":"Transmutação [Bem, Mal]","level":"Misticismo 3, Pal 4","components":"V, S, FD","castingTime":"1 ação","range":"Pessoal","target":"Alvo: Você","duration":"1 rodada/nível","description":"Quando você conjura essa magia, seu corpo se altera para ficar mais parecido com a forma da sua divindade (de modo bastante limitado, obviamente). Você adquire 1d4+1 de bônus de aprimoramento no Carisma. Você também recebe resistência 10 contra dois ou três tipos de energia: ácido, frio e eletricidade se você for Bom ou frio e fogo se você for Mau."}'::jsonb),
('dnd35.defensores.spell.defensores-bando-de-otyugh','Bando de Otyugh','Bando de Otyugh','Bando de otyugh cria esses monstros a partir de uma grande pilha de restos e lixo, como um esgoto ou uma fossa. É possível escolher entre criar 3d4 otyugh normais ou 1d3+1 otyugh Enormes com 15 DV (veja a pág. 14 do Livro dos Monstros). Os otyugh voluntariamente o auxiliam em combate ou batalhas, realizam missões específicas ou servem como guarda-costas. Eles permanecem com o conjurador durante sete dias, a menos que sejam dissipados. Se as criaturas foram criadas apenas para proteger um local, a duração da magia será 7 meses. Nesse caso, os otyugh devem receber ordens para guardar somente um local ou sala específica. Os otyugh invocados para atuar como guardas não podem sair da área afetada pela magia. Os monstros devem ser conjurados numa área com pelo menos 3 toneladas de esgoto, restos ou carcaças apodrecidas de animais. Depois da conjuração, os otyugh que não foram invocados como guardas podem abandonar a área sob seu comando.',9,false,false,ARRAY['Pestilência 9']::text[],'1 ação','Médio (30 m + 3 m/nível)','Efeito: Três ou mais otyughs, todos a menos de 9 m de distância','Sete dias ou sete meses (D) (veja texto)','Nenhum',ARRAY['Conjuração (Criação)']::text[],'v35-defensores','D&D 3.5 — Defensores da Fé',81,'dnd35','{"id":"defensores-bando-de-otyugh","name":"Bando de Otyugh","school":"Conjuração (Criação)","level":"Pestilência 9","components":"V, S","castingTime":"1 ação","range":"Médio (30 m + 3 m/nível)","target":"Efeito: Três ou mais otyughs, todos a menos de 9 m de distância","duration":"Sete dias ou sete meses (D) (veja texto)","savingThrow":"Nenhum","spellResistance":"Não","description":"Bando de otyugh cria esses monstros a partir de uma grande pilha de restos e lixo, como um esgoto ou uma fossa. É possível escolher entre criar 3d4 otyugh normais ou 1d3+1 otyugh Enormes com 15 DV (veja a pág. 14 do Livro dos Monstros). Os otyugh voluntariamente o auxiliam em combate ou batalhas, realizam missões específicas ou servem como guarda-costas. Eles permanecem com o conjurador durante sete dias, a menos que sejam dissipados. Se as criaturas foram criadas apenas para proteger um local, a duração da magia será 7 meses. Nesse caso, os otyugh devem receber ordens para guardar somente um local ou sala específica. Os otyugh invocados para atuar como guardas não podem sair da área afetada pela magia. Os monstros devem ser conjurados numa área com pelo menos 3 toneladas de esgoto, restos ou carcaças apodrecidas de animais. Depois da conjuração, os otyugh que não foram invocados como guardas podem abandonar a área sob seu comando."}'::jsonb),
('dnd35.defensores.spell.defensores-cacador','Caçador','Caçador','Caçador invoca uma ave de rapina incorpórea, do tamanho de um morcego atroz (quase 1,5 m de comprimento e envergadura de asas de 3 m). Esse pássaro age independente do seu conjurador enquanto a magia permanecer ativa. Quando você invocar o caçador, escolha um alvo. O pássaro atacará esse alvo até a magia terminar ou até eliminá-lo. Caçador: ND 3; Besta Mágica (Grande); DV 4d10; 22 PV; Inic. +5; Desl.: 6 m; vôo 15 m (bom); CA 19 (toque 14, surpresa 9); Corpo a corpo: energia +9 (1d8); Face/Alcance 3 m por 1,5 m/1,5 m; AE Ataque de toque; QE Incorpóreo; Tend N; TR Fort +4, Ref +9, Von +3; For —, Des 20, Cons —, Int 2, Sab 14, Car 6. Perícias e Talentos: Observar +7, Ouvir +7; Acuidade com Arma (energia). Ataque de Toque (Sob): Para determinar a CA do alvo, considere o ataque do caçador como um ataque de toque. Incorpóreo: Afetada apenas por outros seres incorpóreos, armas mágicas +1 (ou melhores), magias, habilidades similares a magia e habilidades sobrenaturais. Quando é atingida por magias ou armas mágicas de uma fonte corpórea, existem 50% de chance da criatura ignorar qualquer dano. Capaz de atravessar objetos sólidos conforme desejar; seus golpes ignoram as armaduras e os escudos. Uma criatura incorpórea sempre se desloca em silêncio.',4,false,false,ARRAY['Clr 4, Drd 3']::text[],'1 ação','Curto (7,5 m + 1,5 m/2 níveis)','Alvo: Uma criatura','1 rodada/nível ou até que o alvo morra','Nenhum',ARRAY['Conjuração (Criação)']::text[],'v35-defensores','D&D 3.5 — Defensores da Fé',81,'dnd35','{"id":"defensores-cacador","name":"Caçador","school":"Conjuração (Criação)","level":"Clr 4, Drd 3","components":"V, S","castingTime":"1 ação","range":"Curto (7,5 m + 1,5 m/2 níveis)","target":"Alvo: Uma criatura","duration":"1 rodada/nível ou até que o alvo morra","savingThrow":"Nenhum","spellResistance":"Não","description":"Caçador invoca uma ave de rapina incorpórea, do tamanho de um morcego atroz (quase 1,5 m de comprimento e envergadura de asas de 3 m). Esse pássaro age independente do seu conjurador enquanto a magia permanecer ativa. Quando você invocar o caçador, escolha um alvo. O pássaro atacará esse alvo até a magia terminar ou até eliminá-lo. Caçador: ND 3; Besta Mágica (Grande); DV 4d10; 22 PV; Inic. +5; Desl.: 6 m; vôo 15 m (bom); CA 19 (toque 14, surpresa 9); Corpo a corpo: energia +9 (1d8); Face/Alcance 3 m por 1,5 m/1,5 m; AE Ataque de toque; QE Incorpóreo; Tend N; TR Fort +4, Ref +9, Von +3; For —, Des 20, Cons —, Int 2, Sab 14, Car 6. Perícias e Talentos: Observar +7, Ouvir +7; Acuidade com Arma (energia). Ataque de Toque (Sob): Para determinar a CA do alvo, considere o ataque do caçador como um ataque de toque. Incorpóreo: Afetada apenas por outros seres incorpóreos, armas mágicas +1 (ou melhores), magias, habilidades similares a magia e habilidades sobrenaturais. Quando é atingida por magias ou armas mágicas de uma fonte corpórea, existem 50% de chance da criatura ignorar qualquer dano. Capaz de atravessar objetos sólidos conforme desejar; seus golpes ignoram as armaduras e os escudos. Uma criatura incorpórea sempre se desloca em silêncio."}'::jsonb),
('dnd35.defensores.spell.defensores-castigar','Castigar','Castigar','Essa magia lhe permite afastar verbalmente os seus oponentes. Gritando os preceitos de sua divindade sobre as outras tendências, você causa dor aos ouvintes — as criaturas na área da magia não precisam compreender suas palavras sagradas para serem afetadas, embora a magia não tenha efeito contra criaturas surdas. Por outro lado, os oponentes de uma mesma tendência ficarão ensurdecidos durante 1d4 rodadas (teste de resistência para reduzir à metade). Os inimigos cuja tendência seja ''um passo'' diferente da sua (Leal, Neutro, Caótico; Bom ou Mau) sofrem 1 ponto de dano por nível do conjurador (máximo 10). Os inimigos cuja tendência estejam além disso sofrem 1d4 pontos de dano por nível do conjurador (máximo 10d4). Um teste de resistência de Fortitude bem-sucedido reduzirá o dano à metade.',4,false,false,ARRAY['Clr 4']::text[],'1 ação','3 m','Área: Emanação de 3 m de raio','Instantânea','Fortitude reduz o dano à metade',ARRAY['Evocação [Sônica]']::text[],'v35-defensores','D&D 3.5 — Defensores da Fé',81,'dnd35','{"id":"defensores-castigar","name":"Castigar","school":"Evocação [Sônica]","level":"Clr 4","components":"V","castingTime":"1 ação","range":"3 m","target":"Área: Emanação de 3 m de raio","duration":"Instantânea","savingThrow":"Fortitude reduz o dano à metade","spellResistance":"Sim","description":"Essa magia lhe permite afastar verbalmente os seus oponentes. Gritando os preceitos de sua divindade sobre as outras tendências, você causa dor aos ouvintes — as criaturas na área da magia não precisam compreender suas palavras sagradas para serem afetadas, embora a magia não tenha efeito contra criaturas surdas. Por outro lado, os oponentes de uma mesma tendência ficarão ensurdecidos durante 1d4 rodadas (teste de resistência para reduzir à metade). Os inimigos cuja tendência seja ''um passo'' diferente da sua (Leal, Neutro, Caótico; Bom ou Mau) sofrem 1 ponto de dano por nível do conjurador (máximo 10). Os inimigos cuja tendência estejam além disso sofrem 1d4 pontos de dano por nível do conjurador (máximo 10d4). Um teste de resistência de Fortitude bem-sucedido reduzirá o dano à metade."}'::jsonb),
('dnd35.defensores.spell.defensores-chamas-da-fe','Chamas da Fé','Chamas da Fé','Você é capaz de transformar temporariamente uma única arma normal ou obra-prima numa arma mágica flamejante. Enquanto a magia permanecer ativa, a arma será uma arma de explosão flamejante +1, que causa 1d6 pontos de dano adicionais por fogo. Num golpe decisivo, ela causará +1d10 pontos de dano por fogo caso seu multiplicador de decisivo seja x2, +2d10 pontos caso o multiplicador seja x3 e +3d10 pontos caso o multiplicador seja x4. O efeito dessa magia não se acumula com qualquer bônus de melhoria ou a habilidade flamejante ou explosão flamejante.',3,false,false,ARRAY['Clr 3']::text[],'1 ação','Toque','Alvo: Arma tocada (não mágica)','1 rodada/nível','Nenhum',ARRAY['Evocação']::text[],'v35-defensores','D&D 3.5 — Defensores da Fé',81,'dnd35','{"id":"defensores-chamas-da-fe","name":"Chamas da Fé","school":"Evocação","level":"Clr 3","components":"V, S, M","castingTime":"1 ação","range":"Toque","target":"Alvo: Arma tocada (não mágica)","duration":"1 rodada/nível","savingThrow":"Nenhum","spellResistance":"Não","description":"Você é capaz de transformar temporariamente uma única arma normal ou obra-prima numa arma mágica flamejante. Enquanto a magia permanecer ativa, a arma será uma arma de explosão flamejante +1, que causa 1d6 pontos de dano adicionais por fogo. Num golpe decisivo, ela causará +1d10 pontos de dano por fogo caso seu multiplicador de decisivo seja x2, +2d10 pontos caso o multiplicador seja x3 e +3d10 pontos caso o multiplicador seja x4. O efeito dessa magia não se acumula com qualquer bônus de melhoria ou a habilidade flamejante ou explosão flamejante.","materialComponent":"Um pedaço de fósforo, tocado na arma."}'::jsonb),
('dnd35.defensores.spell.defensores-chamas-divinas','Chamas Divinas','Chamas Divinas','Chamas divinas cria uma proteção imóvel contra criaturas do frio, como gigantes do gelo. As criaturas do frio que tentarem entrar ou permanecer na área sofrem 1d4 pontos de dano por nível do conjurador, até o limite de 5d4 (Fortitude para reduzir o dano à metade). Esse dano será infligido a cada rodada que a criatura permanecer na área e o teste de Fortitude deve ser realizado de acordo.',2,false,false,ARRAY['Clr 2']::text[],'1 ação','4,5 m','Área: Emanação de 4,5 m de raio, centrada no conjurador','1 rodada/nível','Fortitude reduz o dano à metade',ARRAY['Abjuração']::text[],'v35-defensores','D&D 3.5 — Defensores da Fé',81,'dnd35','{"id":"defensores-chamas-divinas","name":"Chamas Divinas","school":"Abjuração","level":"Clr 2","components":"V, S","castingTime":"1 ação","range":"4,5 m","target":"Área: Emanação de 4,5 m de raio, centrada no conjurador","duration":"1 rodada/nível","savingThrow":"Fortitude reduz o dano à metade","spellResistance":"Sim","description":"Chamas divinas cria uma proteção imóvel contra criaturas do frio, como gigantes do gelo. As criaturas do frio que tentarem entrar ou permanecer na área sofrem 1d4 pontos de dano por nível do conjurador, até o limite de 5d4 (Fortitude para reduzir o dano à metade). Esse dano será infligido a cada rodada que a criatura permanecer na área e o teste de Fortitude deve ser realizado de acordo."}'::jsonb),
('dnd35.defensores.spell.defensores-coracao-de-urso','Coração de Urso','Coração de Urso','Você transforma seus aliados (um por nível de conjurador) em guerreiros ferozes, mas os deixa exaustos no processo. Os aliados recebem +4 de bônus de aprimoramento na Força e +1d4 pontos de vida temporários a cada nível do conjurador. Quando a duração da magia terminar, qualquer ponto de vida temporário será perdido e cada aliado sofrerá 1 ponto de dano por contusão a cada nível do conjurador da magia.',4,false,false,ARRAY['Mestre das Feras 4, Clr 5, Drd 4']::text[],'1 ação','6 m','Alvo: Todos os aliados vivos num raio de 6 m','1 rodada/nível','Vontade anula',ARRAY['Transmutação']::text[],'v35-defensores','D&D 3.5 — Defensores da Fé',81,'dnd35','{"id":"defensores-coracao-de-urso","name":"Coração de Urso","school":"Transmutação","level":"Mestre das Feras 4, Clr 5, Drd 4","components":"V, S","castingTime":"1 ação","range":"6 m","target":"Alvo: Todos os aliados vivos num raio de 6 m","duration":"1 rodada/nível","savingThrow":"Vontade anula","spellResistance":"Não","description":"Você transforma seus aliados (um por nível de conjurador) em guerreiros ferozes, mas os deixa exaustos no processo. Os aliados recebem +4 de bônus de aprimoramento na Força e +1d4 pontos de vida temporários a cada nível do conjurador. Quando a duração da magia terminar, qualquer ponto de vida temporário será perdido e cada aliado sofrerá 1 ponto de dano por contusão a cada nível do conjurador da magia."}'::jsonb),
('dnd35.defensores.spell.defensores-coroa-da-gloria','Coroa da Glória','Coroa da Glória','O conjurador fica envolto por uma aura de autoridade celestial, inspirando temor em qualquer criatura inferior capaz de contemplar a sua terrível perfeição e retidão. Você recebe +4 de bônus de aprimoramento no Carisma enquanto a magia permanecer ativa. Todas as criaturas com menos de 8 DV param suas ações em andamento e são compelidas a olharem para o conjurador. Para realizar qualquer atitude hostil contra você, elas devem obter sucesso num teste de resistência de Vontade. Caso não obtenha sucesso na primeira tentativa, o indivíduo ficará cativado (idêntico à magia cativar) enquanto a magia permanecer ativa e enquanto estiver na área afetada, mas não tentará sair da área voluntariamente. As criaturas com 8 DV ou mais prestarão atenção ao conjurador, mas não sofrerão esses efeitos. Quando o conjurador falar, todos os ouvintes compreenderão por telepatia, mesmo que não conheçam seu idioma. é possível realizar até três sugestões para as criaturas com menos de 8 DV, com efeitos idênticos à magia sugestionar multidões (Vontade anula); as criaturas com 8 DV ou mais não são afetadas. Somente as criaturas dentro do alcance da sugestão poderão ser afetadas por esse efeito de coroa da glória.',8,false,false,ARRAY['Glória 8']::text[],'1 rodada completa','36 m','Área: Emanação de 36 m de raio, centrada no conjurador','1 minuto/nível','Vontade anula',ARRAY['Evocação']::text[],'v35-defensores','D&D 3.5 — Defensores da Fé',81,'dnd35','{"id":"defensores-coroa-da-gloria","name":"Coroa da Glória","school":"Evocação","level":"Glória 8","components":"V, S, M, FD","castingTime":"1 rodada completa","range":"36 m","target":"Área: Emanação de 36 m de raio, centrada no conjurador","duration":"1 minuto/nível","savingThrow":"Vontade anula","spellResistance":"Sim","description":"O conjurador fica envolto por uma aura de autoridade celestial, inspirando temor em qualquer criatura inferior capaz de contemplar a sua terrível perfeição e retidão. Você recebe +4 de bônus de aprimoramento no Carisma enquanto a magia permanecer ativa. Todas as criaturas com menos de 8 DV param suas ações em andamento e são compelidas a olharem para o conjurador. Para realizar qualquer atitude hostil contra você, elas devem obter sucesso num teste de resistência de Vontade. Caso não obtenha sucesso na primeira tentativa, o indivíduo ficará cativado (idêntico à magia cativar) enquanto a magia permanecer ativa e enquanto estiver na área afetada, mas não tentará sair da área voluntariamente. As criaturas com 8 DV ou mais prestarão atenção ao conjurador, mas não sofrerão esses efeitos. Quando o conjurador falar, todos os ouvintes compreenderão por telepatia, mesmo que não conheçam seu idioma. é possível realizar até três sugestões para as criaturas com menos de 8 DV, com efeitos idênticos à magia sugestionar multidões (Vontade anula); as criaturas com 8 DV ou mais não são afetadas. Somente as criaturas dentro do alcance da sugestão poderão ser afetadas por esse efeito de coroa da glória.","materialComponent":"Uma opala de 200 PO ou mais."}'::jsonb),
('dnd35.defensores.spell.defensores-corrente-de-caos','Corrente de Caos','Corrente de Caos','Esse poderoso instrumento do caos espalha insanidade através do toque. O conjurador infectará a primeira vítima ao realizar um ataque de toque bem-sucedido. Caso o alvo fracasse num teste de resistência de Vontade, sofrerá os efeitos de insanidade (um efeito de confusão contínua). Essa condição será permanente a menos que seja anulada, e a insanidade será transmitida a qualquer criatura tocada pelo alvo. Qualquer indivíduo que obtenha sucesso no teste de resistência inicial ficará imune a essa utilização de corrente do caos. Todas as pessoas tocadas pela vítima inicial enquanto a magia permanecer ativa (inclusive através de ataques bem-sucedidos) devem obter sucesso num teste de resistência de Vontade contra a CD original ou sofrerão os efeitos de insanidade. Cada uma dessas vítimas conseguirá propagar a corrente durante 1 dia a cada 5 níveis de conjurador depois da infecção. No máximo, a magia afeta cinco pessoas por nível do conjurador. É possível curar as vítimas usando quaisquer recursos eficazes contra a insanidade, como restauração aprimorada, desejo restrito, milagre ou desejo. Qualquer pessoa curada ficará imune a essa utilização de corrente do caos. Observação para o Mestre: Quando os efeitos dessa magia se espalharem sobre uma população grande, mas que não sejam aventureiros, durante um certo período de tempo, não é necessário rastrear cada indivíduo afetado. Em vez disso, apenas decida se os indivíduos encontrados estão insanos e se podem transmitir a corrente, baseando-se no seu julgamento do progresso da corrente de loucura.',8,false,false,ARRAY['Clr 8']::text[],'1 ação','Toque','Alvo: Criatura viva e inteligente tocada','1 dia/5 níveis de conjurador, a partir do dia do toque (veja texto)','Vontade anula',ARRAY['Encantamento (Compulsão) [ação mental]']::text[],'v35-defensores','D&D 3.5 — Defensores da Fé',81,'dnd35','{"id":"defensores-corrente-de-caos","name":"Corrente de Caos","school":"Encantamento (Compulsão) [ação mental]","level":"Clr 8","components":"V, S","castingTime":"1 ação","range":"Toque","target":"Alvo: Criatura viva e inteligente tocada","duration":"1 dia/5 níveis de conjurador, a partir do dia do toque (veja texto)","savingThrow":"Vontade anula","spellResistance":"Sim","description":"Esse poderoso instrumento do caos espalha insanidade através do toque. O conjurador infectará a primeira vítima ao realizar um ataque de toque bem-sucedido. Caso o alvo fracasse num teste de resistência de Vontade, sofrerá os efeitos de insanidade (um efeito de confusão contínua). Essa condição será permanente a menos que seja anulada, e a insanidade será transmitida a qualquer criatura tocada pelo alvo. Qualquer indivíduo que obtenha sucesso no teste de resistência inicial ficará imune a essa utilização de corrente do caos. Todas as pessoas tocadas pela vítima inicial enquanto a magia permanecer ativa (inclusive através de ataques bem-sucedidos) devem obter sucesso num teste de resistência de Vontade contra a CD original ou sofrerão os efeitos de insanidade. Cada uma dessas vítimas conseguirá propagar a corrente durante 1 dia a cada 5 níveis de conjurador depois da infecção. No máximo, a magia afeta cinco pessoas por nível do conjurador. É possível curar as vítimas usando quaisquer recursos eficazes contra a insanidade, como restauração aprimorada, desejo restrito, milagre ou desejo. Qualquer pessoa curada ficará imune a essa utilização de corrente do caos. Observação para o Mestre: Quando os efeitos dessa magia se espalharem sobre uma população grande, mas que não sejam aventureiros, durante um certo período de tempo, não é necessário rastrear cada indivíduo afetado. Em vez disso, apenas decida se os indivíduos encontrados estão insanos e se podem transmitir a corrente, baseando-se no seu julgamento do progresso da corrente de loucura."}'::jsonb),
('dnd35.defensores.spell.defensores-criar-itens-permanentes','Criar Itens Permanentes','Criar Itens Permanentes','Você cria um único objeto comum (mas não mágico), feito de qualquer material. Os itens criados dessa forma são permanentes e não podem ser destruídos por dissipar magias ou poderes de neutralização. Para todos os propósitos, esses itens são completamente reais. O volume do item criado não pode exceder 30 cm³ por nível do conjurador. Você precisa obter sucesso no teste de perícia adequado para criar um item complexo, como um teste de Ofício (fabricar arcos) para criar uma flecha útil ou um teste de Ofícios (ourives) para criar uma gema polida e lapidada. Diferente dos itens criados pelas magias de níveis inferiores, como criar itens efêmeros e criar itens temporários (consulte o Livro do Jogador para obter a descrição dessas magias), os objetos gerados pela magia criar itens permanentes podem ser utilizados como componentes materiais.',8,false,false,ARRAY['Criação 8']::text[],'10 minutos','0 m','Efeito: Um objeto comum (mas não mágico), feito de matéria inorgânica, com até 30 cm³/nível','Instantânea','Nenhum',ARRAY['Conjuração (Criação)']::text[],'v35-defensores','D&D 3.5 — Defensores da Fé',81,'dnd35','{"id":"defensores-criar-itens-permanentes","name":"Criar Itens Permanentes","school":"Conjuração (Criação)","level":"Criação 8","components":"V, S, M, XP","castingTime":"10 minutos","range":"0 m","target":"Efeito: Um objeto comum (mas não mágico), feito de matéria inorgânica, com até 30 cm³/nível","duration":"Instantânea","savingThrow":"Nenhum","spellResistance":"Não","description":"Você cria um único objeto comum (mas não mágico), feito de qualquer material. Os itens criados dessa forma são permanentes e não podem ser destruídos por dissipar magias ou poderes de neutralização. Para todos os propósitos, esses itens são completamente reais. O volume do item criado não pode exceder 30 cm³ por nível do conjurador. Você precisa obter sucesso no teste de perícia adequado para criar um item complexo, como um teste de Ofício (fabricar arcos) para criar uma flecha útil ou um teste de Ofícios (ourives) para criar uma gema polida e lapidada. Diferente dos itens criados pelas magias de níveis inferiores, como criar itens efêmeros e criar itens temporários (consulte o Livro do Jogador para obter a descrição dessas magias), os objetos gerados pela magia criar itens permanentes podem ser utilizados como componentes materiais.","materialComponent":"Um pequeno pedaço de matéria do mesmo tipo do objeto que o conjurador deseja criar — uma lasca de madeira para criar flechas, um minúsculo pedaço da pedra para criar uma gema polida, etc.","xpCost":"O valor em PO do item ou um mínimo de 1 XP, o que for mais alto (veja o Livro do Jogador para obter os custos dos itens)."}'::jsonb),
('dnd35.defensores.spell.defensores-desatar','Desatar','Desatar','Quando você conjura desatar, uma explosão de energia atravessa seu corpo e destrói magicamente quaisquer magias capazes de restringir, constringir, selar ou imobilizar, com as exceções indicadas a seguir. A magia desatar anula as magias enfeitiçar e imobilizar de todos os tipos, trancas arcanas e similares, magias que criam barreiras físicas ou mágicas (muralha de pedra, muralha de energia), proteger fortalezas, estase temporal, lentidão, entre outras. O efeito da magia estátua é dissipado. Um recipiente arcano é rompido — destruído para sempre — e a força vital contida nele também é eliminada. Além disso, qualquer magia que contenha outros efeitos mágicos, inclusive outras magias, imediatamente liberam esses efeitos com alcance de 0 m (entre elas, boca encantada, transferência de poder divino e similares). As magias de proteção, como proteção contra o mal, escudo arcano, globo de invulnerabilidade e similares não são afetadas por desatar. As criaturas petrificadas não são reveladas, nem restauradas. As obrigações individuais dos servos não são removidas (entre elas o vínculos dos familiares, assassinos fantasmagóricos, gênios e elementais). Um campo antimagia não é afetado e os efeitos de desatar não são capazes de penetrá-lo. Um círculo mágico contra o mal (ou outra tendência) que esteja aprisionando uma criatura é dissipado. As maldições e as magias tarefa/missão são anuladas apenas se o conjurador pertencer a um nível equivalente ou superior ao nível do conjurador original. Todos esses efeitos ocorrem a despeito da vontade do conjurador. Os efeitos mágicos carregados, utilizados ou lançados sobre ele permanecem intactos, mas todos os outros atingidos pela explosão serão afetados, inclusive dos seus aliados. A abertura de trancas ou dispositivos de fechamento ativará os alarmes e as armadilhas pertinentes. As criaturas libertadas talvez não sejam amigáveis.',9,false,false,ARRAY['Exorcismo 9, Mag/Fet 9']::text[],'1 rodada','60 m','Área: Explosão de 60 m de raio, centrada no conjurador','Instantânea','Nenhum',ARRAY['Abjuração']::text[],'v35-defensores','D&D 3.5 — Defensores da Fé',81,'dnd35','{"id":"defensores-desatar","name":"Desatar","school":"Abjuração","level":"Exorcismo 9, Mag/Fet 9","components":"V, S, M, FD","castingTime":"1 rodada","range":"60 m","target":"Área: Explosão de 60 m de raio, centrada no conjurador","duration":"Instantânea","savingThrow":"Nenhum","spellResistance":"Não","description":"Quando você conjura desatar, uma explosão de energia atravessa seu corpo e destrói magicamente quaisquer magias capazes de restringir, constringir, selar ou imobilizar, com as exceções indicadas a seguir. A magia desatar anula as magias enfeitiçar e imobilizar de todos os tipos, trancas arcanas e similares, magias que criam barreiras físicas ou mágicas (muralha de pedra, muralha de energia), proteger fortalezas, estase temporal, lentidão, entre outras. O efeito da magia estátua é dissipado. Um recipiente arcano é rompido — destruído para sempre — e a força vital contida nele também é eliminada. Além disso, qualquer magia que contenha outros efeitos mágicos, inclusive outras magias, imediatamente liberam esses efeitos com alcance de 0 m (entre elas, boca encantada, transferência de poder divino e similares). As magias de proteção, como proteção contra o mal, escudo arcano, globo de invulnerabilidade e similares não são afetadas por desatar. As criaturas petrificadas não são reveladas, nem restauradas. As obrigações individuais dos servos não são removidas (entre elas o vínculos dos familiares, assassinos fantasmagóricos, gênios e elementais). Um campo antimagia não é afetado e os efeitos de desatar não são capazes de penetrá-lo. Um círculo mágico contra o mal (ou outra tendência) que esteja aprisionando uma criatura é dissipado. As maldições e as magias tarefa/missão são anuladas apenas se o conjurador pertencer a um nível equivalente ou superior ao nível do conjurador original. Todos esses efeitos ocorrem a despeito da vontade do conjurador. Os efeitos mágicos carregados, utilizados ou lançados sobre ele permanecem intactos, mas todos os outros atingidos pela explosão serão afetados, inclusive dos seus aliados. A abertura de trancas ou dispositivos de fechamento ativará os alarmes e as armadilhas pertinentes. As criaturas libertadas talvez não sejam amigáveis.","materialComponent":"Um imã e uma pitada de salitre."}'::jsonb),
('dnd35.defensores.spell.defensores-dominacao-verdadeira','Dominação Verdadeira','Dominação Verdadeira','Você é capaz de dominar as ações de qualquer humanóide de Médio ou menor. O conjurador estabelece um vínculo telepático com o alvo. Caso exista um idioma em comum, será possível forçá-lo a agir conforme seus desejos, respeitando os limites das habilidades da vítima. Se não houver um idioma em comum, somente comandos básicos poderão ser transmitidos, como "Venha aqui", "Vá para lá", "Lute" ou "Fique parado". Você sabe o que o alvo está sentindo, mas não recebe percepções sensoriais diretas. Os alvos têm uma chance de resistir a esse controle (um teste de resistência de Vontade anulará os efeitos quando a magia é conjurada). Caso o alvo dominado seja ordenado a executar uma tarefa contrária à sua natureza, ele poderá realizar um teste de resistência com -4 de penalidade para resistir a cumprir essa ordem. Ordens obviamente auto-destrutivas são possíveis, mas o alvo deve fracassar no teste de resistência com -4 de penalidade. Depois que o controle for estabelecido, o alcance da magia é ilimitado, mas o conjurador e o alvo devem estar no mesmo plano. Não é necessário ver o indivíduo para controlá-lo. A proteção contra o mal e magias similares são capazes de impedir o controle mental ou neutralizar o vínculo telepático enquanto o alvo estiver protegido, mas não evitam o estabelecimento da dominação ou a dissipam.',8,false,false,ARRAY['Dominação 8']::text[],'1 ação','Médio (30 m + 3 m/nível)','Alvo: Um humanóide Médio ou menor','1 dia/nível','Vontade anula',ARRAY['Encantamento (Compulsão) [ação mental]']::text[],'v35-defensores','D&D 3.5 — Defensores da Fé',81,'dnd35','{"id":"defensores-dominacao-verdadeira","name":"Dominação Verdadeira","school":"Encantamento (Compulsão) [ação mental]","level":"Dominação 8","components":"V, S","castingTime":"1 ação","range":"Médio (30 m + 3 m/nível)","target":"Alvo: Um humanóide Médio ou menor","duration":"1 dia/nível","savingThrow":"Vontade anula","spellResistance":"Sim","description":"Você é capaz de dominar as ações de qualquer humanóide de Médio ou menor. O conjurador estabelece um vínculo telepático com o alvo. Caso exista um idioma em comum, será possível forçá-lo a agir conforme seus desejos, respeitando os limites das habilidades da vítima. Se não houver um idioma em comum, somente comandos básicos poderão ser transmitidos, como \"Venha aqui\", \"Vá para lá\", \"Lute\" ou \"Fique parado\". Você sabe o que o alvo está sentindo, mas não recebe percepções sensoriais diretas. Os alvos têm uma chance de resistir a esse controle (um teste de resistência de Vontade anulará os efeitos quando a magia é conjurada). Caso o alvo dominado seja ordenado a executar uma tarefa contrária à sua natureza, ele poderá realizar um teste de resistência com -4 de penalidade para resistir a cumprir essa ordem. Ordens obviamente auto-destrutivas são possíveis, mas o alvo deve fracassar no teste de resistência com -4 de penalidade. Depois que o controle for estabelecido, o alcance da magia é ilimitado, mas o conjurador e o alvo devem estar no mesmo plano. Não é necessário ver o indivíduo para controlá-lo. A proteção contra o mal e magias similares são capazes de impedir o controle mental ou neutralizar o vínculo telepático enquanto o alvo estiver protegido, mas não evitam o estabelecimento da dominação ou a dissipam."}'::jsonb),
('dnd35.defensores.spell.defensores-escravo-monstruoso','Escravo Monstruoso','Escravo Monstruoso','Como dominação verdadeira, mas afetará qualquer criatura e ela estará dominada permanentemente se fracassar no teste de resistência de Vontade inicial. Uma criatura ordenada a executar uma tarefa contrária à sua natureza poderá realizar um teste de resistência com -4 de penalidade para resistir a cumprir essa ordem. Caso obtenha sucesso, ela continuará sendo uma escrava, apesar desse pequeno contratempo. Depois que a vítima escravizada obtiver sucesso num teste de resistência contra uma ação em particular, todos os seus testes de resistência relacionados a essa ordem não sofrem mais penalidades.',9,false,false,ARRAY['Dominação 9']::text[],'1 ação','Médio (30 m + 3 m/nível)','Alvo: Uma criatura','Instantânea','Vontade anula',ARRAY['Encantamento (Compulsão) [ação mental]']::text[],'v35-defensores','D&D 3.5 — Defensores da Fé',81,'dnd35','{"id":"defensores-escravo-monstruoso","name":"Escravo Monstruoso","school":"Encantamento (Compulsão) [ação mental]","level":"Dominação 9","components":"V, S, XP","castingTime":"1 ação","range":"Médio (30 m + 3 m/nível)","target":"Alvo: Uma criatura","duration":"Instantânea","savingThrow":"Vontade anula","spellResistance":"Sim","description":"Como dominação verdadeira, mas afetará qualquer criatura e ela estará dominada permanentemente se fracassar no teste de resistência de Vontade inicial. Uma criatura ordenada a executar uma tarefa contrária à sua natureza poderá realizar um teste de resistência com -4 de penalidade para resistir a cumprir essa ordem. Caso obtenha sucesso, ela continuará sendo uma escrava, apesar desse pequeno contratempo. Depois que a vítima escravizada obtiver sucesso num teste de resistência contra uma ação em particular, todos os seus testes de resistência relacionados a essa ordem não sofrem mais penalidades.","xpCost":"500 XP por Dado de Vida ou nível do alvo."}'::jsonb),
('dnd35.defensores.spell.defensores-estacas','Estacas','Estacas','Como arbustos, mas a arma recebe +2 de bônus de melhoria nas jogadas de ataques e sua margem de ameaça é dobrada.',3,false,false,ARRAY['Clr 3, Drd 3']::text[],'1 ação','Toque','Alvo: Arma de madeira tocada','1 hora/nível','Nenhum',ARRAY['Transmutação']::text[],'v35-defensores','D&D 3.5 — Defensores da Fé',81,'dnd35','{"id":"defensores-estacas","name":"Estacas","school":"Transmutação","level":"Clr 3, Drd 3","components":"V, S, M","castingTime":"1 ação","range":"Toque","target":"Alvo: Arma de madeira tocada","duration":"1 hora/nível","savingThrow":"Nenhum","spellResistance":"Não","description":"Como arbustos, mas a arma recebe +2 de bônus de melhoria nas jogadas de ataques e sua margem de ameaça é dobrada."}'::jsonb),
('dnd35.defensores.spell.defensores-esturricar','Esturricar','Esturricar','Existem duas versões dessa magia. Para conjurar cada uma, é necessário tocar uma planta e assoprá-la. Área: Quando a magia é conjurada sobre uma planta normal, toda a vegetação numa área de 30 m de raio murchará e morrerá. As flores definham, as folhas caem e qualquer folhagem seca. A magia não causa nenhum mal ao solo, logo é possível substituir as plantas mortas com novas sementes. Esse efeito não permite teste de resistência. Criatura-Planta: Quando é conjurada sobre uma única planta móvel ou inteligente, como um arbusto errante ou um ente, essa magia causa 1d6 pontos de dano por nível do conjurador, até o limite de 15d6. O alvo pode realizar um teste de resistência de Fortitude para reduzir o dano à metade.',5,false,false,ARRAY['Clr 5, Drd 4']::text[],'1 ação','Veja texto','Efeito: Veja texto','Instantânea','Veja texto',ARRAY['Necromancia']::text[],'v35-defensores','D&D 3.5 — Defensores da Fé',81,'dnd35','{"id":"defensores-esturricar","name":"Esturricar","school":"Necromancia","level":"Clr 5, Drd 4","components":"V, S, FD","castingTime":"1 ação","range":"Veja texto","target":"Efeito: Veja texto","duration":"Instantânea","savingThrow":"Veja texto","spellResistance":"Sim","description":"Existem duas versões dessa magia. Para conjurar cada uma, é necessário tocar uma planta e assoprá-la. Área: Quando a magia é conjurada sobre uma planta normal, toda a vegetação numa área de 30 m de raio murchará e morrerá. As flores definham, as folhas caem e qualquer folhagem seca. A magia não causa nenhum mal ao solo, logo é possível substituir as plantas mortas com novas sementes. Esse efeito não permite teste de resistência. Criatura-Planta: Quando é conjurada sobre uma única planta móvel ou inteligente, como um arbusto errante ou um ente, essa magia causa 1d6 pontos de dano por nível do conjurador, até o limite de 15d6. O alvo pode realizar um teste de resistência de Fortitude para reduzir o dano à metade."}'::jsonb),
('dnd35.defensores.spell.defensores-examinar-pensamentos','Examinar Pensamentos','Examinar Pensamentos','Todas as memórias e conhecimentos do alvo tornam-se acessíveis a você, até os pensamentos superficiais. É possível obter respostas para uma pergunta a cada rodada, limitadas pelo conhecimento do alvo. É possível sondar os pensamentos de uma criatura adormecida, mas a vítima poderá realizar um teste de Vontade contra a CD de examinar pensamentos para acordar depois de cada pergunta. Os personagens que desejarem impedir a sondagem devem tentar abandonar a área de alcance da magia, exceto se estiverem imobilizados. As questões são indagadas por telepatia e as respostas são transmitidas direto para a mente do conjurador. Não é necessário ter um idioma em comum, mas talvez as criaturas menos inteligentes somente consigam gerar imagens correlacionadas às suas perguntas.',6,false,false,ARRAY['Mente 6, Mag/Fet 6']::text[],'1 minuto','Curto (7,5 m + 1,5 m/2 níveis)','Alvo: Uma criatura viva/nível','Concentração','Fortitude anula (veja texto)',ARRAY['Adivinhação [ação mental]']::text[],'v35-defensores','D&D 3.5 — Defensores da Fé',81,'dnd35','{"id":"defensores-examinar-pensamentos","name":"Examinar Pensamentos","school":"Adivinhação [ação mental]","level":"Mente 6, Mag/Fet 6","components":"V, S","castingTime":"1 minuto","range":"Curto (7,5 m + 1,5 m/2 níveis)","target":"Alvo: Uma criatura viva/nível","duration":"Concentração","savingThrow":"Fortitude anula (veja texto)","spellResistance":"Sim","description":"Todas as memórias e conhecimentos do alvo tornam-se acessíveis a você, até os pensamentos superficiais. É possível obter respostas para uma pergunta a cada rodada, limitadas pelo conhecimento do alvo. É possível sondar os pensamentos de uma criatura adormecida, mas a vítima poderá realizar um teste de Vontade contra a CD de examinar pensamentos para acordar depois de cada pergunta. Os personagens que desejarem impedir a sondagem devem tentar abandonar a área de alcance da magia, exceto se estiverem imobilizados. As questões são indagadas por telepatia e as respostas são transmitidas direto para a mente do conjurador. Não é necessário ter um idioma em comum, mas talvez as criaturas menos inteligentes somente consigam gerar imagens correlacionadas às suas perguntas."}'::jsonb),
('dnd35.defensores.spell.defensores-flagelo','Flagelo','Flagelo','Essa magia asquerosa causa uma doença grave e enfraquece as criaturas que fracassarem em seus testes de resistência. As criaturas afetadas são imediatamente contaminadas com uma infecção dolorosa, que se espalha e recobre todo o seu corpo em segundos. Surgem bolhas enegrecidas, manchas vermelhas, lesões violeta, pústulas profundas e cistos malignos que são insuportáveis e debilitantes. A doença causa 1d3 pontos de dano temporários de Força e Destreza a cada dia, a menos que a criatura seja bem-sucedida num teste de resistência de Fortitude. Como na podridão da múmia, os testes bem-sucedidos não permitem a recuperação da criatura afligida. Os sintomas persistem até que a criatura encontre algum meio de curar a doença magicamente (como remover doenças, cura, ou restauração).',7,false,false,ARRAY['Pestilência 7']::text[],'1 ação','Longo (120 m + 12 m/nível)','Alvo: Uma criatura viva/nível, todas a menos de 15 m de distância entre si','Instantânea','Fortitude anula',ARRAY['Necromancia']::text[],'v35-defensores','D&D 3.5 — Defensores da Fé',81,'dnd35','{"id":"defensores-flagelo","name":"Flagelo","school":"Necromancia","level":"Pestilência 7","components":"V, S, F, FD","castingTime":"1 ação","range":"Longo (120 m + 12 m/nível)","target":"Alvo: Uma criatura viva/nível, todas a menos de 15 m de distância entre si","duration":"Instantânea","savingThrow":"Fortitude anula","spellResistance":"Sim","description":"Essa magia asquerosa causa uma doença grave e enfraquece as criaturas que fracassarem em seus testes de resistência. As criaturas afetadas são imediatamente contaminadas com uma infecção dolorosa, que se espalha e recobre todo o seu corpo em segundos. Surgem bolhas enegrecidas, manchas vermelhas, lesões violeta, pústulas profundas e cistos malignos que são insuportáveis e debilitantes. A doença causa 1d3 pontos de dano temporários de Força e Destreza a cada dia, a menos que a criatura seja bem-sucedida num teste de resistência de Fortitude. Como na podridão da múmia, os testes bem-sucedidos não permitem a recuperação da criatura afligida. Os sintomas persistem até que a criatura encontre algum meio de curar a doença magicamente (como remover doenças, cura, ou restauração).","materialComponent":"Foco: Um chicote ou chicote de montaria, que é estalado na direção das vítimas durante a conjuração da magia."}'::jsonb),
('dnd35.defensores.spell.defensores-furia','Fúria','Fúria','Você consegue lançar uma criatura num frenesi de ódio incontrolável. Nesse estado, a criatura recebe +4 de Força, +4 de Constituição e +2 de bônus de moral em testes de resistência de Vontade. Diferente da fúria dos bárbaros, a criatura não sofre penalidades na CA e nenhum período de fadiga depois que a duração da magia terminar.',3,false,false,ARRAY['Insanidade 3']::text[],'1 ação','Toque','Alvo: Criatura tocada','1 rodada/nível','Vontade anula (benéfico)',ARRAY['Encantamento (Compulsão) [ação mental]']::text[],'v35-defensores','D&D 3.5 — Defensores da Fé',81,'dnd35','{"id":"defensores-furia","name":"Fúria","school":"Encantamento (Compulsão) [ação mental]","level":"Insanidade 3","components":"V, S","castingTime":"1 ação","range":"Toque","target":"Alvo: Criatura tocada","duration":"1 rodada/nível","savingThrow":"Vontade anula (benéfico)","spellResistance":"Sim (benéfico)","description":"Você consegue lançar uma criatura num frenesi de ódio incontrolável. Nesse estado, a criatura recebe +4 de Força, +4 de Constituição e +2 de bônus de moral em testes de resistência de Vontade. Diferente da fúria dos bárbaros, a criatura não sofre penalidades na CA e nenhum período de fadiga depois que a duração da magia terminar."}'::jsonb),
('dnd35.defensores.spell.defensores-garras-bestiais','Garras Bestiais','Garras Bestiais','Garras bestiais transforma suas mãos e dedos, concedendo-lhe garras longas e curvadas e articulações poderosas. Essas garras servem como armas brancas cortantes (1d6 pontos de dano, mais modificadores mágicos ou de Força, dec. 19-20/x2). É possível golpear com as mãos transformadas sem sofrer ataques de oportunidade. As garras não atrapalham a capacidade manual ou a conjuração de magias.',4,false,false,ARRAY['Clr 4, Drd 3']::text[],'1 ação','Pessoal','Alvo: Você','1 rodada/nível','Nenhum',ARRAY['Transmutação']::text[],'v35-defensores','D&D 3.5 — Defensores da Fé',81,'dnd35','{"id":"defensores-garras-bestiais","name":"Garras Bestiais","school":"Transmutação","level":"Clr 4, Drd 3","components":"V, S, M","castingTime":"1 ação","range":"Pessoal","target":"Alvo: Você","duration":"1 rodada/nível","savingThrow":"Nenhum","spellResistance":"Não","description":"Garras bestiais transforma suas mãos e dedos, concedendo-lhe garras longas e curvadas e articulações poderosas. Essas garras servem como armas brancas cortantes (1d6 pontos de dano, mais modificadores mágicos ou de Força, dec. 19-20/x2). É possível golpear com as mãos transformadas sem sofrer ataques de oportunidade. As garras não atrapalham a capacidade manual ou a conjuração de magias.","materialComponent":"A garra de uma ave de rapina, como uma águia ou falcão."}'::jsonb),
('dnd35.defensores.spell.defensores-genese','Gênese','Gênese','Você cria um plano imóvel, limitado e de acesso restrito — um semi-plano. Os semi-planos criados por essa magia são pequenos, muito menores que os demais. Ela somente pode ser conjurada no Plano Etéreo. Enquanto a conjuração é iniciada, a flutuação de densidade local se altera para criar o semi-plano. Inicialmente, ele cresce num raio de 4,5 m por dia até atingir o alcance inicial máximo de 60 m, conforme absorve substância rapidamente dos vapores e protomatérias etéreas que o envolvem. O ambiente do semi-plano é determinado no início da conjuração de gênese, refletindo qualquer visualização dos desejos do conjurador. É possível definir fatores como atmosfera, água, temperatura e os acidentes geográficos do plano. Entretanto, a magia não cria qualquer forma de vida (como vegetação), nem construções (como prédios, estradas, poços, masmorras, etc.). Se o conjurador desejar esses benefícios, deverá obtê-los de outra forma. Depois que o semi-plano alcançar seu tamanho máximo inicial, é possível conjurar esta magia repetidamente para aumentá-lo, adicionando uma ''bolha'' de 120 m de diâmetro em cada ocasião.',9,false,false,ARRAY['Criação 9']::text[],'1 semana (8 horas/dia)','60 m','Efeito: Um semi-plano dentro do Plano Etéreo, centrado na localização do clérigo','Instantânea','Nenhum',ARRAY['Conjuração (Criação)']::text[],'v35-defensores','D&D 3.5 — Defensores da Fé',81,'dnd35','{"id":"defensores-genese","name":"Gênese","school":"Conjuração (Criação)","level":"Criação 9","components":"V, S, M, XP","castingTime":"1 semana (8 horas/dia)","range":"60 m","target":"Efeito: Um semi-plano dentro do Plano Etéreo, centrado na localização do clérigo","duration":"Instantânea","savingThrow":"Nenhum","spellResistance":"Não","description":"Você cria um plano imóvel, limitado e de acesso restrito — um semi-plano. Os semi-planos criados por essa magia são pequenos, muito menores que os demais. Ela somente pode ser conjurada no Plano Etéreo. Enquanto a conjuração é iniciada, a flutuação de densidade local se altera para criar o semi-plano. Inicialmente, ele cresce num raio de 4,5 m por dia até atingir o alcance inicial máximo de 60 m, conforme absorve substância rapidamente dos vapores e protomatérias etéreas que o envolvem. O ambiente do semi-plano é determinado no início da conjuração de gênese, refletindo qualquer visualização dos desejos do conjurador. É possível definir fatores como atmosfera, água, temperatura e os acidentes geográficos do plano. Entretanto, a magia não cria qualquer forma de vida (como vegetação), nem construções (como prédios, estradas, poços, masmorras, etc.). Se o conjurador desejar esses benefícios, deverá obtê-los de outra forma. Depois que o semi-plano alcançar seu tamanho máximo inicial, é possível conjurar esta magia repetidamente para aumentá-lo, adicionando uma ''bolha'' de 120 m de diâmetro em cada ocasião.","xpCost":"5000 XP"}'::jsonb),
('dnd35.defensores.spell.defensores-grito-enlouquecedor','Grito Enlouquecedor','Grito Enlouquecedor','O alvo não consegue se controlar e ficará gritando, gaguejando e pulando como se estivesse completamente louco. A vítima não conseguirá realizar qualquer ação além de correr em círculos, emitindo gritos estridentes; isso impõe -4 na Classe de Armadura, torna impossível obter sucesso em testes de resistência de Reflexos (exceto se obtiver um 20 natural) e não permite a utilização de escudos.',8,false,false,ARRAY['Insanidade 8']::text[],'1 ação','Toque','Alvo: Criatura viva tocada','1d4+1 rodadas','Nenhum',ARRAY['Encantamento (Compulsão) [ação mental]']::text[],'v35-defensores','D&D 3.5 — Defensores da Fé',81,'dnd35','{"id":"defensores-grito-enlouquecedor","name":"Grito Enlouquecedor","school":"Encantamento (Compulsão) [ação mental]","level":"Insanidade 8","components":"V","castingTime":"1 ação","range":"Toque","target":"Alvo: Criatura viva tocada","duration":"1d4+1 rodadas","savingThrow":"Nenhum","spellResistance":"Sim","description":"O alvo não consegue se controlar e ficará gritando, gaguejando e pulando como se estivesse completamente louco. A vítima não conseguirá realizar qualquer ação além de correr em círculos, emitindo gritos estridentes; isso impõe -4 na Classe de Armadura, torna impossível obter sucesso em testes de resistência de Reflexos (exceto se obtiver um 20 natural) e não permite a utilização de escudos."}'::jsonb),
('dnd35.defensores.spell.defensores-ira-justa-dos-fieis','Ira Justa dos Fiéis','Ira Justa dos Fiéis','Quando você conjura esta magia, seus aliados e companheiros são tomados por uma loucura ou fúria divina que aprimora suas habilidades de combate. Os seus aliados adquirem os benefícios da magia ajuda, recebendo +1 de bônus de moral nas jogadas de ataque e testes de resistência contra efeitos de medo, além de 1d8 pontos de vida temporários enquanto a magia permanecer ativa. Os aliados que veneram a mesma divindade do clérigo recebem os benefícios totais da ira justa. Eles adquirem um ataque corpo a corpo adicional a cada rodada, usando seu bônus de ataque mais favorável, e +2 de bônus de moral nas jogadas de dano e testes de resistência. Eles recebem 1d8 pontos de vida temporários adicionais (totalizando 2d8) e +3 de bônus de moral nos testes de resistência contra magias ou efeitos de ação mental. Quando a duração da magia expirar, todas as criaturas afetadas pela versão completa da ira justa ficarão fatigadas (-2 de Força, -2 de Destreza, não podem correr ou realizar Investidas) durante 10 minutos.',7,false,false,ARRAY['Clr 7']::text[],'1 ação','9 m','Alvos: Todos os aliados numa explosão de 9 m de raio, centrada no conjurador','1 rodada/nível','Nenhum',ARRAY['Encantamento (Compulsão) [ação mental]']::text[],'v35-defensores','D&D 3.5 — Defensores da Fé',81,'dnd35','{"id":"defensores-ira-justa-dos-fieis","name":"Ira Justa dos Fiéis","school":"Encantamento (Compulsão) [ação mental]","level":"Clr 7","components":"V, S, FD","castingTime":"1 ação","range":"9 m","target":"Alvos: Todos os aliados numa explosão de 9 m de raio, centrada no conjurador","duration":"1 rodada/nível","savingThrow":"Nenhum","spellResistance":"Sim","description":"Quando você conjura esta magia, seus aliados e companheiros são tomados por uma loucura ou fúria divina que aprimora suas habilidades de combate. Os seus aliados adquirem os benefícios da magia ajuda, recebendo +1 de bônus de moral nas jogadas de ataque e testes de resistência contra efeitos de medo, além de 1d8 pontos de vida temporários enquanto a magia permanecer ativa. Os aliados que veneram a mesma divindade do clérigo recebem os benefícios totais da ira justa. Eles adquirem um ataque corpo a corpo adicional a cada rodada, usando seu bônus de ataque mais favorável, e +2 de bônus de moral nas jogadas de dano e testes de resistência. Eles recebem 1d8 pontos de vida temporários adicionais (totalizando 2d8) e +3 de bônus de moral nos testes de resistência contra magias ou efeitos de ação mental. Quando a duração da magia expirar, todas as criaturas afetadas pela versão completa da ira justa ficarão fatigadas (-2 de Força, -2 de Destreza, não podem correr ou realizar Investidas) durante 10 minutos."}'::jsonb),
('dnd35.defensores.spell.defensores-laco-telepatico-menor','Laço Telepático Menor','Laço Telepático Menor','Você forja um vínculo telepático com outra criatura que tenha um valor de Inteligência 6 ou superior. Essa ligação somente pode ser estabelecida com um alvo disposto. É possível se comunicar por telepatia usando esse vínculo; o idioma não é uma limitação. Nenhum poder ou influência especial é estabelecido como resultado do laço telepático. Depois da conjuração da magia, o vínculo estará sempre ativo, não importa a distância (mas não viajará entre planos diferentes).',3,false,false,ARRAY['Clr 3, Mente 3']::text[],'1 ação','9 m','Alvos: Você e uma criatura voluntária a 9 m ou menos.','10 minutos/nível','Nenhum',ARRAY['Adivinhação [ação mental]']::text[],'v35-defensores','D&D 3.5 — Defensores da Fé',81,'dnd35','{"id":"defensores-laco-telepatico-menor","name":"Laço Telepático Menor","school":"Adivinhação [ação mental]","level":"Clr 3, Mente 3","components":"V, S","castingTime":"1 ação","range":"9 m","target":"Alvos: Você e uma criatura voluntária a 9 m ou menos.","duration":"10 minutos/nível","savingThrow":"Nenhum","spellResistance":"Não","description":"Você forja um vínculo telepático com outra criatura que tenha um valor de Inteligência 6 ou superior. Essa ligação somente pode ser estabelecida com um alvo disposto. É possível se comunicar por telepatia usando esse vínculo; o idioma não é uma limitação. Nenhum poder ou influência especial é estabelecido como resultado do laço telepático. Depois da conjuração da magia, o vínculo estará sempre ativo, não importa a distância (mas não viajará entre planos diferentes)."}'::jsonb),
('dnd35.defensores.spell.defensores-maldicao-da-licantropia','Maldição da Licantropia','Maldição da Licantropia','É possível infectar temporariamente um humanóide tocado com a maldição da licantropia. Caso a vítima fracasse no teste de resistência, ela contrairá a maldição, que se manifestará na próxima lua cheia. Diferente das outras formas de licantropia, o efeito dessa magia pode ser anulado por remover maldição ou cancelar encantamento. O conjurador pode induzir qualquer tipo de licantropia comum (e os clérigos malignos freqüentemente experimentam novos tipos). A forma animal do licantropo pode variar entre qualquer predador conhecido, desde um cachorro pequeno até um urso grande. O elemento usado como componente material determina a forma animal da vítima (mais informações sobre licantropia podem ser encontradas no Apêndice 3 do Livro dos Monstros).',6,false,false,ARRAY['Pestilência 6']::text[],'1 ação','Toque','Alvo: Humanóide tocado','Permanente (veja texto)','Fortitude anula',ARRAY['Necromancia']::text[],'v35-defensores','D&D 3.5 — Defensores da Fé',81,'dnd35','{"id":"defensores-maldicao-da-licantropia","name":"Maldição da Licantropia","school":"Necromancia","level":"Pestilência 6","components":"V, S, M, FD","castingTime":"1 ação","range":"Toque","target":"Alvo: Humanóide tocado","duration":"Permanente (veja texto)","savingThrow":"Fortitude anula","spellResistance":"Sim","description":"É possível infectar temporariamente um humanóide tocado com a maldição da licantropia. Caso a vítima fracasse no teste de resistência, ela contrairá a maldição, que se manifestará na próxima lua cheia. Diferente das outras formas de licantropia, o efeito dessa magia pode ser anulado por remover maldição ou cancelar encantamento. O conjurador pode induzir qualquer tipo de licantropia comum (e os clérigos malignos freqüentemente experimentam novos tipos). A forma animal do licantropo pode variar entre qualquer predador conhecido, desde um cachorro pequeno até um urso grande. O elemento usado como componente material determina a forma animal da vítima (mais informações sobre licantropia podem ser encontradas no Apêndice 3 do Livro dos Monstros).","materialComponent":"Uma gota de sangue do animal."}'::jsonb),
('dnd35.defensores.spell.defensores-maldicao-dos-brutos','Maldição dos Brutos','Maldição dos Brutos','Você concede +1 de bônus de aprimoramento por nível do conjurador para uma habilidade física da criatura tocada (Força, Constituição ou Destreza). Entretanto, isso reduz temporariamente a Inteligência e o Carisma do alvo (ambos) na mesma quantidade de pontos fornecida pela magia. Caso isso reduza qualquer habilidade para 3, a magia será anulada. Portanto, um clérigo de 5º nível poderia conjurar maldição dos brutos sobre um bárbaro para aumentar a sua Força em 4 pontos, mas reduziria sua Inteligência e o Carisma em 4 pontos. Se a Inteligência ou o Carisma original do bárbaro for 6, a magia não surtirá efeito.',3,false,false,ARRAY['Clr 3, Pal 2']::text[],'1 ação','Toque','Alvo: Criatura tocada','1 rodada/nível','Fortitude anula',ARRAY['Transmutação']::text[],'v35-defensores','D&D 3.5 — Defensores da Fé',81,'dnd35','{"id":"defensores-maldicao-dos-brutos","name":"Maldição dos Brutos","school":"Transmutação","level":"Clr 3, Pal 2","components":"V, S","castingTime":"1 ação","range":"Toque","target":"Alvo: Criatura tocada","duration":"1 rodada/nível","savingThrow":"Fortitude anula","spellResistance":"Sim","description":"Você concede +1 de bônus de aprimoramento por nível do conjurador para uma habilidade física da criatura tocada (Força, Constituição ou Destreza). Entretanto, isso reduz temporariamente a Inteligência e o Carisma do alvo (ambos) na mesma quantidade de pontos fornecida pela magia. Caso isso reduza qualquer habilidade para 3, a magia será anulada. Portanto, um clérigo de 5º nível poderia conjurar maldição dos brutos sobre um bárbaro para aumentar a sua Força em 4 pontos, mas reduziria sua Inteligência e o Carisma em 4 pontos. Se a Inteligência ou o Carisma original do bárbaro for 6, a magia não surtirá efeito."}'::jsonb),
('dnd35.defensores.spell.defensores-mascara-bestial','Máscara Bestial','Máscara Bestial','Esta magia disfarça o alvo de forma que os outros animais ou bestas o considerem um de sua espécie. Por exemplo, um indivíduo disfarçado como um lobo por essa sensação conseguiria se deslocar em meio a uma alcatéia livremente. É preciso determinar a forma do animal no momento da conjuração; caso ela seja uma categoria de tamanho maior ou duas categorias menor que o animal original, a magia fracassará. Essa ilusão afeta os sentidos dos animais e das bestas: visão, audição, olfato e tato. A magia não permite comunicação com os animais ou bestas, nem concede ao alvo quaisquer características da forma animal.',2,false,false,ARRAY['Mestre das Feras 2, Drd 2']::text[],'1 ação','Toque','Alvo: Criatura viva tocada','5 minutos + 1 minuto/nível','Vontade desacredita',ARRAY['Ilusão (Sensação)']::text[],'v35-defensores','D&D 3.5 — Defensores da Fé',81,'dnd35','{"id":"defensores-mascara-bestial","name":"Máscara Bestial","school":"Ilusão (Sensação)","level":"Mestre das Feras 2, Drd 2","components":"V, S","castingTime":"1 ação","range":"Toque","target":"Alvo: Criatura viva tocada","duration":"5 minutos + 1 minuto/nível","savingThrow":"Vontade desacredita","spellResistance":"Sim","description":"Esta magia disfarça o alvo de forma que os outros animais ou bestas o considerem um de sua espécie. Por exemplo, um indivíduo disfarçado como um lobo por essa sensação conseguiria se deslocar em meio a uma alcatéia livremente. É preciso determinar a forma do animal no momento da conjuração; caso ela seja uma categoria de tamanho maior ou duas categorias menor que o animal original, a magia fracassará. Essa ilusão afeta os sentidos dos animais e das bestas: visão, audição, olfato e tato. A magia não permite comunicação com os animais ou bestas, nem concede ao alvo quaisquer características da forma animal."}'::jsonb),
('dnd35.defensores.spell.defensores-mira-abencoada','Mira Abençoada','Mira Abençoada','Esta magia concede aos aliados afetados +2 de bônus de moral em todas as jogadas de ataque à distância.',3,false,false,ARRAY['Clr 3, Pal 2']::text[],'1 ação','18 m','Efeito: Dispersão de 18 m de raio, centrada no conjurador','Concentração','Vontade anula (inofensivo)',ARRAY['Adivinhação']::text[],'v35-defensores','D&D 3.5 — Defensores da Fé',81,'dnd35','{"id":"defensores-mira-abencoada","name":"Mira Abençoada","school":"Adivinhação","level":"Clr 3, Pal 2","components":"V, S","castingTime":"1 ação","range":"18 m","target":"Efeito: Dispersão de 18 m de raio, centrada no conjurador","duration":"Concentração","savingThrow":"Vontade anula (inofensivo)","spellResistance":"Não","description":"Esta magia concede aos aliados afetados +2 de bônus de moral em todas as jogadas de ataque à distância."}'::jsonb),
('dnd35.defensores.spell.defensores-onda-de-lodo','Onda de Lodo','Onda de Lodo','Você cria uma onda de lodo verde, que surge no ponto de origem escolhido e se espalha violentamente até o limite da área da magia. A onda espirra e respinga conforme se propaga; parte dela subirá às paredes ou atingirá o teto. O limo verde disseca a carne e derrete materiais orgânicos com o simples contato e é capaz de dissolver metais. Cada criatura é atingida por um pedaço de limo verde para cada 1,5 m da sua Face. A cada rodada, um pedaço de limo causa 1d6 pontos de dano temporário na Constituição da criatura afetada, enquanto dissolve sua carne. Contra madeira ou metal, ele causa 2d6 pontos de dano por rodada, ignorando a dureza do metal, mas não da madeira. O lodo não danifica rochas. Na primeira rodada de contato, é possível arrancar o limo de uma criatura (provavelmente destruindo o instrumento utilizado), mas depois ele precisará ser congelado, queimado ou decepado (causando dano na vítima também). O frio ou o calor extremos, a luz do sol e a magia remover doenças conseguem destruir o limo verde. Diferente do limo verde comum, a substância criada por meio dessa magia evapora gradualmente, desaparecendo no final da duração.',7,false,false,ARRAY['Clr 7, Drd 7']::text[],'1 ação','Curto (7,5 m + 1,5 m/2 níveis)','Área: Dispersão de 4,5 m de raio','1 rodada/nível','Reflexos evita',ARRAY['Conjuração (Invocação)']::text[],'v35-defensores','D&D 3.5 — Defensores da Fé',81,'dnd35','{"id":"defensores-onda-de-lodo","name":"Onda de Lodo","school":"Conjuração (Invocação)","level":"Clr 7, Drd 7","components":"V, S, M","castingTime":"1 ação","range":"Curto (7,5 m + 1,5 m/2 níveis)","target":"Área: Dispersão de 4,5 m de raio","duration":"1 rodada/nível","savingThrow":"Reflexos evita","spellResistance":"Não","description":"Você cria uma onda de lodo verde, que surge no ponto de origem escolhido e se espalha violentamente até o limite da área da magia. A onda espirra e respinga conforme se propaga; parte dela subirá às paredes ou atingirá o teto. O limo verde disseca a carne e derrete materiais orgânicos com o simples contato e é capaz de dissolver metais. Cada criatura é atingida por um pedaço de limo verde para cada 1,5 m da sua Face. A cada rodada, um pedaço de limo causa 1d6 pontos de dano temporário na Constituição da criatura afetada, enquanto dissolve sua carne. Contra madeira ou metal, ele causa 2d6 pontos de dano por rodada, ignorando a dureza do metal, mas não da madeira. O lodo não danifica rochas. Na primeira rodada de contato, é possível arrancar o limo de uma criatura (provavelmente destruindo o instrumento utilizado), mas depois ele precisará ser congelado, queimado ou decepado (causando dano na vítima também). O frio ou o calor extremos, a luz do sol e a magia remover doenças conseguem destruir o limo verde. Diferente do limo verde comum, a substância criada por meio dessa magia evapora gradualmente, desaparecendo no final da duração.","materialComponent":"Algumas gotas de água parada e podre."}'::jsonb),
('dnd35.defensores.spell.defensores-praga-dos-ratos','Praga dos Ratos','Praga dos Ratos','Uma ninhada de ratos atrozes ataca incessantemente todas as criaturas vivas numa dispersão de 6 m, causando dano e transmitindo a febre do esgoto (veja a pág. 74 do Livro do Mestre). Uma criatura em meio aos ratos que não realize nenhuma ação, exceto combater os roedores, sofrerá 1d4 pontos de dano e deverá obter sucesso num teste de resistência de Fortitude (CD 15 + modificador de Inteligência do conjurador) para não contrair a doença. Uma criatura em meio a ninhada que realizar qualquer outra ação, inclusive uma tentativa de fuga, sofrerá 1d4 pontos de dano por nível do conjurador, e deverá realizar o teste de resistência com -4 de penalidade para evitar a febre do esgoto. É impossível conjurar magias ou manter a concentração em meio a ninhada de ratos. Os ataques dos ratos são comuns (mas não mágicos), portanto as criaturas incorpóreas, com redução de dano e outras formas de defesa são capazes de evitar o dano. A doença é mágica e transmitida pelo toque; qualquer criatura corpórea na área que seja suscetível a doenças mágicas poderá contraí-la. A ninhada não pode ser combatida efetivamente com armas, mas o fogo e efeitos de dano de área podem forçá-la a fugir. Os ratos começarão a se afastar quando a ninhada sofrer 8 pontos de dano por nível do conjurador de ataques desse tipo. Uma névoa fétida e magias ou efeitos similares dispersarão a ninhada imediatamente. Como uma ação equivalente a movimento, o conjurador pode direcionar a ninhada para que ela percorra até 12 m por rodada.',5,false,false,ARRAY['Pestilência 5']::text[],'1 rodada completa','Médio (30 m + 3 m/nível)','Efeito: Ninhada de ratos atrozes numa dispersão de 6 m','1 rodada/nível','Nenhum',ARRAY['Conjuração (Invocação)']::text[],'v35-defensores','D&D 3.5 — Defensores da Fé',81,'dnd35','{"id":"defensores-praga-dos-ratos","name":"Praga dos Ratos","school":"Conjuração (Invocação)","level":"Pestilência 5","components":"V, S, FD","castingTime":"1 rodada completa","range":"Médio (30 m + 3 m/nível)","target":"Efeito: Ninhada de ratos atrozes numa dispersão de 6 m","duration":"1 rodada/nível","savingThrow":"Nenhum","spellResistance":"Sim (veja texto)","description":"Uma ninhada de ratos atrozes ataca incessantemente todas as criaturas vivas numa dispersão de 6 m, causando dano e transmitindo a febre do esgoto (veja a pág. 74 do Livro do Mestre). Uma criatura em meio aos ratos que não realize nenhuma ação, exceto combater os roedores, sofrerá 1d4 pontos de dano e deverá obter sucesso num teste de resistência de Fortitude (CD 15 + modificador de Inteligência do conjurador) para não contrair a doença. Uma criatura em meio a ninhada que realizar qualquer outra ação, inclusive uma tentativa de fuga, sofrerá 1d4 pontos de dano por nível do conjurador, e deverá realizar o teste de resistência com -4 de penalidade para evitar a febre do esgoto. É impossível conjurar magias ou manter a concentração em meio a ninhada de ratos. Os ataques dos ratos são comuns (mas não mágicos), portanto as criaturas incorpóreas, com redução de dano e outras formas de defesa são capazes de evitar o dano. A doença é mágica e transmitida pelo toque; qualquer criatura corpórea na área que seja suscetível a doenças mágicas poderá contraí-la. A ninhada não pode ser combatida efetivamente com armas, mas o fogo e efeitos de dano de área podem forçá-la a fugir. Os ratos começarão a se afastar quando a ninhada sofrer 8 pontos de dano por nível do conjurador de ataques desse tipo. Uma névoa fétida e magias ou efeitos similares dispersarão a ninhada imediatamente. Como uma ação equivalente a movimento, o conjurador pode direcionar a ninhada para que ela percorra até 12 m por rodada."}'::jsonb),
('dnd35.defensores.spell.defensores-raio-de-gloria','Raio de Glória','Raio de Glória','Ao conjurar esta magia, você projeta um raio de energia advinda do Plano de Energia Positiva contra uma criatura. É preciso obter sucesso numa jogada de ataque de toque à distância para atingir o alvo. A criatura atingida sofre um dano variável, dependendo de seu plano de existência natal e seu nível: Plano Material, Plano Elemental, extra-planar neutro: dano máximo 1d6/2 níveis, dano base 7d6. Plano de Energia Negativa, extra-planar maligno, mortos-vivos: dano máximo 1d6/nível, dano base 15d6. Plano de Energia Positiva, extra-planar bom: — (sem dano).',6,false,false,ARRAY['Glória 6']::text[],'1 ação','Curto (7,5 m + 1,5 m/2 níveis)','Efeito: Raio','Instantânea','Nenhum',ARRAY['Evocação [Bem]']::text[],'v35-defensores','D&D 3.5 — Defensores da Fé',81,'dnd35','{"id":"defensores-raio-de-gloria","name":"Raio de Glória","school":"Evocação [Bem]","level":"Glória 6","components":"V, S, FD","castingTime":"1 ação","range":"Curto (7,5 m + 1,5 m/2 níveis)","target":"Efeito: Raio","duration":"Instantânea","savingThrow":"Nenhum","spellResistance":"Sim","description":"Ao conjurar esta magia, você projeta um raio de energia advinda do Plano de Energia Positiva contra uma criatura. É preciso obter sucesso numa jogada de ataque de toque à distância para atingir o alvo. A criatura atingida sofre um dano variável, dependendo de seu plano de existência natal e seu nível: Plano Material, Plano Elemental, extra-planar neutro: dano máximo 1d6/2 níveis, dano base 7d6. Plano de Energia Negativa, extra-planar maligno, mortos-vivos: dano máximo 1d6/nível, dano base 15d6. Plano de Energia Positiva, extra-planar bom: — (sem dano)."}'::jsonb),
('dnd35.defensores.spell.defensores-raios-de-malevolencia','Raios de Malevolência','Raios de Malevolência','Essa magia permite que o conjurador dispare um raio a cada rodada. O raio pasma uma criatura viva, envolvendo sua mente de forma que ela não consiga realizar qualquer ação durante 1d3 rodadas. A criatura não está atordoada (logo, os atacantes não adquirem vantagens especiais contra ela), mas não consegue se mover, conjurar magias, usar habilidades mentais e ações semelhantes.',5,false,false,ARRAY['Insanidade 5']::text[],'1 ação','Médio (30 m + 3 m/nível)','Efeito: Raio','1 rodada/nível','Vontade anula',ARRAY['Encantamento [ação mental]']::text[],'v35-defensores','D&D 3.5 — Defensores da Fé',81,'dnd35','{"id":"defensores-raios-de-malevolencia","name":"Raios de Malevolência","school":"Encantamento [ação mental]","level":"Insanidade 5","components":"V, S","castingTime":"1 ação","range":"Médio (30 m + 3 m/nível)","target":"Efeito: Raio","duration":"1 rodada/nível","savingThrow":"Vontade anula","spellResistance":"Sim","description":"Essa magia permite que o conjurador dispare um raio a cada rodada. O raio pasma uma criatura viva, envolvendo sua mente de forma que ela não consiga realizar qualquer ação durante 1d3 rodadas. A criatura não está atordoada (logo, os atacantes não adquirem vantagens especiais contra ela), mas não consegue se mover, conjurar magias, usar habilidades mentais e ações semelhantes."}'::jsonb),
('dnd35.defensores.spell.defensores-rajada-de-facas','Rajada de Facas','Rajada de Facas','A umidade do ar estala, condensa e forma pequenas adagas, que são disparadas da ponta de seus dedos, atingindo qualquer criatura na área afetada. Cada criatura na área sofre 1d6 pontos de dano, mais 1 ponto adicional por nível do conjurador, até o limite de +5. Um teste de resistência de Reflexos bem-sucedido reduz o dano à metade.',2,false,false,ARRAY['Clr 2']::text[],'1 ação','Curto (7,5 m + 1,5 m/2 níveis)','Área: Cone','Instantânea','Reflexos reduz o dano à metade',ARRAY['Evocação']::text[],'v35-defensores','D&D 3.5 — Defensores da Fé',81,'dnd35','{"id":"defensores-rajada-de-facas","name":"Rajada de Facas","school":"Evocação","level":"Clr 2","components":"V, S","castingTime":"1 ação","range":"Curto (7,5 m + 1,5 m/2 níveis)","target":"Área: Cone","duration":"Instantânea","savingThrow":"Reflexos reduz o dano à metade","spellResistance":"Sim","description":"A umidade do ar estala, condensa e forma pequenas adagas, que são disparadas da ponta de seus dedos, atingindo qualquer criatura na área afetada. Cada criatura na área sofre 1d6 pontos de dano, mais 1 ponto adicional por nível do conjurador, até o limite de +5. Um teste de resistência de Reflexos bem-sucedido reduz o dano à metade."}'::jsonb),
('dnd35.defensores.spell.defensores-rajada-de-espadas','Rajada de Espadas','Rajada de Espadas','A umidade do ar estala, condensa e forma pequenas espadas, que são disparadas da ponta de seus dedos, atingindo qualquer criatura na área afetada. Cada criatura na área sofre 1d8 pontos de dano, mais 1 ponto adicional por nível do conjurador, até o limite de +10. Um teste de resistência de Reflexos bem-sucedido reduz o dano à metade.',3,false,false,ARRAY['Clr 3']::text[],'1 ação','Curto (7,5 m + 1,5 m/2 níveis)','Efeito: Expansão de 1,5 m até o limite do alcance','Instantânea','Reflexos reduz o dano à metade',ARRAY['Evocação']::text[],'v35-defensores','D&D 3.5 — Defensores da Fé',81,'dnd35','{"id":"defensores-rajada-de-espadas","name":"Rajada de Espadas","school":"Evocação","level":"Clr 3","components":"V, S","castingTime":"1 ação","range":"Curto (7,5 m + 1,5 m/2 níveis)","target":"Efeito: Expansão de 1,5 m até o limite do alcance","duration":"Instantânea","savingThrow":"Reflexos reduz o dano à metade","spellResistance":"Sim","description":"A umidade do ar estala, condensa e forma pequenas espadas, que são disparadas da ponta de seus dedos, atingindo qualquer criatura na área afetada. Cada criatura na área sofre 1d8 pontos de dano, mais 1 ponto adicional por nível do conjurador, até o limite de +10. Um teste de resistência de Reflexos bem-sucedido reduz o dano à metade."}'::jsonb),
('dnd35.defensores.spell.defensores-recital','Recital','Recital','Recitando uma passagem ou declaração sagrada, o clérigo invoca a benção de sua divindade sobre si e seus aliados, enquanto causa confusão e fraqueza entre seus inimigos. A magia afeta todos os aliados e inimigos dentro da área da magia no momento da conjuração. Seus aliados recebem +2 de bônus de sorte nas jogadas de ataque e testes de resistência — ou +3 bônus de sorte caso venerem a mesma divindade. Os adversários sofrem -2 de penalidade de sorte nas jogadas de ataque e testes de resistência. Depois da conjuração, o clérigo poderá realizar quaisquer ações que desejar; não é necessário se concentrar.',4,false,false,ARRAY['Clr 4']::text[],'1 ação','18 m','Área: Todos os aliados e inimigos numa explosão de 18 m de raio, centrada no conjurador','1 rodada/nível','Nenhum',ARRAY['Conjuração (Criação)']::text[],'v35-defensores','D&D 3.5 — Defensores da Fé',81,'dnd35','{"id":"defensores-recital","name":"Recital","school":"Conjuração (Criação)","level":"Clr 4","components":"V, S, FD","castingTime":"1 ação","range":"18 m","target":"Área: Todos os aliados e inimigos numa explosão de 18 m de raio, centrada no conjurador","duration":"1 rodada/nível","savingThrow":"Nenhum","spellResistance":"Sim","description":"Recitando uma passagem ou declaração sagrada, o clérigo invoca a benção de sua divindade sobre si e seus aliados, enquanto causa confusão e fraqueza entre seus inimigos. A magia afeta todos os aliados e inimigos dentro da área da magia no momento da conjuração. Seus aliados recebem +2 de bônus de sorte nas jogadas de ataque e testes de resistência — ou +3 bônus de sorte caso venerem a mesma divindade. Os adversários sofrem -2 de penalidade de sorte nas jogadas de ataque e testes de resistência. Depois da conjuração, o clérigo poderá realizar quaisquer ações que desejar; não é necessário se concentrar.","materialComponent":"Foco Divino: Além do seu símbolo sagrado, essa magia requer um texto sagrado como foco divino."}'::jsonb),
('dnd35.defensores.spell.defensores-sacrificio-divino','Sacrifício Divino','Sacrifício Divino','O paladino consegue sacrificar energia vital para aumentar o dano que ele causa. Uma vez a cada rodada, como uma ação livre, você pode sacrificar até 10 pontos de vida (isso não provoca um ataque de oportunidade); para cada 2 pontos sacrificados, seu próximo ataque bem-sucedido causará +1d6 pontos de dano, até o limite de 5d6 num único ataque. Sua capacidade para infligir esse dano adicional termina quando um ataque bem-sucedido é desferido ou quando a duração da magia expirar. É possível realizar esses sacrifícios enquanto a magia permanecer ativa, uma vez por rodada. Os pontos de vida perdidos são considerados dano normal. Por exemplo, um paladino de 8º nível conjura sacrifício divino com duração de 4 rodadas; caso ele sacrifique 10 pontos em cada rodada e acerte todos os seus ataques, ele perderá 40 pontos de vida e causará 20d6 pontos de dano adicionais.',1,false,false,ARRAY['Pal 1']::text[],'1 ação','Pessoal','Alvo: Você','1 rodada/nível','Nenhum',ARRAY['Evocação']::text[],'v35-defensores','D&D 3.5 — Defensores da Fé',81,'dnd35','{"id":"defensores-sacrificio-divino","name":"Sacrifício Divino","school":"Evocação","level":"Pal 1","components":"V, S","castingTime":"1 ação","range":"Pessoal","target":"Alvo: Você","duration":"1 rodada/nível","savingThrow":"Nenhum","spellResistance":"Não","description":"O paladino consegue sacrificar energia vital para aumentar o dano que ele causa. Uma vez a cada rodada, como uma ação livre, você pode sacrificar até 10 pontos de vida (isso não provoca um ataque de oportunidade); para cada 2 pontos sacrificados, seu próximo ataque bem-sucedido causará +1d6 pontos de dano, até o limite de 5d6 num único ataque. Sua capacidade para infligir esse dano adicional termina quando um ataque bem-sucedido é desferido ou quando a duração da magia expirar. É possível realizar esses sacrifícios enquanto a magia permanecer ativa, uma vez por rodada. Os pontos de vida perdidos são considerados dano normal. Por exemplo, um paladino de 8º nível conjura sacrifício divino com duração de 4 rodadas; caso ele sacrifique 10 pontos em cada rodada e acerte todos os seus ataques, ele perderá 40 pontos de vida e causará 20d6 pontos de dano adicionais."}'::jsonb),
('dnd35.defensores.spell.defensores-tempestade-divina','Tempestade Divina','Tempestade Divina','Você cria um disco giratório de armas, do tipo favorito da sua divindade. Essas armas circulam em volta de um ponto central, formando uma barreira imóvel. Qualquer criatura que tente atravessar a tempestade divina sofrerá 1d6 pontos de dano, mais 2 pontos adicionais por nível do conjurador (máximo +20). Você escolhe o plano de rotação das armas: horizontal, vertical ou diagonal. As criaturas que estiverem dentro da área afetada no momento da conjuração podem evitar o dano caso obtenham sucesso num teste de resistência de Reflexos. Depois que a tempestade divina foi conjurada, qualquer criatura que tente entrar ou atravessar o disco sofrerá o dano automaticamente. Uma tempestade divina funciona como ½ cobertura (+4 na CA) para qualquer indivíduo do lado oposto.',4,false,false,ARRAY['Clr 4']::text[],'1 rodada completa','Curto (7,5 m + 1,5 m/2 níveis)','Efeito: Disco giratório de armas com até 9 m de raio','Concentração','Reflexo anula (veja texto)',ARRAY['Evocação']::text[],'v35-defensores','D&D 3.5 — Defensores da Fé',81,'dnd35','{"id":"defensores-tempestade-divina","name":"Tempestade Divina","school":"Evocação","level":"Clr 4","components":"V, S, FD","castingTime":"1 rodada completa","range":"Curto (7,5 m + 1,5 m/2 níveis)","target":"Efeito: Disco giratório de armas com até 9 m de raio","duration":"Concentração","savingThrow":"Reflexo anula (veja texto)","spellResistance":"Sim","description":"Você cria um disco giratório de armas, do tipo favorito da sua divindade. Essas armas circulam em volta de um ponto central, formando uma barreira imóvel. Qualquer criatura que tente atravessar a tempestade divina sofrerá 1d6 pontos de dano, mais 2 pontos adicionais por nível do conjurador (máximo +20). Você escolhe o plano de rotação das armas: horizontal, vertical ou diagonal. As criaturas que estiverem dentro da área afetada no momento da conjuração podem evitar o dano caso obtenham sucesso num teste de resistência de Reflexos. Depois que a tempestade divina foi conjurada, qualquer criatura que tente entrar ou atravessar o disco sofrerá o dano automaticamente. Uma tempestade divina funciona como ½ cobertura (+4 na CA) para qualquer indivíduo do lado oposto.","materialComponent":"Foco divino: Uma miniatura da arma da divindade numa corrente prateada."}'::jsonb),
('dnd35.defensores.spell.defensores-tolerancia-infinita','Tolerância Infinita','Tolerância Infinita','Essa magia torna as criaturas vivas praticamente imunes à fadiga ou exaustão. É necessário tocar cada criatura que será afetada pela tolerância infinita. Os benefícios abrangem: Tolerância: Este talento recebe +4 de bônus em qualquer teste feito para a realização de tarefas físicas prolongadas (correr, nadar, prender o fôlego, etc.). Bônus de moral: Os alvos recebem +4 de bônus de moral, cumulativo ao bônus do talento Tolerância. Esse bônus também é aplicado nos testes de resistência contra magias e efeitos mágicos que causem fraqueza, fadiga, exaustão ou debilitação. Atividade Prolongada: As criaturas afetadas podem executar até 12 horas de trabalho duro ou marcha forçada sem sofrer fadiga, ou continuar durante 16 horas e ficar fatigados em vez de exaustos (consulte Marcha Forçada, pág. 143 do Livro do Jogador, e exausto e fatigado, na pág. 84 do Livro do Mestre).',4,false,false,ARRAY['Clr 4']::text[],'1 rodada completa','Toque','Alvos: Uma criatura viva/nível','1 dia/nível','Nenhum',ARRAY['Transmutação']::text[],'v35-defensores','D&D 3.5 — Defensores da Fé',81,'dnd35','{"id":"defensores-tolerancia-infinita","name":"Tolerância Infinita","school":"Transmutação","level":"Clr 4","components":"V, S","castingTime":"1 rodada completa","range":"Toque","target":"Alvos: Uma criatura viva/nível","duration":"1 dia/nível","savingThrow":"Nenhum","spellResistance":"Sim","description":"Essa magia torna as criaturas vivas praticamente imunes à fadiga ou exaustão. É necessário tocar cada criatura que será afetada pela tolerância infinita. Os benefícios abrangem: Tolerância: Este talento recebe +4 de bônus em qualquer teste feito para a realização de tarefas físicas prolongadas (correr, nadar, prender o fôlego, etc.). Bônus de moral: Os alvos recebem +4 de bônus de moral, cumulativo ao bônus do talento Tolerância. Esse bônus também é aplicado nos testes de resistência contra magias e efeitos mágicos que causem fraqueza, fadiga, exaustão ou debilitação. Atividade Prolongada: As criaturas afetadas podem executar até 12 horas de trabalho duro ou marcha forçada sem sofrer fadiga, ou continuar durante 16 horas e ficar fatigados em vez de exaustos (consulte Marcha Forçada, pág. 143 do Livro do Jogador, e exausto e fatigado, na pág. 84 do Livro do Mestre)."}'::jsonb),
('dnd35.defensores.spell.defensores-toque-da-loucura','Toque da Loucura','Toque da Loucura','Você é capaz de pasmar uma criatura viva caso realize um ataque de toque bem-sucedido. Se a criatura não obtiver sucesso num teste de resistência de Vontade, sua mente ficará enevoada e ela não poderá realizar nenhuma ação durante 1 rodada por nível do conjurador. A criatura não está atordoada (logo, os atacantes não adquirem vantagens especiais contra ela), mas não consegue se mover, conjurar magias, usar habilidades mentais e ações semelhantes.',2,false,false,ARRAY['Insanidade 2']::text[],'1 ação','Toque','Alvo: Criatura tocada','1 rodada/nível','Vontade anula',ARRAY['Encantamento [ação mental]']::text[],'v35-defensores','D&D 3.5 — Defensores da Fé',81,'dnd35','{"id":"defensores-toque-da-loucura","name":"Toque da Loucura","school":"Encantamento [ação mental]","level":"Insanidade 2","components":"V, S","castingTime":"1 ação","range":"Toque","target":"Alvo: Criatura tocada","duration":"1 rodada/nível","savingThrow":"Vontade anula","spellResistance":"Sim","description":"Você é capaz de pasmar uma criatura viva caso realize um ataque de toque bem-sucedido. Se a criatura não obtiver sucesso num teste de resistência de Vontade, sua mente ficará enevoada e ela não poderá realizar nenhuma ação durante 1 rodada por nível do conjurador. A criatura não está atordoada (logo, os atacantes não adquirem vantagens especiais contra ela), mas não consegue se mover, conjurar magias, usar habilidades mentais e ações semelhantes."}'::jsonb),
('dnd35.defensores.spell.defensores-trama-de-espinhos','Trama de Espinhos','Trama de Espinhos','Essa magia obriga grama, ervas, arbustos e até mesmo pequenas árvores a criarem espinhos e então se enroscar, derrubar e aprisionar qualquer criatura dentro da área de efeito ou que tente atravessá-la, segurando-as. As criaturas que permanecerem imóveis estarão enredadas, mas não sofrerão nenhum efeito adicional ou ponto de dano. Caso tentem realizar qualquer ação (atacar, conjurar magias que exijam componentes somáticos, mover-se, etc.), elas sofrerão 1d4 pontos de dano dos espinhos, +1 ponto adicional por nível do conjurador, e precisarão obter sucesso num teste de resistência de Reflexos ou ficarão enredadas. Um personagem enredado que tente conjurar uma magia deverá realizar um teste de Concentração (CD 15 + nível da magia + dano sofrido) ou perderá a magia. As criaturas enredadas sofrem -2 de penalidade nas suas jogadas de ataque, -4 de penalidade na Destreza efetiva e não podem se mover. Elas podem tentar se libertar e percorrer metade de seu deslocamento ou usarem uma ação de rodada completa para realizar um teste de Força ou Arte da Fuga (CD 20). Uma criatura que obtenha sucesso no teste de resistência de Reflexos não estará enredada, mas só poderá percorrer metade de seu deslocamento na área afetada e ainda sofrerá o dano indicado. A cada rodada, as plantas tentam novamente agarrar todas as criaturas que escaparam e ainda estão na área afetada. As plantas fornecem ¼ de cobertura para cada 1,5 m de distância entre duas criaturas na área — ½ depois de 3 m de trama de espinhos, ¾ para 4,5 m, e cobertura total para 6 m ou mais. Observação: O Mestre pode alterar os efeitos da magia de acordo com a natureza das plantas que estão enredando os personagens.',3,false,false,ARRAY['Clr 3, Drd 2, Rgr 2']::text[],'1 ação','Médio (30 m + 3 m/nível)','Área: Plantas em uma dispersão de 12 m de raio','1 minuto/nível','Veja texto',ARRAY['Transmutação']::text[],'v35-defensores','D&D 3.5 — Defensores da Fé',81,'dnd35','{"id":"defensores-trama-de-espinhos","name":"Trama de Espinhos","school":"Transmutação","level":"Clr 3, Drd 2, Rgr 2","components":"V, S, FD","castingTime":"1 ação","range":"Médio (30 m + 3 m/nível)","target":"Área: Plantas em uma dispersão de 12 m de raio","duration":"1 minuto/nível","savingThrow":"Veja texto","spellResistance":"Não","description":"Essa magia obriga grama, ervas, arbustos e até mesmo pequenas árvores a criarem espinhos e então se enroscar, derrubar e aprisionar qualquer criatura dentro da área de efeito ou que tente atravessá-la, segurando-as. As criaturas que permanecerem imóveis estarão enredadas, mas não sofrerão nenhum efeito adicional ou ponto de dano. Caso tentem realizar qualquer ação (atacar, conjurar magias que exijam componentes somáticos, mover-se, etc.), elas sofrerão 1d4 pontos de dano dos espinhos, +1 ponto adicional por nível do conjurador, e precisarão obter sucesso num teste de resistência de Reflexos ou ficarão enredadas. Um personagem enredado que tente conjurar uma magia deverá realizar um teste de Concentração (CD 15 + nível da magia + dano sofrido) ou perderá a magia. As criaturas enredadas sofrem -2 de penalidade nas suas jogadas de ataque, -4 de penalidade na Destreza efetiva e não podem se mover. Elas podem tentar se libertar e percorrer metade de seu deslocamento ou usarem uma ação de rodada completa para realizar um teste de Força ou Arte da Fuga (CD 20). Uma criatura que obtenha sucesso no teste de resistência de Reflexos não estará enredada, mas só poderá percorrer metade de seu deslocamento na área afetada e ainda sofrerá o dano indicado. A cada rodada, as plantas tentam novamente agarrar todas as criaturas que escaparam e ainda estão na área afetada. As plantas fornecem ¼ de cobertura para cada 1,5 m de distância entre duas criaturas na área — ½ depois de 3 m de trama de espinhos, ¾ para 4,5 m, e cobertura total para 6 m ou mais. Observação: O Mestre pode alterar os efeitos da magia de acordo com a natureza das plantas que estão enredando os personagens."}'::jsonb),
('dnd35.defensores.spell.defensores-visao-climatica','Visão Climática','Visão Climática','Você é capaz de prever o clima da próxima semana com precisão. Caso alguma força sobrenatural esteja afetando o clima, a visão climática lhe revelará as informações possíveis de obter com detectar magia.',4,false,false,ARRAY['Clr 4, Drd 3']::text[],'1 hora','1,5 km de raio + 1,5 km/nível','Área: 1,5 km de raio + 1,5 km/nível, centrado no conjurador','Instantânea','Nenhum',ARRAY['Adivinhação']::text[],'v35-defensores','D&D 3.5 — Defensores da Fé',81,'dnd35','{"id":"defensores-visao-climatica","name":"Visão Climática","school":"Adivinhação","level":"Clr 4, Drd 3","components":"V, S, M, FD","castingTime":"1 hora","range":"1,5 km de raio + 1,5 km/nível","target":"Área: 1,5 km de raio + 1,5 km/nível, centrado no conjurador","duration":"Instantânea","savingThrow":"Nenhum","spellResistance":"Não","description":"Você é capaz de prever o clima da próxima semana com precisão. Caso alguma força sobrenatural esteja afetando o clima, a visão climática lhe revelará as informações possíveis de obter com detectar magia.","materialComponent":"Incenso. Foco Divino: Um artifício de observação de qualquer tipo (tigela, espelho, bola de cristal, etc.)."}'::jsonb),
('dnd35.defensores.spell.defensores-visao-sequencial','Visão Seqüencial','Visão Seqüencial','O conjurador pode utilizar a visão de outra criatura no lugar da sua. Embora essa magia não lhe forneça nenhum controle sobre a criatura afetada, sempre que ela estiver em contato físico com outro ser vivo, será possível transferir suas capacidades sensoriais para o novo alvo. Desta forma, seu sensor conseguiria se infiltrar numa área bem protegida. A cada rodada, durante o seu turno, o conjurador pode escolher entre sua visão normal e as percepções da criatura como uma ação livre.',3,false,false,ARRAY['Clr 3, Drd 4']::text[],'1 ação','Toque','Alvo: Criatura viva tocada','1 hora/nível','Vontade anula',ARRAY['Adivinhação']::text[],'v35-defensores','D&D 3.5 — Defensores da Fé',81,'dnd35','{"id":"defensores-visao-sequencial","name":"Visão Seqüencial","school":"Adivinhação","level":"Clr 3, Drd 4","components":"V, S","castingTime":"1 ação","range":"Toque","target":"Alvo: Criatura viva tocada","duration":"1 hora/nível","savingThrow":"Vontade anula","spellResistance":"Sim","description":"O conjurador pode utilizar a visão de outra criatura no lugar da sua. Embora essa magia não lhe forneça nenhum controle sobre a criatura afetada, sempre que ela estiver em contato físico com outro ser vivo, será possível transferir suas capacidades sensoriais para o novo alvo. Desta forma, seu sensor conseguiria se infiltrar numa área bem protegida. A cada rodada, durante o seu turno, o conjurador pode escolher entre sua visão normal e as percepções da criatura como uma ação livre."}'::jsonb),
('dnd35.defensores.spell.defensores-zefiro-celestial','Zéfiro Celestial','Zéfiro Celestial','Zéfiro celestial cria uma proteção imóvel contra criaturas do fogo, como gigantes do fogo. As criaturas do fogo que tentarem entrar ou permanecer na área sofrem 1d4 pontos de dano por nível do conjurador, até o limite de 5d4 (Fortitude para reduzir o dano à metade). Esse dano será infligido a cada rodada que a criatura permanecer na área e o teste de Fortitude deve ser realizado de acordo.',2,false,false,ARRAY['Clr 2']::text[],'1 ação','4,5 m','Área: Emanação de 4,5 m de raio, centrada no conjurador','1 rodada/nível','Fortitude para reduzir à metade',ARRAY['Abjuração']::text[],'v35-defensores','D&D 3.5 — Defensores da Fé',81,'dnd35','{"id":"defensores-zefiro-celestial","name":"Zéfiro Celestial","school":"Abjuração","level":"Clr 2","components":"V, S","castingTime":"1 ação","range":"4,5 m","target":"Área: Emanação de 4,5 m de raio, centrada no conjurador","duration":"1 rodada/nível","savingThrow":"Fortitude para reduzir à metade","spellResistance":"Sim","description":"Zéfiro celestial cria uma proteção imóvel contra criaturas do fogo, como gigantes do fogo. As criaturas do fogo que tentarem entrar ou permanecer na área sofrem 1d4 pontos de dano por nível do conjurador, até o limite de 5d4 (Fortitude para reduzir o dano à metade). Esse dano será infligido a cada rodada que a criatura permanecer na área e o teste de Fortitude deve ser realizado de acordo."}'::jsonb),
('dnd35.defensores.spell.defensores-zelo','Zelo','Zelo','Você invoca um escudo divino para protegê-lo enquanto se aproxima de um adversário pré-determinado. Escolha um oponente conforme lança esta magia. Você recebe +4 de bônus de deflexão na CA contra todos os ataques de oportunidade de outros inimigos, exceto o adversário selecionado. Além disso, você será capaz de ultrapassar seus oponentes como se estes fossem seus aliados enquanto a magia permanecer ativa, mas seu movimento deve ter a intenção de se aproximar do inimigo selecionado no momento da conjuração.',2,false,false,ARRAY['Pal 2']::text[],'1 ação','Pessoal','Alvo: Você','1 rodada/nível','Nenhum',ARRAY['Abjuração']::text[],'v35-defensores','D&D 3.5 — Defensores da Fé',81,'dnd35','{"id":"defensores-zelo","name":"Zelo","school":"Abjuração","level":"Pal 2","components":"V, S","castingTime":"1 ação","range":"Pessoal","target":"Alvo: Você","duration":"1 rodada/nível","savingThrow":"Nenhum","spellResistance":"Não","description":"Você invoca um escudo divino para protegê-lo enquanto se aproxima de um adversário pré-determinado. Escolha um oponente conforme lança esta magia. Você recebe +4 de bônus de deflexão na CA contra todos os ataques de oportunidade de outros inimigos, exceto o adversário selecionado. Além disso, você será capaz de ultrapassar seus oponentes como se estes fossem seus aliados enquanto a magia permanecer ativa, mas seu movimento deve ter a intenção de se aproximar do inimigo selecionado no momento da conjuração."}'::jsonb)
